export default "NT\\\": \\\"http://localhost:4318\\\", \\\"OTEL_TRACES_EXPORTER\\\": \\\"none\\\"},\\n    )\\n    assert result[\\\"provider\\\"] == \\\"ProxyTracerProvider\\\"\\n\\n\\ndef test_per_signal_protocol_takes_precedence():\\n    result = run_probe(\\n        {\\n            \\\"OTEL_EXPORTER_OTLP_ENDPOINT\\\": \\\"http://localhost:4318\\\",\\n            \\\"OTEL_EXPORTER_OTLP_PROTOCOL\\\": \\\"http/protobuf\\\",\\n            \\\"OTEL_EXPORTER_OTLP_TRACES_PROTOCOL\\\": \\\"grpc\\\",\\n        },\\n    )\\n    assert \\\".proto.grpc.\\\" in result[\\\"exporters\\\"][0]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/telemetry_writer/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/telemetry_writer/test_service.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1f83ed497e1c4eb25cf4c95a0349b7c2feeeb6f9ee605a9b15c4d5b355f0bbf5\",\"content\":\"\\\"\\\"\\\"Tests for TelemetryWriterService.\\n\\nThe service is exercised end-to-end against a real in-memory SQLite database\\n(no mocking of the persistence layer). We bypass ``start()`` in most tests so\\nwe don't have to bring up the entire langflow service manager \u2014 instead each\\ntest wires up the writer's internals directly against the test\\n``async_session`` fixture's engine.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport shutil\\nimport tempfile\\nimport warnings\\nfrom pathlib import Path\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.transactions.model import TransactionBase, TransactionTable\\nfrom langflow.services.database.models.vertex_builds.model import VertexBuildBase, VertexBuildTable\\nfrom langflow.services.telemetry_writer.service import (\\n    _FAILURE_ESCALATION_THRESHOLD,\\n    TelemetryWriterService,\\n    _write_owner_file,\\n)\\nfrom sqlalchemy import func, select\\nfrom sqlalchemy.ext.asyncio import AsyncSession, async_sessionmaker, create_async_engine\\nfrom sqlalchemy.pool import StaticPool\\nfrom sqlmodel import SQLModel\\n\\n\\nclass _FakeSettings:\\n    \\\"\\\"\\\"Mutable settings stand-in.\\n\\n    Real ``Settings`` is a pydantic-settings model whose constructor kwargs are\\n    overridden by env-var sources; tests can't reliably set fields through it.\\n    A plain object with the attributes the writer reads via ``getattr`` is\\n    sufficient and side-steps that quirk.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, **overrides):\\n        defaults = {\\n            \\\"telemetry_writer_enabled\\\": True,\\n            \\\"telemetry_writer_batch_size\\\": 200,\\n            \\\"telemetry_writer_flush_interval_s\\\": 0.5,\\n            \\\"telemetry_writer_cleanup_interval_s\\\": 60,\\n            \\\"telemetry_writer_max_queue\\\": 100_000,\\n            \\\"telemetry_writer_outbox_dir\\\": None,\\n            \\\"telemetry_writer_shutdown_drain_s\\\": 5.0,\\n            \\\"telemetry_writer_size_strategy\\\": \\\"count\\\",\\n            \\\"telemetry_writer_batch_size_bytes\\\": 262_144,\\n            \\\"telemetry_writer_max_queue_bytes\\\": 209_715_200,\\n            \\\"max_transactions_to_keep\\\": 3000,\\n            \\\"max_vertex_builds_to_keep\\\": 3000,\\n            \\\"max_vertex_builds_per_vertex\\\": 50,\\n        }\\n        for key, value in {**defaults, **overrides}.items():\\n            setattr(self, key, value)\\n\\n\\nclass _FakeSettingsService:\\n    def __init__(self, **overrides):\\n        self.settings = _FakeSettings(**overrides)\\n\\n\\ndef _build_writer(settings_overrides=None) -> TelemetryWriterService:\\n    return TelemetryWriterService(_FakeSettingsService(**(settings_overrides or {})))\\n\\n\\ndef _make_transaction_row(flow_id, vertex_id=\\\"v1\\\") -> dict:\\n    base = TransactionBase(\\n        vertex_id=vertex_id,\\n        target_id=None,\\n        inputs={\\\"x\\\": 1},\\n        outputs={\\\"y\\\": 2},\\n        status=\\\"success\\\",\\n        error=None,\\n        flow_id=flow_id,\\n    )\\n    return TransactionTable(**base.model_dump()).model_dump(mode=\\\"python\\\")\\n\\n\\ndef _make_vertex_build_row(flow_id, vertex_id=\\\"v1\\\") -> dict:\\n    base = VertexBuildBase(\\n        id=vertex_id,\\n        flow_id=flow_id,\\n        valid=True,\\n        params=\\\"p\\\",\\n        data={\\\"r\\\": 1},\\n        artifacts=None,\\n    )\\n    return VertexBuildTable(**base.model_dump()).model_dump(mode=\\\"python\\\")\\n\\n\\n@pytest.fixture\\nasync def writer_with_engine():\\n    \\\"\\\"\\\"Yield (writer, engine) wired together with a fresh in-memory SQLite.\\\"\\\"\\\"\\n    engine = create_async_engine(\\n        \\\"sqlite+aiosqlite://\\\",\\n        connect_args={\\\"check_same_thread\\\": False},\\n        poolclass=StaticPool,\\n    )\\n    async with engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.create_all)\\n    writer = _build_writer()\\n    writer._engine = engine\\n    writer._session_maker = async_sessionmaker(engine, expire_on_commit=False)\\n    writer._started = True\\n    writer._shutdown_event = asyncio.Event()\\n    try:\\n        yield writer, engine\\n    finally:\\n        writer._started = False\\n        async with engine.begin() as conn:\\n            await conn.run_sync(SQLModel.metadata.drop_all)\\n        await engine.dispose()\\n\\n\\ndef test_is_enabled_reads_settings() -> None:\\n    enabled = _build_writer({\\\"telemetry_writer_enabled\\\": True})\\n    disabled = _build_writer({\\\"telemetry_writer_enabled\\\": False})\\n    assert enabled.is_enabled() is True\\n    assert disabled.is_enabled() is False\\n\\n\\ndef test_enqueue_when_not_running_returns_false() -> None:\\n    writer = _build_writer()\\n    assert writer.enqueue_transaction({\\\"any\\\": \\\"thing\\\"}) is False\\n    assert writer.enqueue_vertex_build({\\\"any\\\": \\\"thing\\\"}) is False\\n\\n\\ndef test_enqueue_when_running_buffers_payload(writer_with_engine) -> None:\\n    writer, _ = writer_with_engine\\n    payload = {\\\"flow_id\\\": str(uuid4()), \\\"vertex_id\\\": \\\"v1\\\"}\\n    assert writer.enqueue_transaction(payload) is True\\n    assert len(writer._tx_buffer) == 1\\n    assert writer.enqueued_transactions == 1\\n\\n\\ndef test_overflow_drops_oldest(writer_with_engine) -> None:\\n    writer, _ = writer_with_engine\\n    writer.settings_service.settings.telemetry_writer_max_queue = 3\\n    for i in range(5):\\n        writer.enqueue_transaction({\\\"i\\\": i})\\n    # Cap is 3 \u2192 oldest two dropped, newest three retained.\\n    assert len(writer._tx_buffer) == 3\\n    assert writer.dropped_transactions == 2\\n    assert [item[\\\"i\\\"] for item in writer._tx_buffer] == [2, 3, 4]\\n\\n\\ndef test_count_strategy_ignores_byte_caps(writer_with_engine) -> None:\\n    \\\"\\\"\\\"Default 'count' strategy must not track or cap bytes \u2014 preserves legacy semantics.\\\"\\\"\\\"\\n    writer, _ = writer_with_engine\\n    writer.settings_service.settings.telemetry_writer_size_strategy = \\\"count\\\"\\n    writer.settings_service.settings.telemetry_writer_max_queue_bytes = 1  # tiny \u2014 would trip on bytes\\n    for i in range(5):\\n        writer.enqueue_transaction({\\\"big\\\": \\\"x\\\" * 1000, \\\"i\\\": i})\\n    assert len(writer._tx_buffer) == 5\\n    assert writer.dropped_transactions == 0\\n    # Byte tracking is disabled under 'count'.\\n    assert writer._tx_bytes == 0\\n    assert len(writer._tx_sizes) == 0\\n\\n\\ndef test_bytes_strategy_drops_oldest_when_byte_cap_exceeded(writer_with_engine) -> None:\\n    \\\"\\\"\\\"'bytes' strategy bounds memory regardless of row count.\\\"\\\"\\\"\\n    writer, _ = writer_with_engine\\n    writer.settings_service.settings.telemetry_writer_size_strategy = \\\"bytes\\\"\\n    writer.settings_service.settings.telemetry_writer_max_queue = 10_000  # high \u2014 must not be the trigger\\n    writer.settings_service.settings.telemetry_writer_max_queue_bytes = 200\\n    # {\\\"payload\\\": \\\"x\\\"*100, \\\"i\\\": N} encodes to 123 bytes. Two of them (246) bust\\n    # the 200B cap, so on each subsequent enqueue the oldest is dropped first.\\n    for i in range(3):\\n        writer.enqueue_transaction({\\\"payload\\\": \\\"x\\\" * 100, \\\"i\\\": i})\\n    assert writer._tx_bytes == 123\\n    assert len(writer._tx_buffer) == 1\\n    assert writer.dropped_transactions == 2\\n    assert writer.dropped_transactions_bytes == 246\\n\\n\\ndef test_either_strategy_trips_on_first_threshold(writer_with_engine) -> None:\\n    \\\"\\\"\\\"'either' fires whichever cap (rows or bytes) is breached first.\\\"\\\"\\\"\\n    writer, _ = writer_with_engine\\n    writer.settings_service.settings.telemetry_writer_size_strategy = \\\"either\\\"\\n    writer.settings_service.settings.telemetry_writer_max_queue = 3\\n    writer.settings_service.settings.telemetry_writer_max_queue_bytes = 10_000_000\\n    for i in range(5):\\n        writer.enqueue_transaction({\\\"i\\\": i})\\n    # Row cap trips first.\\n    assert len(writer._tx_buffer) == 3\\n    assert writer.dropped_transactions == 2\\n\\n\\ndef test_drain_batch_respects_byte_budget(writer_with_engine) -> None:\\n    \\\"\\\"\\\"Writer flush must split batches by bytes when strategy uses bytes.\\\"\\\"\\\"\\n    writer, _ = writer_with_engine\\n    writer.settings_service.settings.telemetry_writer_size_strategy = \\\"bytes\\\"\\n    for i in range(10):\\n        writer.enqueue_transaction({\\\"payload\\\": \\\"x\\\" * 100, \\\"i\\\": i})\\n    # Each row encodes to 123 bytes. With a 250B budget the loop pops 3 rows\\n    # (123, 246, 369) and breaks on the third when batch_bytes >= max_bytes.\\n    batch = writer._drain_batch(\\\"transactions\\\", max_n=10, max_bytes=250)\\n    assert len(batch) == 3\\n    assert len(writer._tx_buffer) == 7\\n    assert len(writer._tx_sizes) == 7\\n    assert writer._tx_bytes == 7 * 123\\n\\n\\ndef test_drain_batch_always_emits_one_row_even_when_oversized(writer_with_engine) -> None:\\n    \\\"\\\"\\\"A single row larger than the byte budget must still make progress.\\\"\\\"\\\"\\n    writer, _ = writer_with_engine\\n    writer.settings_service.settings.telemetry_writer_size_strategy = \\\"bytes\\\"\\n    writer.enqueue_transaction({\\\"big\\\": \\\"x\\\" * 10_000})\\n    batch = writer._drain_batch(\\\"transactions\\\", max_n=200, max_bytes=10)\\n    assert len(batch) == 1\\n\\n\\ndef test_return_batch_to_buffer_restores_sizes(writer_with_engine) -> None:\\n    \\\"\\\"\\\"Cancel/retry path must put rows AND their sizes back so accounting stays consistent.\\\"\\\"\\\"\\n    writer, _ = writer_with_engine\\n    writer.settings_service.settings.telemetry_writer_size_strategy = \\\"either\\\"\\n    writer.enqueue_transaction({\\\"a\\\": 1})\\n    writer.enqueue_transaction({\\\"b\\\": 2})\\n    bytes_before = writer._tx_bytes\\n    batch = writer._drain_batch(\\\"transactions\\\", max_n=2, max_bytes=10_000)\\n    assert writer._tx_bytes == 0\\n    writer._return_batch_to_buffer(\\\"transactions\\\", batch)\\n    assert writer._tx_bytes == bytes_before\\n    assert len(writer._tx_sizes) == len(writer._tx_buffer) == 2\\n\\n\\ndef test_bytes_strategy_round_trip_through_spill_and_restore(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Spill must reset size tracking; restore must rebuild it via _enqueue.\\\"\\\"\\\"\\n    own_dir = tmp_path / \\\"pid\\\"\\n    own_dir.mkdir()\\n    writer = _build_writer({\\\"telemetry_writer_size_strategy\\\": \\\"either\\\"})\\n    writer._started = True\\n    writer.enqueue_transaction({\\\"flow\\\": \\\"a\\\", \\\"i\\\": 1})\\n    writer.enqueue_transaction({\\\"flow\\\": \\\"b\\\", \\\"i\\\": 2})\\n    original_bytes = writer._tx_bytes\\n    assert original_bytes > 0\\n    assert len(writer._tx_sizes) == 2\\n\\n    writer._spill_to_disk(own_dir, kind=\\\"transactions\\\", buffer=writer._tx_buffer)\\n    # Spill drained the buffer and must zero size tracking.\\n    assert writer._tx_bytes == 0\\n    assert len(writer._tx_sizes) == 0\\n    assert not writer._tx_buffer\\n\\n    # Restore into a fresh writer with the same strategy.\\n    restored = _build_writer({\\\"telemetry_writer_size_strategy\\\": \\\"either\\\"})\\n    restored._started = True\\n    restored._restore_from_disk(own_dir, kind=\\\"transactions\\\", buffer=restored._tx_buffer)\\n    assert len(restored._tx_buffer) == 2\\n    assert len(restored._tx_sizes) == 2\\n    # Bytes must match the pre-spill total \u2014 restore re-encodes via _enqueue.\\n    assert restored._tx_bytes == original_bytes\\n\\n\\ndef test_bytes_strategy_round_trip_through_adoption(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Adopting an orphan outbox under 'bytes' strategy must populate size deques.\\\"\\\"\\\"\\n    dead_pid = _find_dead_pid()\\n    dead_dir = tmp_path / str(dead_pid)\\n    dead_dir.mkdir()\\n    _write_owner_file(dead_dir)\\n    spill_writer = _build_writer({\\\"telemetry_writer_size_strategy\\\": \\\"either\\\"})\\n    spill_writer._started = True\\n    spill_writer.enqueue_transaction({\\\"orphan\\\": True, \\\"i\\\": 1})\\n    spill_writer.enqueue_transaction({\\\"orphan\\\": True, \\\"i\\\": 2})\\n    spilled_bytes = spill_writer._tx_bytes\\n    spill_writer._spill_to_disk(dead_dir, kind=\\\"transactions\\\", buffer=spill_writer._tx_buffer)\\n\\n    adopter = _build_writer({\\\"telemetry_writer_size_strategy\\\": \\\"either\\\"})\\n    adopter._adopt_orphan_outboxes(tmp_path, own_pid=1)\\n    assert len(adopter._tx_buffer) == 2\\n    assert len(adopter._tx_sizes) == 2\\n    assert adopter._tx_bytes == spilled_bytes\\n\\n\\nasync def test_sweeper_calls_heartbeat_and_prune(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"One sweeper tick must touch our owner file and prune stale foreign dirs.\\\"\\\"\\\"\\n    import json as _json\\n    import os as _os\\n    import time as _time\\n\\n    own_dir = tmp_path / \\\"1234\\\"\\n    own_dir.mkdir()\\n    _write_owner_file(own_dir)\\n    owner_file = own_dir / \\\"owner.json\\\"\\n    aged = _time.time() - 7200\\n    _os.utime(owner_file, (aged, aged))\\n    own_before = owner_file.stat().st_mtime\\n\\n    foreign_dir = tmp_path / \\\"9999\\\"\\n    foreign_dir.mkdir()\\n    (foreign_dir / \\\"owner.json\\\").write_text(\\n        _json.dumps({\\\"host\\\": \\\"dead-foreign-pod\\\", \\\"boot\\\": \\\"x\\\", \\\"pid\\\": 9999, \\\"started_at\\\": 0})\\n    )\\n    _os.utime(foreign_dir / \\\"owner.json\\\", (aged, aged))\\n\\n    writer = _build_writer(\\n        {\\n            \\\"telemetry_writer_outbox_dir\\\": str(tmp_path),\\n            \\\"telemetry_writer_orphan_max_age_s\\\": 3600.0,\\n            # Skip the real retention pass \u2014 it needs a DB session.\\n            \\\"telemetry_writer_cleanup_interval_s\\\": 0.01,\\n        }\\n    )\\n    writer._own_outbox_dir = own_dir\\n    writer._shutdown_event = asyncio.Event()\\n    # Bypass _run_retention_pass by clearing the session_maker; the sweeper\\n    # catches the exception path either way, but None makes it a no-op.\\n    writer._session_maker = None\\n\\n    async def _stop_after_one_tick() -> None:\\n        await asyncio.sleep(0.1)\\n        writer._shutdown_event.set()\\n\\n    stopper = asyncio.create_task(_stop_after_one_tick())\\n    await writer._run_sweeper()\\n    await stopper\\n\\n    assert owner_file.stat().st_mtime > own_before\\n    assert not foreign_dir.exists()\\n\\n\\nasync def test_flush_inserts_transactions_and_vertex_builds(writer_with_engine) -> None:\\n    writer, engine = writer_with_engine\\n    flow_id = uuid4()\\n    tx_batch = [_make_transaction_row(flow_id) for _ in range(5)]\\n    vb_batch = [_make_vertex_build_row(flow_id) for _ in range(3)]\\n\\n    await writer._flush(tx_batch, vb_batch)\\n\\n    async with AsyncSession(engine) as session:\\n        tx_count = await session.scalar(select(func.count()).select_from(TransactionTable))\\n        vb_count = await session.scalar(select(func.count()).select_from(VertexBuildTable))\\n    assert tx_count == 5\\n    assert vb_count == 3\\n    # Sweeper-driven retention requires dirty-flow tracking; flush populates it.\\n    assert str(flow_id) in writer._dirty_tx_flows\\n    assert str(flow_id) in writer._dirty_vb_flows\\n\\n\\nasync def test_flush_and_retention_do_not_emit_deprecated_session_execute_warning(writer_with_engine) -> None:\\n    writer, _ = writer_with_engine\\n    writer.settings_service.settings.max_transactions_to_keep = 1\\n    writer.settings_service.settings.max_vertex_builds_to_keep = 1\\n    flow_id = uuid4()\\n\\n    tx_batch = [_make_transaction_row(flow_id) for _ in range(3)]\\n    vb_batch = [_make_vertex_build_row(flow_id, vertex_id=\\\"v1\\\") for _ in range(3)]\\n\\n    with warnings.catch_warnings():\\n        warnings.filterwarnings(\\\"error\\\", message=\\\"(?s).*session\\\\\\\\.exec\\\\\\\\(\\\\\\\\).*\\\", category=DeprecationWarning)\\n        await writer._flush(tx_batch, vb_batch)\\n        await writer._run_retention_pass()\\n\\n\\nasync def test_retention_sweep_caps_transactions_per_flow(writer_with_engine) -> None:\\n    writer, engine = writer_with_engine\\n    writer.settings_service.settings.max_transactions_to_keep = 3\\n    flow_id = uuid4()\\n    tx_batch = [_make_transaction_row(flow_id) for _ in range(10)]\\n    await writer._flush(tx_batch, [])\\n    async with AsyncSession(engine) as session:\\n        before = await session.scalar(select(func.count()).select_from(TransactionTable))\\n    assert before == 10\\n\\n    await writer._run_retention_pass()\\n\\n    async with AsyncSession(engine) as session:\\n        after = await session.scalar(select(func.count()).select_from(TransactionTable))\\n    assert after == 3\\n\\n\\nasync def test_retention_sweep_caps_vertex_builds_globally(writer_with_engine) -> None:\\n    writer, engine = writer_with_engine\\n    writer.settings_service.settings.max_vertex_builds_to_keep = 4\\n    writer.settings_service.settings.max_vertex_builds_per_vertex = 50\\n    flow_id = uuid4()\\n    vb_batch = [_make_vertex_build_row(flow_id, vertex_id=f\\\"v{i}\\\") for i in range(8)]\\n    await writer._flush([], vb_batch)\\n    await writer._run_retention_pass()\\n\\n    async with AsyncSession(engine) as session:\\n        count = await session.scalar(select(func.count()).select_from(VertexBuildTable))\\n    assert count == 4\\n\\n\\nasync def test_writer_loop_drains_buffers(writer_with_engine) -> None:\\n    writer, engine = writer_with_engine\\n    writer.settings_service.settings.telemetry_writer_batch_size = 2\\n    writer.settings_service.settings.telemetry_writer_flush_interval_s = 0.01\\n    flow_id = uuid4()\\n    for _ in range(5):\\n        writer.enqueue_transaction(_make_transaction_row(flow_id))\\n        writer.enqueue_vertex_build(_make_vertex_build_row(flow_id))\\n\\n    task = asyncio.create_task(writer._run_writer())\\n    # Give the writer time to flush all batches.\\n    for _ in range(20):\\n        await asyncio.sleep(0.05)\\n        if not writer._tx_buffer and not writer._vb_buffer:\\n            break\\n    writer._shutdown_event.set()\\n    await asyncio.wait_for(task, timeout=2)\\n\\n    async with AsyncSession(engine) as session:\\n        tx_count = await session.scalar(select(func.count()).select_from(TransactionTable))\\n        vb_count = await session.scalar(select(func.count()).select_from(VertexBuildTable))\\n    assert tx_count == 5\\n    assert vb_count == 5\\n    assert writer.failed_batches == 0\\n\\n\\ndef test_spill_and_restore_round_trip(tmp_path: Path) -> None:\\n    writer = _build_writer()\\n    own_dir = tmp_path / str(12345)\\n    own_dir.mkdir()\\n\\n    # Producer-side fills in-memory buffer.\\n    writer._tx_buffer.extend([{\\\"i\\\": 1}, {\\\"i\\\": 2}])\\n    writer._vb_buffer.extend([{\\\"j\\\": 1}])\\n\\n    writer._spill_to_disk(own_dir, kind=\\\"transactions\\\", buffer=writer._tx_buffer)\\n    writer._spill_to_disk(own_dir, kind=\\\"vertex_builds\\\", buffer=writer._vb_buffer)\\n    assert not writer._tx_buffer\\n    assert not writer._vb_buffer\\n\\n    # New writer comes up against the same outbox directory and restores.\\n    writer2 = _build_writer()\\n    writer2._restore_from_disk(own_dir, kind=\\\"transactions\\\", buffer=writer2._tx_buffer)\\n    writer2._restore_from_disk(own_dir, kind=\\\"vertex_builds\\\", buffer=writer2._vb_buffer)\\n    assert list(writer2._tx_buffer) == [{\\\"i\\\": 1}, {\\\"i\\\": 2}]\\n    assert list(writer2._vb_buffer) == [{\\\"j\\\": 1}]\\n\\n\\nasync def test_spill_restore_round_trip_writes_realistic_payload_to_db(writer_with_engine, tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Realistic payloads (UUID, datetime) survive JSON spill/restore and INSERT.\\n\\n    Guards against the SQLite outbox's ``json.dumps(default=str)`` encoding\\n    breaking SQLAlchemy core inserts on the UUID/datetime columns of\\n    ``transaction`` / ``vertex_build`` once a row has been spilled to disk.\\n    \\\"\\\"\\\"\\n    writer, engine = writer_with_engine\\n    flow_id = uuid4()\\n    writer._tx_buffer.append(_make_transaction_row(flow_id))\\n    writer._vb_buffer.append(_make_vertex_build_row(flow_id))\\n\\n    own_dir = tmp_path / \\\"pid\\\"\\n    own_dir.mkdir()\\n    writer._spill_to_disk(own_dir, kind=\\\"transactions\\\", buffer=writer._tx_buffer)\\n    writer._spill_to_disk(own_dir, kind=\\\"vertex_builds\\\", buffer=writer._vb_buffer)\\n    writer._restore_from_disk(own_dir, kind=\\\"transactions\\\", buffer=writer._tx_buffer)\\n    writer._restore_from_disk(own_dir, kind=\\\"vertex_builds\\\", buffer=writer._vb_buffer)\\n\\n    tx_batch = list(writer._tx_buffer)\\n    vb_batch = list(writer._vb_buffer)\\n    writer._tx_buffer.clear()\\n    writer._vb_buffer.clear()\\n    await writer._flush(tx_batch, vb_batch)\\n\\n    async with AsyncSession(engine) as session:\\n        tx_count = await session.scalar(select(func.count()).select_from(TransactionTable))\\n        vb_count = await session.scalar(select(func.count()).select_from(VertexBuildTable))\\n    assert tx_count == 1\\n    assert vb_count == 1\\n\\n\\ndef _find_dead_pid(start: int = 99_999, max_checks: int = 50_000) -> int:\\n    from langflow.services.telemetry_writer.service import _pid_alive\\n\\n    pid = start\\n    for _ in range(max_checks):\\n        if not _pid_alive(pid):\\n            return pid\\n        pid += 1\\n    pytest.fail(\\\"Unable to find an unused PID for orphan outbox setup\\\")\\n    return 0  # unreachable, for type-checkers\\n\\n\\ndef test_adopt_orphan_outboxes(tmp_path: Path) -> None:\\n    # Simulate a dead worker that left rows in a sibling outbox.\\n    dead_pid = _find_dead_pid()\\n    dead_dir = tmp_path / str(dead_pid)\\n    dead_dir.mkdir()\\n    _write_owner_file(dead_dir)\\n    spill_writer = _build_writer()\\n    spill_writer._tx_buffer.extend([{\\\"orphan\\\": True}])\\n    spill_writer._vb_buffer.extend([{\\\"orphan_vb\\\": True}])\\n    spill_writer._spill_to_disk(dead_dir, kind=\\\"transactions\\\", buffer=spill_writer._tx_buffer)\\n    spill_writer._spill_to_disk(dead_dir, kind=\\\"vertex_builds\\\", buffer=spill_writer._vb_buffer)\\n\\n    own_writer = _build_writer()\\n    own_writer._adopt_orphan_outboxes(tmp_path, own_pid=1)\\n    assert list(own_writer._tx_buffer) == [{\\\"orphan\\\": True}]\\n    assert list(own_writer._vb_buffer) == [{\\\"orphan_vb\\\": True}]\\n    # Orphan directory was cleaned up.\\n    assert not dead_dir.exists()\\n\\n\\ndef test_adopt_orphan_outboxes_skips_unknown_host(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Cross-host or pre-reboot orphan dirs must not be adopted.\\n\\n    Guards against PID reuse on container restart pulling in a stranger's\\n    spill data \u2014 the spill on disk is only adopted when the owner file's\\n    host + boot identity matches the current host.\\n    \\\"\\\"\\\"\\n    import json as _json\\n\\n    dead_pid = _find_dead_pid()\\n    dead_dir = tmp_path / str(dead_pid)\\n    dead_dir.mkdir()\\n    # Stamp a mismatched owner file.\\n    (dead_dir / \\\"owner.json\\\").write_text(\\n        _json.dumps({\\\"host\\\": \\\"some-other-host\\\", \\\"boot\\\": \\\"unrelated-boot\\\", \\\"pid\\\": dead_pid, \\\"started_at\\\": 0})\\n    )\\n    spill_writer = _build_writer()\\n    spill_writer._tx_buffer.extend([{\\\"orphan\\\": True}])\\n    spill_writer._spill_to_disk(dead_dir, kind=\\\"transactions\\\", buffer=spill_writer._tx_buffer)\\n\\n    own_writer = _build_writer()\\n    own_writer._adopt_orphan_outboxes(tmp_path, own_pid=1)\\n    assert list(own_writer._tx_buffer) == []\\n    # The orphan directory is left in place so a forensic operator can inspect it.\\n    assert dead_dir.exists()\\n\\n\\ndef test_adopt_orphan_outboxes_skips_when_owner_missing(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Pre-owner-file directories from older runs must not be silently adopted.\\\"\\\"\\\"\\n    dead_pid = _find_dead_pid()\\n    dead_dir = tmp_path / str(dead_pid)\\n    dead_dir.mkdir()\\n    # No owner.json on purpose.\\n    spill_writer = _build_writer()\\n    spill_writer._tx_buffer.extend([{\\\"orphan\\\": True}])\\n    spill_writer._spill_to_disk(dead_dir, kind=\\\"transactions\\\", buffer=spill_writer._tx_buffer)\\n\\n    own_writer = _build_writer()\\n    own_writer._adopt_orphan_outboxes(tmp_path, own_pid=1)\\n    assert list(own_writer._tx_buffer) == []\\n\\n\\ndef test_adopt_orphan_outboxes_honors_max_queue(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A pathologically large orphan spill must not OOM the current worker.\\n\\n    Regression for the case where ``_restore_from_disk`` and\\n    ``_adopt_orphan_outboxes`` appended directly to the deque, bypassing the\\n    queue cap.\\n    \\\"\\\"\\\"\\n    dead_pid = _find_dead_pid()\\n    dead_dir = tmp_path / str(dead_pid)\\n    dead_dir.mkdir()\\n    _write_owner_file(dead_dir)\\n    spill_writer = _build_writer()\\n    # Spill more rows than the receiving writer's cap.\\n    spill_writer._tx_buffer.extend([{\\\"i\\\": i} for i in range(100)])\\n    spill_writer._spill_to_disk(dead_dir, kind=\\\"transactions\\\", buffer=spill_writer._tx_buffer)\\n\\n    own_writer = _build_writer({\\\"telemetry_writer_max_queue\\\": 10})\\n    own_writer._adopt_orphan_outboxes(tmp_path, own_pid=1)\\n\\n    # Buffer capped at 10; older rows dropped, drop counter reflects loss.\\n    assert len(own_writer._tx_buffer) == 10\\n    assert own_writer.dropped_transactions == 90\\n    # The newest rows (90..99) survive.\\n    assert [r[\\\"i\\\"] for r in own_writer._tx_buffer] == list(range(90, 100))\\n\\n\\ndef test_prune_stale_foreign_outboxes_deletes_aged_cross_host_dirs(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Cross-host orphan dirs older than max_age must be deleted from a shared volume.\\\"\\\"\\\"\\n    import json as _json\\n    import os as _os\\n    import time as _time\\n\\n    foreign_dir = tmp_path / \\\"9999\\\"\\n    foreign_dir.mkdir()\\n    owner_file = foreign_dir / \\\"owner.json\\\"\\n    owner_file.write_text(\\n        _json.dumps({\\\"host\\\": \\\"some-other-host\\\", \\\"boot\\\": \\\"unrelated-boot\\\", \\\"pid\\\": 9999, \\\"started_at\\\": 0})\\n    )\\n    # Backdate the owner file beyond the prune threshold.\\n    aged = _time.time() - 7200  # 2h ago, default max_age is 1h\\n    _os.utime(owner_file, (aged, aged))\\n\\n    writer = _build_writer({\\\"telemetry_writer_orphan_max_age_s\\\": 3600.0})\\n    writer._prune_stale_foreign_outboxes(tmp_path)\\n    assert not foreign_dir.exists()\\n\\n\\ndef test_prune_stale_foreign_outboxes_preserves_fresh_cross_host_dirs(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A live foreign pod's outbox must not be deleted while it's actively heartbeating.\\\"\\\"\\\"\\n    import json as _json\\n\\n    foreign_dir = tmp_path / \\\"1234\\\"\\n    foreign_dir.mkdir()\\n    (foreign_dir / \\\"owner.json\\\").write_text(\\n        _json.dumps({\\\"host\\\": \\\"live-foreign-pod\\\", \\\"boot\\\": \\\"unrelated-boot\\\", \\\"pid\\\": 1234, \\\"started_at\\\": 0})\\n    )\\n    # Owner file mtime is \\\"now\\\" \u2014 pod is actively heartbeating.\\n\\n    writer = _build_writer({\\\"telemetry_writer_orphan_max_age_s\\\": 3600.0})\\n    writer._prune_stale_foreign_outboxes(tmp_path)\\n    assert foreign_dir.exists()\\n\\n\\ndef test_prune_stale_foreign_outboxes_leaves_same_host_dirs_alone(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"Same-host orphans are the adoption path's job, not the pruner's \u2014 even when aged.\\\"\\\"\\\"\\n    import os as _os\\n    import time as _time\\n\\n    own_dir = tmp_path / \\\"5555\\\"\\n    own_dir.mkdir()\\n    _write_owner_file(own_dir)\\n    owner_file = own_dir / \\\"owner.json\\\"\\n    aged = _time.time() - 7200\\n    _os.utime(owner_file, (aged, aged))\\n\\n    writer = _build_writer({\\\"telemetry_writer_orphan_max_age_s\\\": 3600.0})\\n    writer._prune_stale_foreign_outboxes(tmp_path)\\n    assert own_dir.exists()\\n\\n\\ndef test_heartbeat_owner_file_refreshes_mtime(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"The heartbeat must bump the owner file's mtime so foreign hosts can age us out.\\\"\\\"\\\"\\n    import os as _os\\n    import time as _time\\n\\n    own_dir = tmp_path / \\\"1\\\"\\n    own_dir.mkdir()\\n    _write_owner_file(own_dir)\\n    owner_file = own_dir / \\\"owner.json\\\"\\n    aged = _time.time() - 7200\\n    _os.utime(owner_file, (aged, aged))\\n    before = owner_file.stat().st_mtime\\n\\n    writer = _build_writer()\\n    writer._own_outbox_dir = own_dir\\n    writer._heartbeat_owner_file()\\n    after = owner_file.stat().st_mtime\\n    assert after > before\\n\\n\\ndef test_spill_caps_at_max_queue(tmp_path: Path) -> None:\\n    \\\"\\\"\\\"A backlogged buffer at shutdown must not spill unbounded rows to disk.\\n\\n    Older rows beyond ``telemetry_writer_max_queue`` are dropped (matching\\n    the producer-side overflow policy) and the drop counter is incremented.\\n    \\\"\\\"\\\"\\n    own_dir = tmp_path / \\\"pid\\\"\\n    own_dir.mkdir()\\n    writer = _build_writer({\\\"telemetry_writer_max_queue\\\": 20})\\n    writer._tx_buffer.extend([{\\\"i\\\": i} for i in range(100)])\\n    writer._spill_to_disk(own_dir, kind=\\\"transactions\\\", buffer=writer._tx_buffer)\\n\\n    assert writer.dropped_transactions == 80\\n    # Round-trip what hit disk: only the newest 20 rows survive.\\n    restore = _build_writer({\\\"telemetry_writer_max_queue\\\": 1000})\\n    restore._restore_from_disk(own_dir, kind=\\\"transactions\\\", buffer=restore._tx_buffer)\\n    assert [r[\\\"i\\\"] for r in restore._tx_buffer] == list(range(80, 100))\\n\\n\\nasync def test_sanitization_survives_writer_round_trip(writer_with_engine) -> None:\\n    \\\"\\\"\\\"A sensitive value passed through the producer must land redacted in the DB.\\\"\\\"\\\"\\n    writer, engine = writer_with_engine\\n    flow_id = uuid4()\\n    # TransactionBase.__init__ runs sanitize_data on inputs/outputs. The\\n    # writer path serializes via model_dump and bulk-inserts; verify the\\n    # sanitization isn't lost along the way.\\n    base = TransactionBase(\\n        vertex_id=\\\"v1\\\",\\n        target_id=None,\\n        inputs={\\\"api_key\\\": \\\"sk-very-secret-token-12345\\\"},  # pragma: allowlist secret\\n        outputs={\\\"password\\\": \\\"hunter2\\\"},  # pragma: allowlist secret\\n        status=\\\"success\\\",\\n        error=None,\\n        flow_id=flow_id,\\n    )\\n    row = TransactionTable(**base.model_dump()).model_dump(mode=\\\"python\\\")\\n    await writer._flush([row], [])\\n\\n    async with AsyncSession(engine) as session:\\n        result = await session.execute(select(TransactionTable.inputs, TransactionTable.outputs))\\n        inputs, outputs = result.one()\\n    assert \\\"sk-very-secret-token-12345\\\" not in str(inputs)\\n    assert \\\"hunter2\\\" not in str(outputs)\\n    assert \\\"api_key\\\" in inputs\\n    assert \\\"password\\\" in outputs\\n\\n\\nasync def test_retention_failure_preserves_dirty_flows(writer_with_engine) -> None:\\n    \\\"\\\"\\\"A sweep that crashes before commit must leave the dirty-flow set intact.\\\"\\\"\\\"\\n    writer, _ = writer_with_engine\\n    tx_flow = uuid4()\\n    vb_flow = uuid4()\\n    writer._dirty_tx_flows.add(str(tx_flow))\\n    writer._dirty_vb_flows.add(str(vb_flow))\\n\\n    # Wrap the real session_maker so commit raises but execute() works\\n    # normally \u2014 this drives the retention pass through every query and only\\n    # fails at the commit boundary, which is exactly the scenario the snapshot/\\n    # restore logic guards against.\\n    real_session_maker = writer._session_maker\\n\\n    class _CommitFailsSessionMaker:\\n        def __call__(self_inner):  # noqa: N805\\n            session = real_session_maker()\\n\\n            class _CommitFailsCM:\\n                async def __aenter__(self):\\n                    self._session = await session.__aenter__()\\n                    original_commit = self._session.commit\\n\\n                    async def _raise_on_commit():\\n                        await original_commit()  # exercise the path\\n                        msg = \\\"boom\\\"\\n                        raise RuntimeError(msg)\\n\\n                    self._session.commit = _raise_on_commit\\n                    return self._session\\n\\n                async def __aexit__(self, *args):\\n                    return await session.__aexit__(*args)\\n\\n            return _CommitFailsCM()\\n\\n    writer._session_maker = _CommitFailsSessionMaker()\\n    with pytest.raises(RuntimeError, match=\\\"boom\\\"):\\n        await writer._run_retention_pass()\\n\\n    # Dirty set must still hold both ids since the commit never landed.\\n    assert str(tx_flow) in writer._dirty_tx_flows\\n    assert str(vb_flow) in writer._dirty_vb_flows\\n\\n\\nasync def test_in_flight_batch_returned_on_cancel(writer_with_engine) -> None:\\n    \\\"\\\"\\\"If the writer is cancelled mid-flush, popped rows must go back to the buffer.\\\"\\\"\\\"\\n    writer, _ = writer_with_engine\\n    writer.settings_service.settings.telemetry_writer_batch_size = 100\\n    writer.settings_service.settings.telemetry_writer_flush_interval_s = 0.01\\n    flow_id = uuid4()\\n    for _ in range(20):\\n        writer.enqueue_transaction(_make_transaction_row(flow_id))\\n    assert len(writer._tx_buffer) == 20\\n\\n    # Replace the session_maker with one that hangs forever inside execute,\\n    # so the writer is guaranteed to be blocked mid-flush when we cancel.\\n    hang = asyncio.Event()  # never set\\n\\n    class _HangingSessionMaker:\\n        def __call__(self):\\n            return self\\n\\n        async def __aenter__(self):\\n            return self\\n\\n        async def __aexit__(self, *_):\\n            return False\\n\\n        async def execute(self, *_, **__):\\n            await hang.wait()\\n\\n        async def commit(self):\\n            pass\\n\\n    writer._session_maker = _HangingSessionMaker()\\n    task = asyncio.create_task(writer._run_writer())\\n    # Give the writer a tick to drain into a batch and start the flush.\\n    for _ in range(20):\\n        await asyncio.sleep(0.02)\\n        if len(writer._tx_buffer) == 0:\\n            break\\n    assert len(writer._tx_buffer) == 0  # the batch is in-flight\\n\\n    task.cancel()\\n    with pytest.raises(asyncio.CancelledError):\\n        await task\\n\\n    # Cancelled mid-flush \u2014 the 20 rows should be back in the buffer.\\n    assert len(writer._tx_buffer) == 20\\n\\n\\nasync def test_lifecycle_idempotent_when_disabled() -> None:\\n    writer = _build_writer({\\\"telemetry_writer_enabled\\\": False})\\n    # start() is a no-op when disabled.\\n    await writer.start()\\n    assert writer.is_running() is False\\n    # teardown() on a never-started writer is harmless.\\n    await writer.teardown()\\n\\n\\nasync def test_teardown_spills_remaining_buffer(tmp_path: Path) -> None:\\n    outbox = tmp_path / \\\"outbox\\\"\\n    writer = _build_writer(\\n        {\\n            \\\"telemetry_writer_outbox_dir\\\": str(outbox),\\n        }\\n    )\\n    # Manually wire enough state to exercise teardown's spill path without\\n    # going through start() (which needs the full langflow service stack).\\n    writer._started = True\\n    writer._shutdown_event = asyncio.Event()\\n    writer._shutdown_event.set()\\n    writer._own_outbox_dir = outbox / \\\"1\\\"\\n    writer._own_outbox_dir.mkdir(parents=True)\\n    writer._tx_buffer.append({\\\"to_disk\\\": 1})\\n\\n    await writer.teardown()\\n\\n    # A second writer pointed at the same dir should see the spilled row.\\n    writer2 = _build_writer()\\n    writer2._restore_from_disk(outbox / \\\"1\\\", kind=\\\"transactions\\\", buffer=writer2._tx_buffer)\\n    assert list(writer2._tx_buffer) == [{\\\"to_disk\\\": 1}]\\n\\n    # Clean up the outbox directory tree.\\n    shutil.rmtree(outbox, ignore_errors=True)\\n    # Also clean up our potential tempfile fallback if used.\\n    fallback = Path(tempfile.gettempdir()) / \\\"langflow_telemetry_outbox\\\"\\n    if fallback.exists() and fallback.is_dir() and not any(fallback.iterdir()):\\n        fallback.rmdir()\\n\\n\\nasync def test_retention_sweep_caps_vertex_builds_per_vertex(writer_with_engine) -> None:\\n    \\\"\\\"\\\"Per-vertex cap must prune the oldest builds for a single vertex.\\\"\\\"\\\"\\n    writer, engine = writer_with_engine\\n    writer.settings_service.settings.max_vertex_builds_per_vertex = 3\\n    writer.settings_service.settings.max_vertex_builds_to_keep = 10_000\\n    flow_id = uuid4()\\n    # Insert 8 builds for the same vertex \u2014 only 3 should survive.\\n    vb_batch = [_make_vertex_build_row(flow_id, vertex_id=\\\"v1\\\") for _ in range(8)]\\n    await writer._flush([], vb_batch)\\n    await writer._run_retention_pass()\\n\\n    async with AsyncSession(engine) as session:\\n        count = await session.scalar(select(func.count()).select_from(VertexBuildTable))\\n    assert count == 3\\n\\n\\ndef test_either_strategy_trips_on_bytes_first(writer_with_engine) -> None:\\n    \\\"\\\"\\\"'either' strategy must enforce the byte cap when it trips before the row cap.\\\"\\\"\\\"\\n    writer, _ = writer_with_engine\\n    writer.settings_service.settings.telemetry_writer_size_strategy = \\\"either\\\"\\n    writer.settings_service.settings.telemetry_writer_max_queue = 10_000  # high \u2014 must not trigger\\n    writer.settings_service.settings.telemetry_writer_max_queue_bytes = 200\\n    # Each row encodes to ~123 bytes; two rows (246B) exceed the 200B cap.\\n    for i in range(3):\\n        writer.enqueue_transaction({\\\"payload\\\": \\\"x\\\" * 100, \\\"i\\\": i})\\n    # Byte cap trips first \u2014 same drop semantics as the bytes-only strategy.\\n    assert writer.dropped_transactions >= 1\\n    assert writer._tx_bytes <= 200\\n\\n\\nasync def test_writer_retries_on_batch_failure(writer_with_engine) -> None:\\n    \\\"\\\"\\\"Failed flush must increment failed_batches, return rows to buffer, then succeed on retry.\\\"\\\"\\\"\\n    writer, engine = writer_with_engine\\n    writer.settings_service.settings.telemetry_writer_batch_size = 100\\n    writer.settings_service.settings.telemetry_writer_flush_interval_s = 0.01\\n    flow_id = uuid4()\\n    for _ in range(5):\\n        writer.enqueue_transaction(_make_transaction_row(flow_id))\\n\\n    fail_count = 0\\n\\n    real_flush = writer._flush.__func__\\n\\n    async def _fail_twice(self, tx_batch, vb_batch):\\n        nonlocal fail_count\\n        if fail_count < 2:\\n            fail_count += 1\\n            msg = \\\"injected failure\\\"\\n            raise RuntimeError(msg)\\n        return await real_flush(self, tx_batch, vb_batch)\\n\\n    import types\\n\\n    writer._flush = types.MethodType(_fail_twice, writer)\\n\\n    task = asyncio.create_task(writer._run_writer())\\n    # The two injected failures each return the batch to the buffer and back off\\n    # via _wait_or_shutdown. Setting the shutdown event short-circuits those\\n    # backoffs so the writer reaches its successful retry and drains \u2014 the\\n    # shutdown, not wall-clock waiting, is what lands the rows.\\n    writer._shutdown_event.set()\\n    await asyncio.wait_for(task, timeout=5)\\n\\n    assert writer.failed_batches == 2\\n    assert writer.flushed_rows == 5\\n    async with AsyncSession(engine) as session:\\n        final = await session.scalar(select(func.count()).select_from(TransactionTable))\\n    assert final == 5\\n\\n\\nasync def test_writer_escalates_after_threshold_failures(writer_with_engine) -> None:\\n    \\\"\\\"\\\"Consecutive failures past the threshold must keep retrying (exercises the `>=` branch, not `==`).\\\"\\\"\\\"\\n    import types\\n\\n    writer, engine = writer_with_engine\\n    writer.settings_service.settings.telemetry_writer_batch_size = 100\\n    writer.settings_service.settings.telemetry_writer_flush_interval_s = 0.01\\n    flow_id = uuid4()\\n    for _ in range(5):\\n        writer.enqueue_transaction(_make_transaction_row(flow_id))\\n\\n    # Fail one more than the threshold so the escalation branch runs at counts\\n    # both equal to and greater than the threshold \u2014 exactly what `>=` covers\\n    # and `==` would not.\\n    fail_target = _FAILURE_ESCALATION_THRESHOLD + 1\\n    fail_count = 0\\n    real_flush = writer._flush.__func__\\n\\n    async def _fail_n_times(self, tx_batch, vb_batch):\\n        nonlocal fail_count\\n        if fail_count < fail_target:\\n            fail_count += 1\\n            msg = \\\"injected failure\\\"\\n            raise RuntimeError(msg)\\n        return await real_flush(self, tx_batch, vb_batch)\\n\\n    writer._flush = types.MethodType(_fail_n_times, writer)\\n\\n    task = asyncio.create_task(writer._run_writer())\\n    # Short-circuit every backoff so the failures (and the final success) run fast.\\n    writer._shutdown_event.set()\\n    await asyncio.wait_for(task, timeout=5)\\n\\n    # Every injected failure was counted (driving consecutive_failures past the\\n    # threshold), then the buffer drained on the success.\\n    assert writer.failed_batches == fail_target\\n    assert writer.flushed_rows == 5\\n    async with AsyncSession(engine) as session:\\n        final = await session.scalar(select(func.count()).select_from(TransactionTable))\\n    assert final == 5\\n\\n\\nasync def test_teardown_cancelled_still_spills_buffer(writer_with_engine, tmp_path: Path) -> None:\\n    \\\"\\\"\\\"If teardown() is itself cancelled, the in-memory buffer must still spill to disk.\\\"\\\"\\\"\\n    writer, _ = writer_with_engine\\n    own_dir = tmp_path / \\\"pid\\\"\\n    own_dir.mkdir()\\n    writer._own_outbox_dir = own_dir\\n    # Long drain so teardown blocks in the writer-drain await while we cancel it.\\n    writer.settings_service.settings.telemetry_writer_shutdown_drain_s = 30.0\\n\\n    for i in range(3):\\n        writer.enqueue_transaction({\\\"cancelled_spill\\\": i})\\n    assert len(writer._tx_buffer) == 3\\n\\n    # A writer task that never finishes on its own, so teardown stays parked in\\n    # the drain await until we cancel it.\\n    async def _never() -> None:\\n        await asyncio.Event().wait()\\n\\n    writer._writer_task = asyncio.create_task(_never())\\n\\n    teardown_task = asyncio.create_task(writer.teardown())\\n    await asyncio.sleep(0.05)  # let teardown reach the drain await\\n    teardown_task.cancel()\\n    with pytest.raises(asyncio.CancelledError):\\n        await teardown_task\\n\\n    # The cancellation must not have dropped the buffer: a fresh reader pointed\\n    # at the same outbox sees the spilled rows.\\n    reader = _build_writer()\\n    reader._restore_from_disk(own_dir, kind=\\\"transactions\\\", buffer=reader._tx_buffer)\\n    assert [row[\\\"cancelled_spill\\\"] for row in reader._tx_buffer] == [0, 1, 2]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/test_cache_factory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"66a62c44a786529c8032815deb73f62e7fba1bc6ad1940c33858f90aa927b6d3\",\"content\":\"\\\"\\\"\\\"Regression tests for the cache factory after diskcache removal.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport pytest\\nfrom lfx.services.settings.base import Settings\\nfrom pydantic import ValidationError\\n\\n\\ndef test_cache_type_disk_is_rejected(monkeypatch):\\n    \\\"\\\"\\\"LANGFLOW_CACHE_TYPE=disk must fail validation now that the disk backend is gone.\\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGFLOW_CACHE_TYPE\\\", \\\"disk\\\")\\n    with pytest.raises(ValidationError):\\n        Settings()\\n\\n\\n@pytest.mark.parametrize(\\\"cache_type\\\", [\\\"async\\\", \\\"memory\\\", \\\"redis\\\"])\\ndef test_supported_cache_types_validate(monkeypatch, cache_type):\\n    monkeypatch.setenv(\\\"LANGFLOW_CACHE_TYPE\\\", cache_type)\\n    settings = Settings()\\n    assert settings.cache_type == cache_type\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/test_deployment_feature_flags.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"dab6f3293e887c81e212792e6b02c39437fe37f6431eb8ffc7944c0b6024f6d9\",\"content\":\"import langflow.services.utils as service_utils\\n\\n\\ndef test_register_builtin_adapters_skips_import_when_feature_disabled(monkeypatch):\\n    calls: list[str] = []\\n\\n    monkeypatch.setattr(service_utils.FEATURE_FLAGS, \\\"wxo_deployments\\\", False)\\n    monkeypatch.setattr(service_utils, \\\"import_module\\\", lambda name: calls.append(name))\\n\\n    service_utils.register_builtin_adapters()\\n\\n    assert calls == []\\n\\n\\ndef test_register_builtin_adapters_imports_when_feature_enabled(monkeypatch):\\n    calls: list[str] = []\\n\\n    monkeypatch.setattr(service_utils.FEATURE_FLAGS, \\\"wxo_deployments\\\", True)\\n    monkeypatch.setattr(service_utils, \\\"import_module\\\", lambda name: calls.append(name))\\n\\n    service_utils.register_builtin_adapters()\\n\\n    assert calls == [\\\"langflow.services.adapters.deployment.watsonx_orchestrate.register\\\"]\\n\\n\\ndef test_register_builtin_deployment_mappers_skips_import_when_feature_disabled(monkeypatch):\\n    calls: list[str] = []\\n\\n    monkeypatch.setattr(service_utils.FEATURE_FLAGS, \\\"wxo_deployments\\\", False)\\n    monkeypatch.setattr(service_utils, \\\"import_module\\\", lambda name: calls.append(name))\\n\\n    service_utils.register_builtin_deployment_mappers()\\n\\n    assert calls == []\\n\\n\\ndef test_register_builtin_deployment_mappers_imports_when_feature_enabled(monkeypatch):\\n    calls: list[str] = []\\n\\n    monkeypatch.setattr(service_utils.FEATURE_FLAGS, \\\"wxo_deployments\\\", True)\\n    monkeypatch.setattr(service_utils, \\\"import_module\\\", lambda name: calls.append(name))\\n\\n    service_utils.register_builtin_deployment_mappers()\\n\\n    assert calls == [\\\"langflow.api.v1.mappers.deployments.watsonx_orchestrate\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/test_model_provider_policy_refresh.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b336ed6ea797c2b354e6936e223a89165c283148f0a957479bf0b1c1cacbe69f\",\"content\":\"from __future__ import annotations\\n\\nimport asyncio\\nfrom contextlib import asynccontextmanager\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, Mock\\n\\nfrom langflow.services.task import model_provider_policy_refresh as refresh_module\\nfrom lfx.services.model_provider_policy import (\\n    BaseModelProviderPolicyService,\\n    ModelProviderPolicyContext,\\n    ModelProviderPolicyPurpose,\\n    ModelProviderPolicyService,\\n)\\nfrom lfx.services.policy_bundle import PolicyBundleService, PolicyBundleSnapshot\\n\\n\\nclass _DatabaseOwnedPluginPolicyService(BaseModelProviderPolicyService):\\n    def __init__(self, policy_bundle_service: PolicyBundleService) -> None:\\n        super().__init__()\\n        self.policy_bundle_service = policy_bundle_service\\n        self.set_ready()\\n\\n    def get_allowed_provider_ids(\\n        self,\\n        *,\\n        context: ModelProviderPolicyContext,\\n        candidate_provider_ids: frozenset[str],\\n        purpose: ModelProviderPolicyPurpose,\\n    ) -> frozenset[str]:\\n        _ = context, purpose\\n        if not self.policy_bundle_service.source_available:\\n            return frozenset()\\n        ceiling = self.policy_bundle_service.snapshot.approved_provider_ids\\n        return candidate_provider_ids if not ceiling else candidate_provider_ids & ceiling\\n\\n\\nclass _ExternalBuiltinPolicyService(ModelProviderPolicyService):\\n    def __init__(self) -> None:\\n        super().__init__()\\n        self.set_approved_provider_ids({\\\"openai\\\"}, version=2)\\n\\n    @property\\n    def external_approved_provider_ids(self) -> frozenset[str]:\\n        return frozenset({\\\"openai\\\"})\\n\\n\\nasync def test_refresh_failure_preserves_unrestricted_policy_availability(monkeypatch):\\n    service = ModelProviderPolicyService()\\n    error_message = \\\"policy store unavailable\\\"\\n\\n    @asynccontextmanager\\n    async def failing_session_scope():\\n        raise ConnectionError(error_message)\\n        yield\\n\\n    monkeypatch.setattr(refresh_module, \\\"session_scope\\\", failing_session_scope)\\n    monkeypatch.setattr(refresh_module, \\\"get_model_provider_policy_service\\\", lambda: service)\\n    monkeypatch.setattr(refresh_module.logger, \\\"aerror\\\", AsyncMock())\\n\\n    changed = await refresh_module.ModelProviderPolicyRefreshWorker()._run_once()\\n\\n    assert changed is False\\n    assert service.policy_source_available is True\\n\\n\\nasync def test_missing_policy_singleton_denies_an_unrestricted_service(monkeypatch):\\n    service = ModelProviderPolicyService()\\n    error_message = \\\"model-provider policy singleton is missing\\\"\\n\\n    @asynccontextmanager\\n    async def failing_session_scope():\\n        raise refresh_module.ModelProviderPolicyNotInitializedError(error_message)\\n        yield\\n\\n    monkeypatch.setattr(refresh_module, \\\"session_scope\\\", failing_session_scope)\\n    monkeypatch.setattr(refresh_module, \\\"get_model_provider_policy_service\\\", lambda: service)\\n    monkeypatch.setattr(refresh_module.logger, \\\"aerror\\\", AsyncMock())\\n\\n    changed = await refresh_module.ModelProviderPolicyRefreshWorker()._run_once()\\n\\n    assert changed is True\\n    assert service.policy_source_available is False\\n\\n\\nasync def test_refresh_apply_failure_denies_a_restrictive_policy(monkeypatch):\\n    service = ModelProviderPolicyService()\\n    service.set_approved_provider_ids({\\\"openai\\\"}, version=3)\\n\\n    @asynccontextmanager\\n    async def session_scope():\\n        yield object()\\n\\n    monkeypatch.setattr(refresh_module, \\\"session_scope\\\", session_scope)\\n    monkeypatch.setattr(refresh_module, \\\"get_model_provider_policy_service\\\", lambda: service)\\n    monkeypatch.setattr(\\n        refresh_module,\\n        \\\"get_model_provider_policy_state\\\",\\n        AsyncMock(return_value=SimpleNamespace(approved_provider_ids=frozenset({\\\"openai\\\"}))),\\n    )\\n    monkeypatch.setattr(\\n        refresh_module,\\n        \\\"apply_model_provider_policy_state\\\",\\n        Mock(side_effect=RuntimeError(\\\"apply failed\\\")),\\n    )\\n    monkeypatch.setattr(refresh_module.logger, \\\"aerror\\\", AsyncMock())\\n\\n    changed = await refresh_module.ModelProviderPolicyRefreshWorker()._run_once()\\n\\n    assert changed is True\\n    assert service.policy_source_available is False\\n\\n\\nasync def test_refresh_apply_failure_denies_a_newly_read_restrictive_policy(monkeypatch):\\n    service = ModelProviderPolicyService()\\n\\n    @asynccontextmanager\\n    async def session_scope():\\n        yield object()\\n\\n    state = SimpleNamespace(approved_provider_ids=frozenset({\\\"openai\\\"}))\\n    monkeypatch.setattr(refresh_module, \\\"session_scope\\\", session_scope)\\n    monkeypatch.setattr(refresh_module, \\\"get_model_provider_policy_service\\\", lambda: service)\\n    monkeypatch.setattr(\\n        refresh_module,\\n        \\\"get_model_provider_policy_state\\\",\\n        AsyncMock(return_value=state),\\n    )\\n    monkeypatch.setattr(\\n        refresh_module,\\n        \\\"apply_model_provider_policy_state\\\",\\n        Mock(side_effect=RuntimeError(\\\"apply failed\\\")),\\n    )\\n    monkeypatch.setattr(refresh_module.logger, \\\"aerror\\\", AsyncMock())\\n\\n    changed = await refresh_module.ModelProviderPolicyRefreshWorker()._run_once()\\n\\n    assert service.approved_provider_ids == frozenset()\\n    assert changed is True\\n    assert service.policy_source_available is False\\n\\n\\nasync def test_refresh_loop_survives_an_iteration_failure(monkeypatch):\\n    worker = refresh_module.ModelProviderPolicyRefreshWorker(interval=0.001)\\n    calls = 0\\n    error_message = \\\"apply failed\\\"\\n\\n    async def run_once():\\n        nonlocal calls\\n        calls += 1\\n        if calls == 1:\\n            raise RuntimeError(error_message)\\n        worker._stop_event.set()\\n        return False\\n\\n    monkeypatch.setattr(worker, \\\"_run_once\\\", run_once)\\n    log_error = AsyncMock()\\n    monkeypatch.setattr(refresh_module.logger, \\\"aerror\\\", log_error)\\n\\n    await asyncio.wait_for(worker._run(), timeout=1)\\n\\n    assert calls == 2\\n    log_error.assert_awaited_once()\\n\\n\\nasync def test_start_uses_configured_interval_and_stop_clears_task(monkeypatch):\\n    service = ModelProviderPolicyService()\\n    settings_service = SimpleNamespace(\\n        settings=SimpleNamespace(model_provider_policy_refresh_interval_s=7.5),\\n    )\\n    worker = refresh_module.ModelProviderPolicyRefreshWorker()\\n    run_started = asyncio.Event()\\n    keep_running = asyncio.Event()\\n\\n    async def run():\\n        run_started.set()\\n        await keep_running.wait()\\n\\n    monkeypatch.setattr(refresh_module, \\\"get_model_provider_policy_service\\\", lambda: service)\\n    monkeypatch.setattr(refresh_module, \\\"get_settings_service\\\", lambda: settings_service)\\n    monkeypatch.setattr(worker, \\\"_run\\\", run)\\n\\n    await worker.start()\\n    await run_started.wait()\\n\\n    assert worker._active_interval == 7.5\\n    assert worker._task is not None\\n\\n    await worker.stop()\\n\\n    assert worker._task is None\\n\\n\\nasync def test_start_refreshes_a_database_owned_provider_plugin(monkeypatch):\\n    service = _DatabaseOwnedPluginPolicyService(PolicyBundleService())\\n    worker = refresh_module.ModelProviderPolicyRefreshWorker(interval=5)\\n    run_started = asyncio.Event()\\n    keep_running = asyncio.Event()\\n\\n    async def run():\\n        run_started.set()\\n        await keep_running.wait()\\n\\n    monkeypatch.setattr(refresh_module, \\\"get_model_provider_policy_service\\\", lambda: service)\\n    monkeypatch.setattr(worker, \\\"_run\\\", run)\\n\\n    await worker.start()\\n    await run_started.wait()\\n\\n    assert worker._task is not None\\n\\n    await worker.stop()\\n\\n\\nasync def test_refresh_failure_marks_a_restrictive_database_owned_plugin_unavailable(monkeypatch):\\n    bundle_service = PolicyBundleService()\\n    bundle_service.publish(\\n        PolicyBundleSnapshot(\\n            revision=3,\\n            initialized=True,\\n            source=\\\"api\\\",\\n            approved_provider_ids=frozenset({\\\"openai\\\"}),\\n        )\\n    )\\n    service = _DatabaseOwnedPluginPolicyService(bundle_service)\\n    error_message = \\\"policy store unavailable\\\"\\n\\n    @asynccontextmanager\\n    async def failing_session_scope():\\n        raise ConnectionError(error_message)\\n        yield\\n\\n    invalidate = Mock(wraps=service.invalidate)\\n    monkeypatch.setattr(service, \\\"invalidate\\\", invalidate)\\n    monkeypatch.setattr(refresh_module, \\\"session_scope\\\", failing_session_scope)\\n    monkeypatch.setattr(refresh_module, \\\"get_model_provider_policy_service\\\", lambda: service)\\n    monkeypatch.setattr(refresh_module, \\\"get_policy_bundle_service\\\", lambda: bundle_service)\\n    monkeypatch.setattr(refresh_module.logger, \\\"aerror\\\", AsyncMock())\\n\\n    changed = await refresh_module.ModelProviderPolicyRefreshWorker()._run_once()\\n\\n    assert changed is True\\n    assert bundle_service.source_available is False\\n    invalidate.assert_called_once_with()\\n\\n\\nasync def test_start_skips_explicitly_external_builtin_subclass(monkeypatch):\\n    service = _ExternalBuiltinPolicyService()\\n    worker = refresh_module.ModelProviderPolicyRefreshWorker()\\n    debug = AsyncMock()\\n    monkeypatch.setattr(refresh_module, \\\"get_model_provider_policy_service\\\", lambda: service)\\n    monkeypatch.setattr(\\n        refresh_module,\\n        \\\"get_catalog_policy_service\\\",\\n        lambda: SimpleNamespace(external_policy_snapshot=object()),\\n    )\\n    monkeypatch.setattr(refresh_module.logger, \\\"adebug\\\", debug)\\n\\n    await worker.start()\\n\\n    assert worker._task is None\\n    debug.assert_awaited_once_with(\\n        \\\"Policy-bundle refresh worker not started: provider and catalog policies are externally managed\\\"\\n    )\\n\\n\\nasync def test_start_refreshes_database_catalog_when_provider_policy_is_external(monkeypatch):\\n    service = _ExternalBuiltinPolicyService()\\n    worker = refresh_module.ModelProviderPolicyRefreshWorker(interval=5)\\n    run_started = asyncio.Event()\\n    keep_running = asyncio.Event()\\n\\n    async def run():\\n        run_started.set()\\n        await keep_running.wait()\\n\\n    monkeypatch.setattr(refresh_module, \\\"get_model_provider_policy_service\\\", lambda: service)\\n    monkeypatch.setattr(\\n        refresh_module,\\n        \\\"get_catalog_policy_service\\\",\\n        lambda: SimpleNamespace(external_policy_snapshot=None),\\n    )\\n    monkeypatch.setattr(worker, \\\"_run\\\", run)\\n\\n    await worker.start()\\n    await run_started.wait()\\n\\n    assert worker._task is not None\\n\\n    await worker.stop()\\n\\n\\nasync def test_refresh_failure_does_not_fail_close_explicitly_external_builtin_subclass(monkeypatch):\\n    service = _ExternalBuiltinPolicyService()\\n    error_message = \\\"policy store unavailable\\\"\\n\\n    @asynccontextmanager\\n    async def failing_session_scope():\\n        raise ConnectionError(error_message)\\n        yield\\n\\n    fail_closed = Mock(wraps=service.fail_closed)\\n    monkeypatch.setattr(service, \\\"fail_closed\\\", fail_closed)\\n    monkeypatch.setattr(refresh_module, \\\"session_scope\\\", failing_session_scope)\\n    monkeypatch.setattr(refresh_module, \\\"get_model_provider_policy_service\\\", lambda: service)\\n    monkeypatch.setattr(refresh_module.logger, \\\"aerror\\\", AsyncMock())\\n\\n    changed = await refresh_module.ModelProviderPolicyRefreshWorker()._run_once()\\n\\n    assert changed is False\\n    assert service.approved_provider_ids == frozenset({\\\"openai\\\"})\\n    fail_closed.assert_not_called()\\n\\n\\nasync def test_start_replaces_a_completed_refresh_task(monkeypatch):\\n    service = ModelProviderPolicyService()\\n    worker = refresh_module.ModelProviderPolicyRefreshWorker(interval=5)\\n    previous = asyncio.create_task(asyncio.sleep(0))\\n    await previous\\n    worker._task = previous\\n    run_started = asyncio.Event()\\n    keep_running = asyncio.Event()\\n\\n    async def run():\\n        run_started.set()\\n        await keep_running.wait()\\n\\n    monkeypatch.setattr(refresh_module, \\\"get_model_provider_policy_service\\\", lambda: service)\\n    monkeypatch.setattr(worker, \\\"_run\\\", run)\\n\\n    await worker.start()\\n    await run_started.wait()\\n\\n    assert worker._task is not previous\\n    assert worker._task is not None\\n\\n    await worker.stop()\\n\\n\\nasync def test_stop_clears_a_failed_task_without_reraising():\\n    worker = refresh_module.ModelProviderPolicyRefreshWorker(interval=5)\\n    error_message = \\\"task failed\\\"\\n\\n    async def fail():\\n        raise RuntimeError(error_message)\\n\\n    task = asyncio.create_task(fail())\\n    await asyncio.sleep(0)\\n    worker._task = task\\n\\n    await worker.stop()\\n\\n    assert worker._task is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/test_model_provider_policy_store.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"036c548e4d4b7118bebf396b01b1cd044381f02dc740ce71e2bf13d845a8396b\",\"content\":\"from __future__ import annotations\\n\\nimport asyncio\\nfrom contextlib import asynccontextmanager\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock, Mock\\n\\nimport pytest\\nfrom langflow.services import model_provider_policy as policy_store\\nfrom langflow.services.database.models.model_provider_policy import ModelProviderPolicy\\nfrom langflow.services.task import model_provider_policy_refresh as refresh_module\\nfrom lfx.services.catalog_policy import CatalogPolicyService\\nfrom lfx.services.model_provider_policy import BaseModelProviderPolicyService, ModelProviderPolicyService\\nfrom lfx.services.policy_bundle import PolicyBundleService, PolicyBundleSnapshot\\nfrom sqlalchemy.dialects import postgresql, sqlite\\nfrom sqlalchemy.ext.asyncio import async_sessionmaker, create_async_engine\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\n\\nclass _Result:\\n    def __init__(self, row, *, rowcount: int = 1):\\n        self._row = row\\n        self.rowcount = rowcount\\n\\n    def one_or_none(self):\\n        return self._row\\n\\n\\nclass _ReadSession:\\n    def __init__(self, provider_ids: list[str], *, version: int):\\n        self._row = SimpleNamespace(approved_provider_ids=provider_ids, version=version)\\n\\n    async def exec(self, _statement):\\n        return _Result(self._row)\\n\\n\\nasync def test_hydrate_model_provider_policy_restores_persisted_ceiling(monkeypatch):\\n    service = ModelProviderPolicyService()\\n    monkeypatch.setattr(policy_store, \\\"get_model_provider_policy_service\\\", lambda: service)\\n\\n    state = await policy_store.hydrate_model_provider_policy(_ReadSession([\\\"openai\\\", \\\"anthropic\\\"], version=4))\\n\\n    assert state == policy_store.PersistedModelProviderPolicy(\\n        approved_provider_ids=frozenset({\\\"openai\\\", \\\"anthropic\\\"}),\\n        version=4,\\n    )\\n    assert service.approved_provider_ids == state.approved_provider_ids\\n    assert service.policy_version == 4\\n\\n\\nasync def test_hydrate_empty_store_preserves_allow_all(monkeypatch):\\n    service = ModelProviderPolicyService()\\n    service.set_approved_provider_ids({\\\"openai\\\"}, version=1)\\n    monkeypatch.setattr(policy_store, \\\"get_model_provider_policy_service\\\", lambda: service)\\n\\n    await policy_store.hydrate_model_provider_policy(_ReadSession([], version=2))\\n\\n    assert not service.approved_provider_ids\\n    assert service.policy_version == 2\\n\\n\\ndef test_legacy_third_party_policy_service_is_invalidated_without_replacing_its_source(monkeypatch):\\n    class LegacyPolicyService(BaseModelProviderPolicyService):\\n        def get_allowed_provider_ids(self, *, context, candidate_provider_ids, purpose):\\n            _ = (context, purpose)\\n            return candidate_provider_ids\\n\\n    service = LegacyPolicyService()\\n    invalidate = Mock(wraps=service.invalidate)\\n    monkeypatch.setattr(service, \\\"invalidate\\\", invalidate)\\n    monkeypatch.setattr(policy_store, \\\"get_model_provider_policy_service\\\", lambda: service)\\n    state = policy_store.PersistedModelProviderPolicy(\\n        approved_provider_ids=frozenset({\\\"openai\\\"}),\\n        version=3,\\n    )\\n\\n    assert policy_store.apply_model_provider_policy_state(state)\\n    invalidate.assert_called_once_with()\\n\\n\\n@pytest.mark.parametrize(\\\"external_ids\\\", [frozenset({\\\"openai\\\"}), frozenset()])\\ndef test_explicitly_external_policy_service_is_not_invalidated(monkeypatch, external_ids):\\n    class ExternalPolicyService(BaseModelProviderPolicyService):\\n        def __init__(self) -> None:\\n            super().__init__()\\n            self.set_ready()\\n\\n        @property\\n        def external_approved_provider_ids(self) -> frozenset[str]:\\n            return external_ids\\n\\n        def get_allowed_provider_ids(self, *, context, candidate_provider_ids, purpose):\\n            _ = (context, purpose)\\n            return candidate_provider_ids & external_ids\\n\\n    service = ExternalPolicyService()\\n    invalidate = Mock(wraps=service.invalidate)\\n    monkeypatch.setattr(service, \\\"invalidate\\\", invalidate)\\n    monkeypatch.setattr(policy_store, \\\"get_model_provider_policy_service\\\", lambda: service)\\n    state = policy_store.PersistedModelProviderPolicy(\\n        approved_provider_ids=frozenset({\\\"anthropic\\\"}),\\n        version=3,\\n    )\\n\\n    assert policy_store.apply_model_provider_policy_state(state) is False\\n    invalidate.assert_not_called()\\n\\n\\ndef test_explicitly_external_builtin_subclass_does_not_receive_database_state(monkeypatch):\\n    class ExternalBuiltinPolicyService(ModelProviderPolicyService):\\n        @property\\n        def external_approved_provider_ids(self) -> frozenset[str]:\\n            return frozenset({\\\"openai\\\"})\\n\\n    service = ExternalBuiltinPolicyService()\\n    service.set_approved_provider_ids({\\\"openai\\\"}, version=2)\\n    monkeypatch.setattr(policy_store, \\\"get_model_provider_policy_service\\\", lambda: service)\\n    state = policy_store.PersistedModelProviderPolicy(\\n        approved_provider_ids=frozenset(),\\n        version=3,\\n    )\\n\\n    assert policy_store.apply_model_provider_policy_state(state) is False\\n    assert service.approved_provider_ids == frozenset({\\\"openai\\\"})\\n    assert service.policy_version == 2\\n\\n\\ndef test_external_provider_does_not_block_database_owned_catalog_bundle_refresh(monkeypatch):\\n    class ExternalBuiltinPolicyService(ModelProviderPolicyService):\\n        @property\\n        def external_approved_provider_ids(self) -> frozenset[str]:\\n            return frozenset({\\\"openai\\\"})\\n\\n    provider_service = ExternalBuiltinPolicyService()\\n    provider_service.set_approved_provider_ids({\\\"openai\\\"}, version=2)\\n    bundle_service = PolicyBundleService()\\n    catalog_service = CatalogPolicyService(bundle_service)\\n    snapshot = PolicyBundleSnapshot(\\n        revision=3,\\n        initialized=True,\\n        source=\\\"api\\\",\\n        approved_provider_ids=frozenset({\\\"anthropic\\\"}),\\n        blocked_component_keys=frozenset({\\\"PythonREPL\\\"}),\\n    )\\n    state = policy_store.PersistedModelProviderPolicy(\\n        approved_provider_ids=snapshot.approved_provider_ids,\\n        version=snapshot.revision,\\n        bundle_snapshot=snapshot,\\n    )\\n\\n    monkeypatch.setattr(policy_store, \\\"get_model_provider_policy_service\\\", lambda: provider_service)\\n    monkeypatch.setattr(\\\"lfx.services.deps.get_model_provider_policy_service\\\", lambda: provider_service)\\n    monkeypatch.setattr(\\\"lfx.services.deps.get_policy_bundle_service\\\", lambda: bundle_service)\\n    monkeypatch.setattr(\\\"lfx.services.deps.get_catalog_policy_service\\\", lambda: catalog_service)\\n\\n    assert policy_store.apply_model_provider_policy_state(state) is True\\n    assert bundle_service.snapshot is snapshot\\n    assert catalog_service.is_component_blocked(\\\"PythonREPL\\\") is True\\n    assert provider_service.approved_provider_ids == frozenset({\\\"openai\\\"})\\n\\n\\ndef test_replacement_is_one_atomic_versioned_update():\\n    statement = policy_store._replace_policy_statement([\\\"openai\\\"])\\n    postgres_sql = str(statement.compile(dialect=postgresql.dialect()))\\n    sqlite_sql = str(statement.compile(dialect=sqlite.dialect()))\\n\\n    for compiled in (postgres_sql, sqlite_sql):\\n        assert compiled.startswith(\\\"UPDATE model_provider_policy SET\\\")\\n        assert \\\"version=(model_provider_policy.version + \\\" in compiled\\n        assert \\\"RETURNING\\\" not in compiled\\n\\n\\nasync def test_concurrent_sqlite_replacements_keep_complete_sets_and_distinct_versions(tmp_path):\\n    engine = create_async_engine(\\n        f\\\"sqlite+aiosqlite:///{tmp_path / 'model-provider-policy.db'}\\\",\\n        connect_args={\\\"timeout\\\": 30},\\n    )\\n    session_maker = async_sessionmaker(engine, class_=AsyncSession, expire_on_commit=False)\\n    try:\\n        async with engine.begin() as connection:\\n            await connection.run_sync(ModelProviderPolicy.__table__.create)\\n        async with session_maker() as session:\\n            session.add(ModelProviderPolicy())\\n            await session.commit()\\n\\n        async def replace(provider_ids: set[str]):\\n            async with session_maker() as session:\\n                return await policy_store.replace_model_provider_policy_state(session, provider_ids)\\n\\n        first, second = await asyncio.gather(\\n            replace({\\\"openai\\\"}),\\n            replace({\\\"anthropic\\\"}),\\n        )\\n\\n        async with session_maker() as session:\\n            persisted = await policy_store.get_model_provider_policy_state(session)\\n\\n        assert {first.version, second.version} == {1, 2}\\n        assert persisted.version == 2\\n        assert persisted.approved_provider_ids in (\\n            frozenset({\\\"openai\\\"}),\\n            frozenset({\\\"anthropic\\\"}),\\n        )\\n    finally:\\n        await engine.dispose()\\n\\n\\nasync def test_missing_sqlite_singleton_is_never_treated_as_unrestricted(tmp_path):\\n    engine = create_async_engine(f\\\"sqlite+aiosqlite:///{tmp_path / 'missing-model-provider-policy.db'}\\\")\\n    session_maker = async_sessionmaker(engine, class_=AsyncSession, expire_on_commit=False)\\n    try:\\n        async with engine.begin() as connection:\\n            await connection.run_sync(ModelProviderPolicy.__table__.create)\\n\\n        async with session_maker() as session:\\n            with pytest.raises(policy_store.ModelProviderPolicyNotInitializedError, match=\\\"migrations\\\"):\\n                await policy_store.get_model_provider_policy_state(session)\\n            with pytest.raises(policy_store.ModelProviderPolicyNotInitializedError, match=\\\"migrations\\\"):\\n                await policy_store.replace_model_provider_policy_state(session, {\\\"openai\\\"})\\n    finally:\\n        await engine.dispose()\\n\\n\\nasync def test_replace_refreshes_a_row_already_loaded_in_the_identity_map(tmp_path):\\n    engine = create_async_engine(f\\\"sqlite+aiosqlite:///{tmp_path / 'fresh-model-provider-policy.db'}\\\")\\n    session_maker = async_sessionmaker(engine, class_=AsyncSession, expire_on_commit=False)\\n    try:\\n        async with engine.begin() as connection:\\n            await connection.run_sync(ModelProviderPolicy.__table__.create)\\n\\n        async with session_maker() as session:\\n            session.add(ModelProviderPolicy())\\n            await session.commit()\\n            cached = await session.get(ModelProviderPolicy, 1)\\n            assert cached is not None\\n\\n            state = await policy_store.replace_model_provider_policy_state(session, {\\\"openai\\\"})\\n\\n            assert state == policy_store.PersistedModelProviderPolicy(\\n                approved_provider_ids=frozenset({\\\"openai\\\"}),\\n                version=1,\\n            )\\n            assert cached.approved_provider_ids == [\\\"openai\\\"]\\n            assert cached.version == 1\\n    finally:\\n        await engine.dispose()\\n\\n\\nasync def test_second_worker_refreshes_a_committed_policy_version(monkeypatch):\\n    state = policy_store.PersistedModelProviderPolicy(\\n        approved_provider_ids=frozenset({\\\"openai\\\"}),\\n        version=8,\\n    )\\n    handling_worker = ModelProviderPolicyService()\\n    other_worker = ModelProviderPolicyService()\\n\\n    monkeypatch.setattr(policy_store, \\\"get_model_provider_policy_service\\\", lambda: handling_worker)\\n    policy_store.apply_model_provider_policy_state(state)\\n\\n    @asynccontextmanager\\n    async def session_scope():\\n        yield _ReadSession([\\\"openai\\\"], version=8)\\n\\n    monkeypatch.setattr(refresh_module, \\\"session_scope\\\", session_scope)\\n    monkeypatch.setattr(policy_store, \\\"get_model_provider_policy_service\\\", lambda: other_worker)\\n\\n    changed = await refresh_module.ModelProviderPolicyRefreshWorker()._run_once()\\n\\n    assert changed is True\\n    assert handling_worker.approved_provider_ids == frozenset({\\\"openai\\\"})\\n    assert other_worker.approved_provider_ids == frozenset({\\\"openai\\\"})\\n    assert other_worker.policy_version == 8\\n\\n\\nasync def test_refresh_skips_unchanged_version_without_invalidating_cache(monkeypatch):\\n    service = ModelProviderPolicyService()\\n    service.set_approved_provider_ids({\\\"openai\\\"}, version=8)\\n\\n    @asynccontextmanager\\n    async def session_scope():\\n        yield _ReadSession([\\\"openai\\\"], version=8)\\n\\n    monkeypatch.setattr(refresh_module, \\\"session_scope\\\", session_scope)\\n    monkeypatch.setattr(policy_store, \\\"get_model_provider_policy_service\\\", lambda: service)\\n    invalidate = Mock(wraps=service.invalidate)\\n    monkeypatch.setattr(service, \\\"invalidate\\\", invalidate)\\n\\n    changed = await refresh_module.ModelProviderPolicyRefreshWorker()._run_once()\\n\\n    assert changed is False\\n    invalidate.assert_not_called()\\n\\n\\nasync def test_refresh_failure_denies_all_until_the_store_recovers(monkeypatch):\\n    service = ModelProviderPolicyService()\\n    service.set_approved_provider_ids({\\\"openai\\\", \\\"anthropic\\\"}, version=8)\\n    error_message = \\\"policy store unavailable\\\"\\n\\n    @asynccontextmanager\\n    async def failing_session_scope():\\n        raise ConnectionError(error_message)\\n        yield\\n\\n    monkeypatch.setattr(refresh_module, \\\"session_scope\\\", failing_session_scope)\\n    monkeypatch.setattr(refresh_module, \\\"get_model_provider_policy_service\\\", lambda: service)\\n    monkeypatch.setattr(\\n        refresh_module.logger,\\n        \\\"aerror\\\",\\n        AsyncMock(side_effect=RuntimeError(error_message)),\\n    )\\n\\n    changed = await refresh_module.ModelProviderPolicyRefreshWorker()._run_once()\\n\\n    assert changed is True\\n    assert service.policy_source_available is False\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/test_policy_bundle_store.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"52964e31e95f6b36447b07ec0a9b46ec5dd09fcb78ec884b405285953a13669c\",\"content\":\"\\\"\\\"\\\"Atomic store and cross-worker runtime tests for shared policy bundles.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nfrom contextlib import asynccontextmanager\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services import deps as langflow_service_deps\\nfrom langflow.services import policy_bundle as policy_store\\nfrom langflow.services.database.models.catalog_policy import CatalogPolicyRule, CatalogResourceKind\\nfrom langflow.services.database.models.model_provider_policy import ModelProviderPolicy\\nfrom langflow.services.database.models.policy_bundle import PolicyBundleActive, PolicyBundleRevision\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.task import model_provider_policy_refresh as refresh_module\\nfrom lfx.services import deps as lfx_service_deps\\nfrom lfx.services.catalog_policy import CatalogPolicyService\\nfrom lfx.services.catalog_policy.base import BaseCatalogPolicyService, CatalogPolicySnapshot\\nfrom lfx.services.model_provider_policy import ModelProviderPolicyService\\nfrom lfx.services.policy_bundle import PolicyBundleService, PolicyBundleSnapshot\\nfrom sqlalchemy.ext.asyncio import async_sessionmaker, create_async_engine\\nfrom sqlmodel import SQLModel, select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\n_INITIAL_PROVIDERS = frozenset({\\\"openai\\\"})\\n_INITIAL_COMPONENTS = frozenset({\\\"OldComponent\\\"})\\n_INITIAL_TEMPLATES = frozenset({\\\"old-template\\\"})\\n\\n\\ndef test_policy_bundle_revision_resolves_created_by_for_validation_and_schema():\\n    actor_id = uuid4()\\n    revision = PolicyBundleRevision.model_validate(\\n        {\\n            \\\"revision\\\": 1,\\n            \\\"initialized\\\": True,\\n            \\\"approved_provider_ids\\\": [],\\n            \\\"blocked_component_keys\\\": [],\\n            \\\"blocked_template_keys\\\": [],\\n            \\\"content_hash\\\": \\\"0\\\" * 64,\\n            \\\"created_by\\\": str(actor_id),\\n        }\\n    )\\n\\n    assert revision.created_by == actor_id\\n    assert \\\"created_by\\\" in PolicyBundleRevision.model_json_schema()[\\\"properties\\\"]\\n    assert all(foreign_key.parent.name != \\\"created_by\\\" for foreign_key in PolicyBundleRevision.__table__.foreign_keys)\\n\\n\\n@pytest.fixture\\nasync def bundle_session_maker(tmp_path):\\n    engine = create_async_engine(\\n        f\\\"sqlite+aiosqlite:///{tmp_path / 'policy-bundle.db'}\\\",\\n        connect_args={\\\"timeout\\\": 30},\\n    )\\n    session_maker = async_sessionmaker(engine, class_=AsyncSession, expire_on_commit=False)\\n    async with engine.begin() as connection:\\n        await connection.run_sync(\\n            lambda sync_connection: SQLModel.metadata.create_all(\\n                sync_connection,\\n                tables=[\\n                    User.__table__,\\n                    ModelProviderPolicy.__table__,\\n                    CatalogPolicyRule.__table__,\\n                    PolicyBundleRevision.__table__,\\n                    PolicyBundleActive.__table__,\\n                ],\\n            )\\n        )\\n\\n    initial_hash = policy_store.policy_bundle_content_hash(\\n        approved_provider_ids=_INITIAL_PROVIDERS,\\n        blocked_component_keys=_INITIAL_COMPONENTS,\\n        blocked_template_keys=_INITIAL_TEMPLATES,\\n    )\\n    async with session_maker() as session:\\n        session.add_all(\\n            [\\n                PolicyBundleRevision(\\n                    revision=1,\\n                    initialized=True,\\n                    approved_provider_ids=sorted(_INITIAL_PROVIDERS),\\n                    blocked_component_keys=sorted(_INITIAL_COMPONENTS),\\n                    blocked_template_keys=sorted(_INITIAL_TEMPLATES),\\n                    content_hash=initial_hash,\\n                    source=\\\"migration\\\",\\n                    reason=\\\"initial\\\",\\n                ),\\n                PolicyBundleActive(revision=1, initialized=True),\\n                ModelProviderPolicy(\\n                    approved_provider_ids=sorted(_INITIAL_PROVIDERS),\\n                    version=1,\\n                ),\\n                CatalogPolicyRule(\\n                    resource_kind=CatalogResourceKind.COMPONENT.value,\\n                    resource_key=\\\"OldComponent\\\",\\n                ),\\n                CatalogPolicyRule(\\n                    resource_kind=CatalogResourceKind.TEMPLATE.value,\\n                    resource_key=\\\"old-template\\\",\\n                ),\\n            ]\\n        )\\n        await session.commit()\\n\\n    yield session_maker\\n    await engine.dispose()\\n\\n\\nasync def _read_active(session_maker) -> PolicyBundleSnapshot:\\n    async with session_maker() as session:\\n        return await policy_store.get_policy_bundle_state(session)\\n\\n\\ndef _bundle_value(snapshot: PolicyBundleSnapshot) -> tuple:\\n    \\\"\\\"\\\"Compare persisted semantics without depending on SQLite timezone reflection.\\\"\\\"\\\"\\n    timestamp = snapshot.created_at.replace(tzinfo=None) if snapshot.created_at is not None else None\\n    return (\\n        snapshot.revision,\\n        snapshot.approved_provider_ids,\\n        snapshot.blocked_component_keys,\\n        snapshot.blocked_template_keys,\\n        snapshot.content_hash,\\n        snapshot.created_by,\\n        timestamp,\\n        snapshot.reason,\\n        snapshot.rollback_of_revision,\\n    )\\n\\n\\nasync def test_concurrent_cas_replacements_commit_one_complete_bundle_without_mixing_facets(\\n    bundle_session_maker,\\n):\\n    actor_id = uuid4()\\n    proposals = [\\n        {\\n            \\\"approved_provider_ids\\\": {\\\"anthropic\\\"},\\n            \\\"blocked_component_keys\\\": {\\\"AnthropicModel\\\"},\\n            \\\"blocked_template_keys\\\": {\\\"anthropic-template\\\"},\\n            \\\"reason\\\": \\\"anthropic policy\\\",\\n        },\\n        {\\n            \\\"approved_provider_ids\\\": {\\\"google.generativeai\\\"},\\n            \\\"blocked_component_keys\\\": {\\\"GoogleModel\\\"},\\n            \\\"blocked_template_keys\\\": {\\\"google-template\\\"},\\n            \\\"reason\\\": \\\"google policy\\\",\\n        },\\n    ]\\n\\n    async def replace(proposal):\\n        async with bundle_session_maker() as session:\\n            return await policy_store.replace_policy_bundle_state(\\n                session,\\n                expected_revision=1,\\n                actor_user_id=actor_id,\\n                **proposal,\\n            )\\n\\n    results = await asyncio.gather(*(replace(proposal) for proposal in proposals), return_exceptions=True)\\n    committed = [result for result in results if isinstance(result, PolicyBundleSnapshot)]\\n    conflicts = [result for result in results if isinstance(result, policy_store.PolicyBundleRevisionConflictError)]\\n\\n    assert len(committed) == 1\\n    assert len(conflicts) == 1\\n    assert conflicts[0].expected_revision == 1\\n    assert conflicts[0].active_revision == 2\\n\\n    persisted = await _read_active(bundle_session_maker)\\n    complete_states = {\\n        (\\n            frozenset(proposal[\\\"approved_provider_ids\\\"]),\\n            frozenset(proposal[\\\"blocked_component_keys\\\"]),\\n            frozenset(proposal[\\\"blocked_template_keys\\\"]),\\n        )\\n        for proposal in proposals\\n    }\\n    assert persisted.revision == 2\\n    assert persisted.initialized is True\\n    assert persisted.source == \\\"api\\\"\\n    assert (\\n        persisted.approved_provider_ids,\\n        persisted.blocked_component_keys,\\n        persisted.blocked_template_keys,\\n    ) in complete_states\\n    assert _bundle_value(persisted) == _bundle_value(committed[0])\\n\\n    async with bundle_session_maker() as session:\\n        history = await policy_store.list_policy_bundle_history(session)\\n        legacy_provider = await session.get(ModelProviderPolicy, 1)\\n        legacy_rules = list((await session.exec(select(CatalogPolicyRule))).all())\\n\\n    assert [snapshot.revision for snapshot in history] == [2, 1]\\n    assert legacy_provider is not None\\n    assert legacy_provider.version == persisted.revision\\n    assert frozenset(legacy_provider.approved_provider_ids) == persisted.approved_provider_ids\\n    assert {\\n        row.resource_key for row in legacy_rules if row.resource_kind == CatalogResourceKind.COMPONENT.value\\n    } == persisted.blocked_component_keys\\n    assert {\\n        row.resource_key for row in legacy_rules if row.resource_kind == CatalogResourceKind.TEMPLATE.value\\n    } == persisted.blocked_template_keys\\n\\n\\nasync def test_rollback_copies_old_content_into_a_new_immutable_revision(bundle_session_maker):\\n    first_actor = uuid4()\\n    rollback_actor = uuid4()\\n    async with bundle_session_maker() as session:\\n        revision_two = await policy_store.replace_policy_bundle_state(\\n            session,\\n            expected_revision=1,\\n            approved_provider_ids={\\\"anthropic\\\"},\\n            blocked_component_keys={\\\"SecondComponent\\\"},\\n            blocked_template_keys={\\\"second-template\\\"},\\n            actor_user_id=first_actor,\\n            reason=\\\"second\\\",\\n        )\\n    async with bundle_session_maker() as session:\\n        revision_three = await policy_store.replace_policy_bundle_state(\\n            session,\\n            expected_revision=revision_two.revision,\\n            approved_provider_ids={\\\"google.generativeai\\\"},\\n            blocked_component_keys={\\\"ThirdComponent\\\"},\\n            blocked_template_keys={\\\"third-template\\\"},\\n            actor_user_id=first_actor,\\n            reason=\\\"third\\\",\\n        )\\n    async with bundle_session_maker() as session:\\n        rolled_back = await policy_store.rollback_policy_bundle_state(\\n            session,\\n            expected_revision=revision_three.revision,\\n            target_revision=1,\\n            actor_user_id=rollback_actor,\\n            reason=\\\"incident rollback\\\",\\n        )\\n\\n    assert rolled_back.revision == 4\\n    assert rolled_back.initialized is True\\n    assert rolled_back.source == \\\"rollback\\\"\\n    assert rolled_back.approved_provider_ids == _INITIAL_PROVIDERS\\n    assert rolled_back.blocked_component_keys == _INITIAL_COMPONENTS\\n    assert rolled_back.blocked_template_keys == _INITIAL_TEMPLATES\\n    assert rolled_back.rollback_of_revision == 1\\n    assert rolled_back.created_by == rollback_actor\\n    assert rolled_back.reason == \\\"incident rollback\\\"\\n\\n    async with bundle_session_maker() as session:\\n        history = await policy_store.list_policy_bundle_history(session)\\n\\n    assert [snapshot.revision for snapshot in history] == [4, 3, 2, 1]\\n    by_revision = {snapshot.revision: snapshot for snapshot in history}\\n    assert by_revision[1].reason == \\\"initial\\\"\\n    assert _bundle_value(by_revision[2]) == _bundle_value(revision_two)\\n    assert _bundle_value(by_revision[3]) == _bundle_value(revision_three)\\n    assert by_revision[1].content_hash == rolled_back.content_hash\\n    assert by_revision[2].rollback_of_revision is None\\n    assert by_revision[3].rollback_of_revision is None\\n\\n\\nasync def test_stale_expected_revision_leaves_active_state_and_history_unchanged(bundle_session_maker):\\n    async with bundle_session_maker() as session:\\n        current = await policy_store.replace_policy_bundle_state(\\n            session,\\n            expected_revision=1,\\n            approved_provider_ids={\\\"anthropic\\\"},\\n            blocked_component_keys={\\\"CurrentComponent\\\"},\\n            blocked_template_keys={\\\"current-template\\\"},\\n            actor_user_id=uuid4(),\\n        )\\n\\n    async with bundle_session_maker() as session:\\n        with pytest.raises(policy_store.PolicyBundleRevisionConflictError) as exc_info:\\n            await policy_store.replace_policy_bundle_state(\\n                session,\\n                expected_revision=1,\\n                approved_provider_ids={\\\"openai\\\"},\\n                blocked_component_keys={\\\"StaleComponent\\\"},\\n                blocked_template_keys={\\\"stale-template\\\"},\\n                actor_user_id=uuid4(),\\n            )\\n\\n    assert exc_info.value.expected_revision == 1\\n    assert exc_info.value.active_revision == 2\\n    assert _bundle_value(await _read_active(bundle_session_maker)) == _bundle_value(current)\\n    async with bundle_session_maker() as session:\\n        assert [item.revision for item in await policy_store.list_policy_bundle_history(session)] == [2, 1]\\n\\n\\nasync def test_environment_bootstrap_initializes_a_pristine_bundle_exactly_once(bundle_session_maker):\\n    empty_hash = policy_store.policy_bundle_content_hash(\\n        approved_provider_ids=[],\\n        blocked_component_keys=[],\\n        blocked_template_keys=[],\\n    )\\n    async with bundle_session_maker() as session:\\n        active = await session.get(PolicyBundleActive, 1)\\n        initial = await session.get(PolicyBundleRevision, 1)\\n        legacy_provider = await session.get(ModelProviderPolicy, 1)\\n        assert active is not None\\n        assert initial is not None\\n        assert legacy_provider is not None\\n        active.initialized = False\\n        initial.initialized = False\\n        initial.approved_provider_ids = []\\n        initial.blocked_component_keys = []\\n        initial.blocked_template_keys = []\\n        initial.content_hash = empty_hash\\n        legacy_provider.approved_provider_ids = []\\n        legacy_provider.version = 0\\n        for rule in list((await session.exec(select(CatalogPolicyRule))).all()):\\n            await session.delete(rule)\\n        await session.commit()\\n\\n    async with bundle_session_maker() as session:\\n        bootstrapped, created = await policy_store.bootstrap_policy_bundle_if_pristine(\\n            session,\\n            approved_provider_ids={\\\"anthropic\\\"},\\n            blocked_component_keys={\\\"EnvironmentComponent\\\"},\\n            blocked_template_keys={\\\"environment-template\\\"},\\n            reason=\\\"deployment bootstrap\\\",\\n        )\\n    async with bundle_session_maker() as session:\\n        repeated, repeated_created = await policy_store.bootstrap_policy_bundle_if_pristine(\\n            session,\\n            approved_provider_ids={\\\"openai\\\"},\\n            blocked_component_keys={\\\"MustNotReplace\\\"},\\n            blocked_template_keys={\\\"must-not-replace\\\"},\\n        )\\n\\n    assert created is True\\n    assert bootstrapped.revision == 2\\n    assert bootstrapped.initialized is True\\n    assert bootstrapped.source == \\\"environment\\\"\\n    assert bootstrapped.approved_provider_ids == frozenset({\\\"anthropic\\\"})\\n    assert repeated_created is False\\n    assert _bundle_value(repeated) == _bundle_value(bootstrapped)\\n    async with bundle_session_maker() as session:\\n        history = await policy_store.list_policy_bundle_history(session)\\n        pristine = await policy_store.get_policy_bundle_state(session, revision=1)\\n    assert [(item.revision, item.initialized) for item in history] == [(2, True), (1, False)]\\n    assert pristine.initialized is False\\n\\n\\ndef test_runtime_publishes_one_immutable_snapshot_for_provider_and_catalog_facets(monkeypatch):\\n    bundle_service = PolicyBundleService()\\n    catalog_service = CatalogPolicyService(bundle_service)\\n    provider_service = ModelProviderPolicyService(bundle_service)\\n    old_snapshot = bundle_service.snapshot\\n    new_snapshot = PolicyBundleSnapshot(\\n        revision=9,\\n        initialized=True,\\n        source=\\\"api\\\",\\n        approved_provider_ids={\\\"anthropic\\\"},\\n        blocked_component_keys={\\\"OpenAIModel\\\"},\\n        blocked_template_keys={\\\"starter-template\\\"},\\n        content_hash=\\\"9\\\" * 64,\\n        reason=\\\"one atomic publication\\\",\\n    )\\n    monkeypatch.setattr(langflow_service_deps, \\\"get_policy_bundle_service\\\", lambda: bundle_service)\\n    monkeypatch.setattr(langflow_service_deps, \\\"get_catalog_policy_service\\\", lambda: catalog_service)\\n    monkeypatch.setattr(lfx_service_deps, \\\"get_policy_bundle_service\\\", lambda: bundle_service)\\n    monkeypatch.setattr(lfx_service_deps, \\\"get_catalog_policy_service\\\", lambda: catalog_service)\\n    monkeypatch.setattr(lfx_service_deps, \\\"get_model_provider_policy_service\\\", lambda: provider_service)\\n\\n    assert policy_store.apply_policy_bundle_state(new_snapshot) is True\\n\\n    assert bundle_service.snapshot is new_snapshot\\n    assert catalog_service.policy_bundle_snapshot is new_snapshot\\n    assert provider_service.approved_provider_ids == new_snapshot.approved_provider_ids\\n    assert provider_service.policy_version == new_snapshot.revision\\n    assert catalog_service.snapshot.blocked_component_keys == new_snapshot.blocked_component_keys\\n    assert catalog_service.snapshot.blocked_template_keys == new_snapshot.blocked_template_keys\\n    assert old_snapshot == PolicyBundleSnapshot()\\n\\n\\ndef test_runtime_applies_bundle_to_database_owned_catalog_plugin_with_independent_state(monkeypatch):\\n    class IndependentCatalogPolicy(BaseCatalogPolicyService):\\n        def __init__(self) -> None:\\n            super().__init__()\\n            self._snapshot = CatalogPolicySnapshot()\\n            self.applied: list[PolicyBundleSnapshot] = []\\n            self.set_ready()\\n\\n        @property\\n        def snapshot(self) -> CatalogPolicySnapshot:\\n            return self._snapshot\\n\\n        @property\\n        def supports_policy_bundle_updates(self) -> bool:\\n            return True\\n\\n        def apply_policy_bundle(self, snapshot: PolicyBundleSnapshot) -> bool:\\n            self.applied.append(snapshot)\\n            self._snapshot = CatalogPolicySnapshot(\\n                blocked_component_keys=snapshot.blocked_component_keys,\\n                blocked_template_keys=snapshot.blocked_template_keys,\\n            )\\n            return True\\n\\n    bundle_service = PolicyBundleService()\\n    catalog_service = IndependentCatalogPolicy()\\n    provider_service = ModelProviderPolicyService(bundle_service)\\n    snapshot = PolicyBundleSnapshot(\\n        revision=4,\\n        initialized=True,\\n        source=\\\"api\\\",\\n        approved_provider_ids={\\\"openai\\\"},\\n        blocked_component_keys={\\\"PythonREPL\\\"},\\n        blocked_template_keys={\\\"Starter\\\"},\\n        content_hash=\\\"4\\\" * 64,\\n    )\\n    monkeypatch.setattr(lfx_service_deps, \\\"get_policy_bundle_service\\\", lambda: bundle_service)\\n    monkeypatch.setattr(lfx_service_deps, \\\"get_catalog_policy_service\\\", lambda: catalog_service)\\n    monkeypatch.setattr(lfx_service_deps, \\\"get_model_provider_policy_service\\\", lambda: provider_service)\\n\\n    assert policy_store.apply_policy_bundle_state(snapshot) is True\\n    assert catalog_service.applied == [snapshot]\\n    assert catalog_service.snapshot.blocked_component_keys == frozenset({\\\"PythonREPL\\\"})\\n    assert catalog_service.snapshot.blocked_template_keys == frozenset({\\\"Starter\\\"})\\n\\n    stale = PolicyBundleSnapshot(\\n        revision=3,\\n        initialized=True,\\n        source=\\\"poll\\\",\\n        approved_provider_ids={\\\"anthropic\\\"},\\n        blocked_component_keys={\\\"OpenAIModel\\\"},\\n        blocked_template_keys={\\\"OldStarter\\\"},\\n        content_hash=\\\"3\\\" * 64,\\n    )\\n    assert policy_store.apply_policy_bundle_state(stale) is True\\n    assert bundle_service.snapshot is snapshot\\n    assert catalog_service.applied == [snapshot, snapshot]\\n    assert catalog_service.snapshot.blocked_component_keys == frozenset({\\\"PythonREPL\\\"})\\n    assert catalog_service.snapshot.blocked_template_keys == frozenset({\\\"Starter\\\"})\\n    assert provider_service.approved_provider_ids == frozenset({\\\"openai\\\"})\\n    assert provider_service.policy_version == 4\\n\\n\\ndef test_runtime_rejects_database_owned_catalog_plugin_without_bundle_update_support(monkeypatch):\\n    class LegacyCatalogPolicy(BaseCatalogPolicyService):\\n        def __init__(self) -> None:\\n            super().__init__()\\n            self.set_ready()\\n\\n        @property\\n        def snapshot(self) -> CatalogPolicySnapshot:\\n            return CatalogPolicySnapshot()\\n\\n    bundle_service = PolicyBundleService()\\n    catalog_service = LegacyCatalogPolicy()\\n    provider_service = ModelProviderPolicyService(bundle_service)\\n    snapshot = PolicyBundleSnapshot(revision=2, initialized=True, content_hash=\\\"2\\\" * 64)\\n    monkeypatch.setattr(lfx_service_deps, \\\"get_policy_bundle_service\\\", lambda: bundle_service)\\n    monkeypatch.setattr(lfx_service_deps, \\\"get_catalog_policy_service\\\", lambda: catalog_service)\\n    monkeypatch.setattr(lfx_service_deps, \\\"get_model_provider_policy_service\\\", lambda: provider_service)\\n\\n    with pytest.raises(policy_store.PolicyBundleApplicationNotSupportedError, match=\\\"upgrade the plugin\\\"):\\n        policy_store.apply_policy_bundle_state(snapshot)\\n\\n    assert bundle_service.snapshot == PolicyBundleSnapshot()\\n    assert provider_service.policy_version == 0\\n\\n\\nasync def test_second_worker_poll_refreshes_all_facets_from_one_committed_revision(\\n    monkeypatch,\\n    bundle_session_maker,\\n):\\n    async with bundle_session_maker() as session:\\n        committed = await policy_store.replace_policy_bundle_state(\\n            session,\\n            expected_revision=1,\\n            approved_provider_ids={\\\"anthropic\\\"},\\n            blocked_component_keys={\\\"OpenAIModel\\\"},\\n            blocked_template_keys={\\\"starter-template\\\"},\\n            actor_user_id=uuid4(),\\n            reason=\\\"cross-worker\\\",\\n        )\\n\\n    second_bundle_service = PolicyBundleService()\\n    second_catalog_service = CatalogPolicyService(second_bundle_service)\\n    second_provider_service = ModelProviderPolicyService(second_bundle_service)\\n\\n    @asynccontextmanager\\n    async def session_scope():\\n        async with bundle_session_maker() as session:\\n            yield session\\n\\n    monkeypatch.setattr(refresh_module, \\\"session_scope\\\", session_scope)\\n    monkeypatch.setattr(\\n        refresh_module,\\n        \\\"get_model_provider_policy_service\\\",\\n        lambda: second_provider_service,\\n    )\\n    monkeypatch.setattr(\\n        refresh_module,\\n        \\\"get_policy_bundle_service\\\",\\n        lambda: second_bundle_service,\\n        raising=False,\\n    )\\n    monkeypatch.setattr(langflow_service_deps, \\\"get_policy_bundle_service\\\", lambda: second_bundle_service)\\n    monkeypatch.setattr(langflow_service_deps, \\\"get_catalog_policy_service\\\", lambda: second_catalog_service)\\n    monkeypatch.setattr(lfx_service_deps, \\\"get_policy_bundle_service\\\", lambda: second_bundle_service)\\n    monkeypatch.setattr(lfx_service_deps, \\\"get_catalog_policy_service\\\", lambda: second_catalog_service)\\n    monkeypatch.setattr(lfx_service_deps, \\\"get_model_provider_policy_service\\\", lambda: second_provider_service)\\n\\n    changed = await refresh_module.ModelProviderPolicyRefreshWorker()._run_once()\\n\\n    assert changed is True\\n    assert _bundle_value(second_bundle_service.snapshot) == _bundle_value(committed)\\n    assert second_catalog_service.policy_bundle_snapshot is second_bundle_service.snapshot\\n    assert second_provider_service.approved_provider_ids == committed.approved_provider_ids\\n    assert second_provider_service.policy_version == committed.revision\\n    assert second_catalog_service.snapshot.blocked_component_keys == committed.blocked_component_keys\\n    assert second_catalog_service.snapshot.blocked_template_keys == committed.blocked_template_keys\\n\\n\\nasync def test_replace_persists_and_canonicalizes_blocked_model_keys(bundle_session_maker):\\n    actor_id = uuid4()\\n    async with bundle_session_maker() as session:\\n        committed = await policy_store.replace_policy_bundle_state(\\n            session,\\n            expected_revision=1,\\n            approved_provider_ids=_INITIAL_PROVIDERS,\\n            blocked_component_keys=_INITIAL_COMPONENTS,\\n            blocked_template_keys=_INITIAL_TEMPLATES,\\n            blocked_model_keys={\\\"OpenAI::gpt-blocked\\\", \\\"openai::gpt-blocked\\\", \\\"bare-blocked\\\"},\\n            actor_user_id=actor_id,\\n            reason=\\\"block models\\\",\\n        )\\n\\n    assert committed.blocked_model_keys == frozenset({\\\"openai::gpt-blocked\\\", \\\"bare-blocked\\\"})\\n    assert committed.content_hash == policy_store.policy_bundle_content_hash(\\n        approved_provider_ids=_INITIAL_PROVIDERS,\\n        blocked_component_keys=_INITIAL_COMPONENTS,\\n        blocked_template_keys=_INITIAL_TEMPLATES,\\n        blocked_model_keys={\\\"openai::gpt-blocked\\\", \\\"bare-blocked\\\"},\\n    )\\n    durable = await _read_active(bundle_session_maker)\\n    assert durable.blocked_model_keys == committed.blocked_model_keys\\n    assert durable.content_hash == committed.content_hash\\n\\n\\nasync def test_replace_without_model_keys_keeps_legacy_content_hash_shape(bundle_session_maker):\\n    async with bundle_session_maker() as session:\\n        committed = await policy_store.replace_policy_bundle_state(\\n            session,\\n            expected_revision=1,\\n            approved_provider_ids=_INITIAL_PROVIDERS,\\n            blocked_component_keys=_INITIAL_COMPONENTS,\\n            blocked_template_keys=_INITIAL_TEMPLATES,\\n            actor_user_id=uuid4(),\\n        )\\n\\n    assert committed.blocked_model_keys == frozenset()\\n    assert committed.content_hash == policy_store.policy_bundle_content_hash(\\n        approved_provider_ids=_INITIAL_PROVIDERS,\\n        blocked_component_keys=_INITIAL_COMPONENTS,\\n        blocked_template_keys=_INITIAL_TEMPLATES,\\n    )\\n\\n\\nasync def test_malformed_blocked_model_key_rejected_before_any_write(bundle_session_maker):\\n    async with bundle_session_maker() as session:\\n        with pytest.raises(ValueError, match=\\\"Blocked-model key\\\"):\\n            await policy_store.replace_policy_bundle_state(\\n                session,\\n                expected_revision=1,\\n                approved_provider_ids=_INITIAL_PROVIDERS,\\n                blocked_component_keys=_INITIAL_COMPONENTS,\\n                blocked_template_keys=_INITIAL_TEMPLATES,\\n                blocked_model_keys={\\\"::claude-blocked\\\"},\\n                actor_user_id=uuid4(),\\n            )\\n\\n    active = await _read_active(bundle_session_maker)\\n    assert active.revision == 1\\n    assert active.blocked_model_keys == frozenset()\\n\\n\\nasync def test_rollback_restores_blocked_model_keys(bundle_session_maker):\\n    async with bundle_session_maker() as session:\\n        revision_two = await policy_store.replace_policy_bundle_state(\\n            session,\\n            expected_revision=1,\\n            approved_provider_ids=_INITIAL_PROVIDERS,\\n            blocked_component_keys=_INITIAL_COMPONENTS,\\n            blocked_template_keys=_INITIAL_TEMPLATES,\\n            blocked_model_keys={\\\"openai::gpt-blocked\\\"},\\n            actor_user_id=uuid4(),\\n            reason=\\\"block models\\\",\\n        )\\n    async with bundle_session_maker() as session:\\n        revision_three = await policy_store.replace_policy_bundle_state(\\n            session,\\n            expected_revision=revision_two.revision,\\n            approved_provider_ids=_INITIAL_PROVIDERS,\\n            blocked_component_keys=_INITIAL_COMPONENTS,\\n            blocked_template_keys=_INITIAL_TEMPLATES,\\n            actor_user_id=uuid4(),\\n            reason=\\\"unblock models\\\",\\n        )\\n    assert revision_three.blocked_model_keys == frozenset()\\n\\n    async with bundle_session_maker() as session:\\n        rolled_back = await policy_store.rollback_policy_bundle_state(\\n            session,\\n            expected_revision=revision_three.revision,\\n            target_revision=revision_two.revision,\\n            actor_user_id=uuid4(),\\n            reason=\\\"restore model blocks\\\",\\n        )\\n\\n    assert rolled_back.blocked_model_keys == frozenset({\\\"openai::gpt-blocked\\\"})\\n    assert rolled_back.rollback_of_revision == revision_two.revision\\n    assert rolled_back.content_hash == revision_two.content_hash\\n\\n\\nasync def test_legacy_provider_ceiling_write_preserves_blocked_model_keys(bundle_session_maker):\\n    from langflow.services import model_provider_policy as legacy_provider_store\\n\\n    async with bundle_session_maker() as session:\\n        await policy_store.replace_policy_bundle_state(\\n            session,\\n            expected_revision=1,\\n            approved_provider_ids=_INITIAL_PROVIDERS,\\n            blocked_component_keys=_INITIAL_COMPONENTS,\\n            blocked_template_keys=_INITIAL_TEMPLATES,\\n            blocked_model_keys={\\\"openai::gpt-blocked\\\"},\\n            actor_user_id=uuid4(),\\n        )\\n\\n    async with bundle_session_maker() as session:\\n        persisted = await legacy_provider_store.replace_model_provider_policy_state(\\n            session,\\n            {\\\"openai\\\", \\\"anthropic\\\"},\\n            actor_user_id=uuid4(),\\n        )\\n\\n    assert persisted.bundle_snapshot is not None\\n    assert persisted.bundle_snapshot.blocked_model_keys == frozenset({\\\"openai::gpt-blocked\\\"})\\n    assert persisted.approved_provider_ids == frozenset({\\\"openai\\\", \\\"anthropic\\\"})\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/test_storage_parse_file_path.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"06a81980daa552257e17545fcedbcdced670085e4a20303ed3577661ba804ae4\",\"content\":\"\\\"\\\"\\\"Tests for storage service parse_file_path method.\\\"\\\"\\\"\\n\\nfrom unittest.mock import Mock\\n\\nimport pytest\\nfrom langflow.services.storage.local import LocalStorageService\\nfrom langflow.services.storage.s3 import S3StorageService\\n\\n\\nclass TestLocalStorageParseFilePath:\\n    \\\"\\\"\\\"Test LocalStorageService.parse_file_path method.\\\"\\\"\\\"\\n\\n    def test_parse_with_data_dir(self):\\n        \\\"\\\"\\\"Test parsing path that includes data_dir.\\\"\\\"\\\"\\n        # Mock the services\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n\\n        service = LocalStorageService(mock_session, mock_settings)\\n\\n        # Test with full path including data_dir\\n        flow_id, file_name = service.parse_file_path(\\\"/data/user_123/image.png\\\")\\n        assert flow_id == \\\"user_123\\\"\\n        assert file_name == \\\"image.png\\\"\\n\\n    def test_parse_without_data_dir(self):\\n        \\\"\\\"\\\"Test parsing path without data_dir.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n\\n        service = LocalStorageService(mock_session, mock_settings)\\n\\n        # Test with relative path (no data_dir)\\n        flow_id, file_name = service.parse_file_path(\\\"user_123/image.png\\\")\\n        assert flow_id == \\\"user_123\\\"\\n        assert file_name == \\\"image.png\\\"\\n\\n    def test_parse_nested_flow_id(self):\\n        \\\"\\\"\\\"Test parsing path with nested flow_id.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n\\n        service = LocalStorageService(mock_session, mock_settings)\\n\\n        # Test with nested flow_id\\n        flow_id, file_name = service.parse_file_path(\\\"/data/bucket/user_123/image.png\\\")\\n        assert flow_id == \\\"bucket/user_123\\\"\\n        assert file_name == \\\"image.png\\\"\\n\\n    def test_parse_just_filename(self):\\n        \\\"\\\"\\\"Test parsing just a filename with no directory.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n\\n        service = LocalStorageService(mock_session, mock_settings)\\n\\n        # Test with just filename\\n        flow_id, file_name = service.parse_file_path(\\\"image.png\\\")\\n        assert flow_id == \\\"\\\"\\n        assert file_name == \\\"image.png\\\"\\n\\n\\nclass TestS3StorageParseFilePath:\\n    \\\"\\\"\\\"Test S3StorageService.parse_file_path method.\\\"\\\"\\\"\\n\\n    def test_parse_with_prefix(self):\\n        \\\"\\\"\\\"Test parsing path that includes S3 prefix.\\\"\\\"\\\"\\n        # Mock the services\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n        mock_settings.settings.object_storage_bucket_name = \\\"test-bucket\\\"\\n        mock_settings.settings.object_storage_prefix = \\\"files/\\\"\\n        mock_settings.settings.object_storage_tags = {}\\n\\n        service = S3StorageService(mock_session, mock_settings)\\n\\n        # Test with full path including prefix\\n        flow_id, file_name = service.parse_file_path(\\\"files/user_123/image.png\\\")\\n        assert flow_id == \\\"user_123\\\"\\n        assert file_name == \\\"image.png\\\"\\n\\n    def test_parse_without_prefix(self):\\n        \\\"\\\"\\\"Test parsing path without S3 prefix.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n        mock_settings.settings.object_storage_bucket_name = \\\"test-bucket\\\"\\n        mock_settings.settings.object_storage_prefix = \\\"files/\\\"\\n        mock_settings.settings.object_storage_tags = {}\\n\\n        service = S3StorageService(mock_session, mock_settings)\\n\\n        # Test with relative path (no prefix)\\n        flow_id, file_name = service.parse_file_path(\\\"user_123/image.png\\\")\\n        assert flow_id == \\\"user_123\\\"\\n        assert file_name == \\\"image.png\\\"\\n\\n    def test_parse_nested_flow_id(self):\\n        \\\"\\\"\\\"Test parsing path with nested flow_id.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n        mock_settings.settings.object_storage_bucket_name = \\\"test-bucket\\\"\\n        mock_settings.settings.object_storage_prefix = \\\"files-test-1/\\\"\\n        mock_settings.settings.object_storage_tags = {}\\n\\n        service = S3StorageService(mock_session, mock_settings)\\n\\n        # Test with nested flow_id (real-world example from logs)\\n        flow_id, file_name = service.parse_file_path(\\n            \\\"files-test-1/afffa27a-a9f0-4511-b1a9-7e6cb2b3df05/2025-12-07_14-47-29_langflow_pid_mem_usage.png\\\"\\n        )\\n        assert flow_id == \\\"afffa27a-a9f0-4511-b1a9-7e6cb2b3df05\\\"\\n        assert file_name == \\\"2025-12-07_14-47-29_langflow_pid_mem_usage.png\\\"\\n\\n    def test_parse_nested_flow_id_without_prefix(self):\\n        \\\"\\\"\\\"Test parsing nested flow_id without prefix.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n        mock_settings.settings.object_storage_bucket_name = \\\"test-bucket\\\"\\n        mock_settings.settings.object_storage_prefix = \\\"files-test-1/\\\"\\n        mock_settings.settings.object_storage_tags = {}\\n\\n        service = S3StorageService(mock_session, mock_settings)\\n\\n        # Test without prefix (as seen in error logs)\\n        flow_id, file_name = service.parse_file_path(\\n            \\\"afffa27a-a9f0-4511-b1a9-7e6cb2b3df05/2025-12-07_14-47-29_langflow_pid_mem_usage.png\\\"\\n        )\\n        assert flow_id == \\\"afffa27a-a9f0-4511-b1a9-7e6cb2b3df05\\\"\\n        assert file_name == \\\"2025-12-07_14-47-29_langflow_pid_mem_usage.png\\\"\\n\\n    def test_parse_just_filename(self):\\n        \\\"\\\"\\\"Test parsing just a filename with no directory.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n        mock_settings.settings.object_storage_bucket_name = \\\"test-bucket\\\"\\n        mock_settings.settings.object_storage_prefix = \\\"files/\\\"\\n        mock_settings.settings.object_storage_tags = {}\\n\\n        service = S3StorageService(mock_session, mock_settings)\\n\\n        # Test with just filename\\n        flow_id, file_name = service.parse_file_path(\\\"image.png\\\")\\n        assert flow_id == \\\"\\\"\\n        assert file_name == \\\"image.png\\\"\\n\\n    def test_parse_empty_prefix(self):\\n        \\\"\\\"\\\"Test parsing when prefix is empty.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n        mock_settings.settings.object_storage_bucket_name = \\\"test-bucket\\\"\\n        mock_settings.settings.object_storage_prefix = \\\"\\\"\\n        mock_settings.settings.object_storage_tags = {}\\n\\n        service = S3StorageService(mock_session, mock_settings)\\n\\n        # Test with no prefix configured\\n        flow_id, file_name = service.parse_file_path(\\\"user_123/image.png\\\")\\n        assert flow_id == \\\"user_123\\\"\\n        assert file_name == \\\"image.png\\\"\\n\\n\\nclass TestParseFilePathRoundTrip:\\n    \\\"\\\"\\\"Test that parse_file_path correctly reverses build_full_path.\\\"\\\"\\\"\\n\\n    def test_local_storage_round_trip(self):\\n        \\\"\\\"\\\"Test that parse reverses build for local storage.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n\\n        service = LocalStorageService(mock_session, mock_settings)\\n\\n        # Build a path\\n        full_path = service.build_full_path(\\\"user_123\\\", \\\"image.png\\\")\\n        assert full_path == \\\"/data/user_123/image.png\\\"\\n\\n        # Parse it back\\n        flow_id, file_name = service.parse_file_path(full_path)\\n        assert flow_id == \\\"user_123\\\"\\n        assert file_name == \\\"image.png\\\"\\n\\n    def test_s3_storage_round_trip(self):\\n        \\\"\\\"\\\"Test that parse reverses build for S3 storage.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n        mock_settings.settings.object_storage_bucket_name = \\\"test-bucket\\\"\\n        mock_settings.settings.object_storage_prefix = \\\"files/\\\"\\n        mock_settings.settings.object_storage_tags = {}\\n\\n        service = S3StorageService(mock_session, mock_settings)\\n\\n        # Build a path\\n        full_path = service.build_full_path(\\\"user_123\\\", \\\"image.png\\\")\\n        assert full_path == \\\"files/user_123/image.png\\\"\\n\\n        # Parse it back\\n        flow_id, file_name = service.parse_file_path(full_path)\\n        assert flow_id == \\\"user_123\\\"\\n        assert file_name == \\\"image.png\\\"\\n\\n    def test_s3_storage_round_trip_nested(self):\\n        \\\"\\\"\\\"Test round trip with nested flow_id.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n        mock_settings.settings.object_storage_bucket_name = \\\"test-bucket\\\"\\n        mock_settings.settings.object_storage_prefix = \\\"files-test-1/\\\"\\n        mock_settings.settings.object_storage_tags = {}\\n\\n        service = S3StorageService(mock_session, mock_settings)\\n\\n        # Build a path with nested flow_id\\n        full_path = service.build_full_path(\\n            \\\"afffa27a-a9f0-4511-b1a9-7e6cb2b3df05\\\", \\\"2025-12-07_14-47-29_langflow_pid_mem_usage.png\\\"\\n        )\\n        assert (\\n            full_path\\n            == \\\"files-test-1/afffa27a-a9f0-4511-b1a9-7e6cb2b3df05/2025-12-07_14-47-29_langflow_pid_mem_usage.png\\\"\\n        )\\n\\n        # Parse it back\\n        flow_id, file_name = service.parse_file_path(full_path)\\n        assert flow_id == \\\"afffa27a-a9f0-4511-b1a9-7e6cb2b3df05\\\"\\n        assert file_name == \\\"2025-12-07_14-47-29_langflow_pid_mem_usage.png\\\"\\n\\n\\nclass TestLocalStorageParseFilePathWindowsCompatibility:\\n    \\\"\\\"\\\"Test LocalStorageService.parse_file_path with Windows-style paths.\\n\\n    These tests ensure cross-platform compatibility when paths contain\\n    backslashes (Windows) instead of forward slashes (Unix).\\n    \\\"\\\"\\\"\\n\\n    @pytest.mark.skipif(\\n        not hasattr(__import__(\\\"os\\\"), \\\"name\\\") or __import__(\\\"os\\\").name != \\\"nt\\\",\\n        reason=\\\"Windows-specific path tests only run on Windows\\\",\\n    )\\n    def test_parse_windows_path_with_backslashes(self):\\n        \\\"\\\"\\\"Test parsing a Windows-style path with backslashes.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"C:\\\\\\\\data\\\"\\n\\n        service = LocalStorageService(mock_session, mock_settings)\\n\\n        flow_id, file_name = service.parse_file_path(\\\"C:\\\\\\\\data\\\\\\\\user_123\\\\\\\\image.png\\\")\\n        assert flow_id == \\\"user_123\\\"\\n        assert file_name == \\\"image.png\\\"\\n\\n    def test_parse_windows_relative_path(self):\\n        \\\"\\\"\\\"Test parsing a Windows relative path without data_dir.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"C:\\\\\\\\data\\\"\\n\\n        service = LocalStorageService(mock_session, mock_settings)\\n\\n        flow_id, file_name = service.parse_file_path(\\\"user_123\\\\\\\\image.png\\\")\\n        assert flow_id == \\\"user_123\\\"\\n        assert file_name == \\\"image.png\\\"\\n\\n    @pytest.mark.skipif(\\n        not hasattr(__import__(\\\"os\\\"), \\\"name\\\") or __import__(\\\"os\\\").name != \\\"nt\\\",\\n        reason=\\\"Windows-specific path tests only run on Windows\\\",\\n    )\\n    def test_parse_windows_nested_flow_id(self):\\n        \\\"\\\"\\\"Test parsing Windows path with nested flow_id.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"C:\\\\\\\\data\\\"\\n\\n        service = LocalStorageService(mock_session, mock_settings)\\n\\n        flow_id, file_name = service.parse_file_path(\\\"C:\\\\\\\\data\\\\\\\\bucket\\\\\\\\user_123\\\\\\\\image.png\\\")\\n        assert flow_id == \\\"bucket/user_123\\\"\\n        assert file_name == \\\"image.png\\\"\\n\\n    def test_parse_mixed_slashes(self):\\n        \\\"\\\"\\\"Test parsing path with mixed forward and backslashes.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n\\n        service = LocalStorageService(mock_session, mock_settings)\\n\\n        flow_id, file_name = service.parse_file_path(\\\"user_123\\\\\\\\subdir/image.png\\\")\\n        assert flow_id == \\\"user_123/subdir\\\"\\n        assert file_name == \\\"image.png\\\"\\n\\n    def test_parse_windows_just_filename(self):\\n        \\\"\\\"\\\"Test parsing just a filename on Windows.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"C:\\\\\\\\data\\\"\\n\\n        service = LocalStorageService(mock_session, mock_settings)\\n\\n        flow_id, file_name = service.parse_file_path(\\\"image.png\\\")\\n        assert flow_id == \\\"\\\"\\n        assert file_name == \\\"image.png\\\"\\n\\n    @pytest.mark.skipif(\\n        not hasattr(__import__(\\\"os\\\"), \\\"name\\\") or __import__(\\\"os\\\").name != \\\"nt\\\",\\n        reason=\\\"Windows-specific path tests only run on Windows\\\",\\n    )\\n    def test_parse_windows_uuid_flow_id(self):\\n        \\\"\\\"\\\"Test parsing Windows path with UUID flow_id (real-world scenario).\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"C:\\\\\\\\Users\\\\\\\\user\\\\\\\\AppData\\\\\\\\Local\\\\\\\\langflow\\\"\\n\\n        service = LocalStorageService(mock_session, mock_settings)\\n\\n        flow_id, file_name = service.parse_file_path(\\n            \\\"C:\\\\\\\\Users\\\\\\\\user\\\\\\\\AppData\\\\\\\\Local\\\\\\\\langflow\\\\\\\\afffa27a-a9f0-4511-b1a9-7e6cb2b3df05\\\\\\\\uploaded_file.png\\\"\\n        )\\n        assert flow_id == \\\"afffa27a-a9f0-4511-b1a9-7e6cb2b3df05\\\"\\n        assert file_name == \\\"uploaded_file.png\\\"\\n\\n    def test_backslash_normalization(self):\\n        \\\"\\\"\\\"Test that backslashes are normalized to forward slashes.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n\\n        service = LocalStorageService(mock_session, mock_settings)\\n\\n        # This should work on any platform - relative paths with backslashes\\n        flow_id, file_name = service.parse_file_path(\\\"flow_123\\\\\\\\subdir\\\\\\\\image.png\\\")\\n        assert \\\"/\\\" not in flow_id or \\\"\\\\\\\\\\\" not in flow_id  # Normalized\\n        assert file_name == \\\"image.png\\\"\\n\\n    def test_deeply_nested_backslash_path(self):\\n        \\\"\\\"\\\"Test parsing deeply nested path with backslashes.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n\\n        service = LocalStorageService(mock_session, mock_settings)\\n\\n        flow_id, file_name = service.parse_file_path(\\\"a\\\\\\\\b\\\\\\\\c\\\\\\\\d\\\\\\\\file.txt\\\")\\n        assert file_name == \\\"file.txt\\\"\\n        # Flow ID should have normalized slashes\\n        assert \\\"\\\\\\\\\\\" not in flow_id\\n\\n\\nclass TestLocalStorageParseFilePathEdgeCases:\\n    \\\"\\\"\\\"Test edge cases for LocalStorageService.parse_file_path.\\\"\\\"\\\"\\n\\n    def test_parse_empty_string(self):\\n        \\\"\\\"\\\"Test parsing an empty string.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n\\n        service = LocalStorageService(mock_session, mock_settings)\\n\\n        flow_id, file_name = service.parse_file_path(\\\"\\\")\\n        assert flow_id == \\\"\\\"\\n        assert file_name == \\\".\\\"\\n\\n    def test_parse_path_with_spaces(self):\\n        \\\"\\\"\\\"Test parsing path with spaces in names.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n\\n        service = LocalStorageService(mock_session, mock_settings)\\n\\n        flow_id, file_name = service.parse_file_path(\\\"/data/flow with spaces/my file.png\\\")\\n        assert flow_id == \\\"flow with spaces\\\"\\n        assert file_name == \\\"my file.png\\\"\\n\\n    def test_parse_path_with_special_characters(self):\\n        \\\"\\\"\\\"Test parsing path with special characters.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n\\n        service = LocalStorageService(mock_session, mock_settings)\\n\\n        flow_id, file_name = service.parse_file_path(\\\"/data/flow_123-test/image_2024-01-01.png\\\")\\n        assert flow_id == \\\"flow_123-test\\\"\\n        assert file_name == \\\"image_2024-01-01.png\\\"\\n\\n    def test_parse_deeply_nested_path(self):\\n        \\\"\\\"\\\"Test parsing deeply nested path.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n\\n        service = LocalStorageService(mock_session, mock_settings)\\n\\n        flow_id, file_name = service.parse_file_path(\\\"/data/level1/level2/level3/file.txt\\\")\\n        assert flow_id == \\\"level1/level2/level3\\\"\\n        assert file_name == \\\"file.txt\\\"\\n\\n    @pytest.mark.parametrize(\\n        (\\\"input_path\\\", \\\"expected_flow_id\\\", \\\"expected_file_name\\\"),\\n        [\\n            (\\\"user_123/image.png\\\", \\\"user_123\\\", \\\"image.png\\\"),\\n            (\\\"image.png\\\", \\\"\\\", \\\"image.png\\\"),\\n            (\\\"a/b/c/d.txt\\\", \\\"a/b/c\\\", \\\"d.txt\\\"),\\n            (\\\"flow-id/file-name.ext\\\", \\\"flow-id\\\", \\\"file-name.ext\\\"),\\n        ],\\n    )\\n    def test_parse_various_relative_paths(self, input_path, expected_flow_id, expected_file_name):\\n        \\\"\\\"\\\"Test parsing various relative path formats.\\\"\\\"\\\"\\n        mock_session = Mock()\\n        mock_settings = Mock()\\n        mock_settings.settings.config_dir = \\\"/data\\\"\\n\\n        service = LocalStorageService(mock_session, mock_settings)\\n\\n        flow_id, file_name = service.parse_file_path(input_path)\\n        assert flow_id == expected_flow_id\\n        assert file_name == expected_file_name\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/tracing/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8e99beb2a11ed93c2531d3d44c69822e590a16655dbca0b01f164e02e99e9dcb\",\"content\":\"\\\"\\\"\\\"Services tests package.\\\"\\\"\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/tracing/test_arize_phoenix.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0d99c4db4c16e85a59ec4a1ce2594ba33b92058ddadc636827c6f0333ab4cfb7\",\"content\":\"import pytest\\nfrom langflow.services.tracing.arize_phoenix import ArizePhoenixTracer\\nfrom lfx.schema.data import Data\\n\\n\\n@pytest.fixture\\ndef tracer():\\n    return ArizePhoenixTracer.__new__(ArizePhoenixTracer)\\n\\n\\ndef test_data_dict_conversion(tracer):\\n    value = Data(data={\\\"a\\\": 1, \\\"b\\\": \\\"x\\\"})\\n\\n    result = tracer._convert_to_arize_phoenix_type(value)\\n\\n    assert result == {\\\"a\\\": 1, \\\"b\\\": \\\"x\\\"}\\n\\n\\ndef test_data_list_conversion(tracer):\\n    value = Data.model_construct(data=[1, Data(data={\\\"x\\\": 2})], text_key=\\\"text\\\", default_value=\\\"\\\")\\n\\n    result = tracer._convert_to_arize_phoenix_type(value)\\n\\n    assert result == [1, {\\\"x\\\": 2}]\\n\\n\\ndef test_data_text_payload_preserved(tracer):\\n    value = Data(data={\\\"text\\\": \\\"hello\\\"})\\n\\n    result = tracer._convert_to_arize_phoenix_type(value)\\n\\n    assert result == {\\\"text\\\": \\\"hello\\\"}\\n\\n\\ndef test_data_nested_structure(tracer):\\n    value = Data(data={\\\"nested\\\": [1, Data(data={\\\"x\\\": float(\\\"inf\\\")})]})\\n\\n    result = tracer._convert_to_arize_phoenix_type(value)\\n\\n    assert result == {\\\"nested\\\": [1, {\\\"x\\\": \\\"NaN\\\"}]}\\n\\n\\ndef test_data_none(tracer):\\n    value = Data(data=None)\\n\\n    result = tracer._convert_to_arize_phoenix_type(value)\\n\\n    assert result == {}\\n\\n\\ndef test_dict_recursive_conversion(tracer):\\n    value = {\\n        \\\"a\\\": Data(data={\\\"b\\\": 1}),\\n        \\\"c\\\": [Data(data={\\\"text\\\": \\\"text\\\"}), 2],\\n    }\\n\\n    result = tracer._convert_to_arize_phoenix_type(value)\\n\\n    assert result == {\\n        \\\"a\\\": {\\\"b\\\": 1},\\n        \\\"c\\\": [{\\\"text\\\": \\\"text\\\"}, 2],\\n    }\\n\\n\\ndef test_list_recursive_conversion(tracer):\\n    value = [\\n        Data(data={\\\"x\\\": 1}),\\n        Data(data={\\\"text\\\": \\\"y\\\"}),\\n    ]\\n\\n    result = tracer._convert_to_arize_phoenix_type(value)\\n\\n    assert result == [{\\\"x\\\": 1}, {\\\"text\\\": \\\"y\\\"}]\\n\\n\\ndef test_float_nan_conversion(tracer):\\n    value = float(\\\"nan\\\")\\n\\n    result = tracer._convert_to_arize_phoenix_type(value)\\n\\n    assert result == \\\"NaN\\\"\\n\\n\\ndef test_float_inf_conversion(tracer):\\n    value = float(\\\"inf\\\")\\n\\n    result = tracer._convert_to_arize_phoenix_type(value)\\n\\n    assert result == \\\"NaN\\\"\\n\\n\\ndef test_none_type_conversion(tracer):\\n    value = None\\n\\n    result = tracer._convert_to_arize_phoenix_type(value)\\n\\n    assert result == \\\"None\\\"\\n\\n\\ndef test_generator_conversion(tracer):\\n    def gen():\\n        yield 1\\n\\n    value = gen()\\n\\n    result = tracer._convert_to_arize_phoenix_type(value)\\n\\n    assert isinstance(result, str)\\n\\n\\ndef test_plain_dict_unchanged(tracer):\\n    value = {\\\"a\\\": 1, \\\"b\\\": 2}\\n\\n    result = tracer._convert_to_arize_phoenix_type(value)\\n\\n    assert result == value\\n\\n\\ndef test_plain_list_unchanged(tracer):\\n    value = [1, 2, 3]\\n\\n    result = tracer._convert_to_arize_phoenix_type(value)\\n\\n    assert result == value\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/tracing/test_formatting.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"011524f84c7abc17007e0d2fd73da3319f65d7032ba978894bcd426cf07a62df\",\"content\":\"\\\"\\\"\\\"Unit tests for langflow.services.tracing.formatting.\\n\\nCovers:\\n- safe_int_tokens: happy path, edge cases, adversarial inputs\\n- build_span_tree: ordering, hierarchy, empty input, orphan spans\\n- extract_trace_io_from_spans: Chat Input detection, root-span output selection\\n- extract_trace_io_from_rows: same heuristics via lightweight row tuples\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom datetime import datetime, timezone\\nfrom uuid import uuid4\\n\\nfrom langflow.services.database.models.traces.model import SpanStatus, SpanTable, SpanType\\nfrom langflow.services.tracing.formatting import (\\n    _CHAT_INPUT_SPAN_NAME,\\n    build_span_tree,\\n    extract_trace_io_from_rows,\\n    extract_trace_io_from_spans,\\n    safe_int_tokens,\\n)\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\n\\n_TRACE_ID = uuid4()\\n_UTC = timezone.utc\\n\\n\\ndef _dt(hour: int, minute: int = 0) -> datetime:\\n    \\\"\\\"\\\"Return a UTC datetime for a fixed date at the given hour:minute.\\\"\\\"\\\"\\n    return datetime(2024, 1, 1, hour, minute, tzinfo=_UTC)\\n\\n\\ndef _span(\\n    *,\\n    name: str = \\\"span\\\",\\n    parent_span_id=None,\\n    start_time: datetime | None = None,\\n    end_time: datetime | None = None,\\n    inputs: dict | None = None,\\n    outputs: dict | None = None,\\n    attributes: dict | None = None,\\n    span_type: SpanType = SpanType.CHAIN,\\n    status: SpanStatus = SpanStatus.OK,\\n) -> SpanTable:\\n    \\\"\\\"\\\"Build a minimal SpanTable without a database session.\\\"\\\"\\\"\\n    return SpanTable(\\n        id=uuid4(),\\n        trace_id=_TRACE_ID,\\n        name=name,\\n        parent_span_id=parent_span_id,\\n        start_time=start_time or _dt(0),\\n        end_time=end_time,\\n        inputs=inputs,\\n        outputs=outputs,\\n        attributes=attributes or {},\\n        span_type=span_type,\\n        status=status,\\n        latency_ms=0,\\n    )\\n\\n\\ndef _row(\\n    *,\\n    name: str = \\\"span\\\",\\n    parent_span_id=None,\\n    end_time: datetime | None = None,\\n    inputs: dict | None = None,\\n    outputs: dict | None = None,\\n):\\n    \\\"\\\"\\\"Build a lightweight row tuple matching the layout expected by extract_trace_io_from_rows.\\n\\n    Layout: (trace_id, name, parent_span_id, end_time, inputs, outputs)\\n    \\\"\\\"\\\"\\n    return (_TRACE_ID, name, parent_span_id, end_time, inputs, outputs)\\n\\n\\n# ---------------------------------------------------------------------------\\n# safe_int_tokens\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestSafeIntTokens:\\n    # --- Happy path ---\\n\\n    def test_should_return_int_unchanged_when_given_plain_int(self):\\n        assert safe_int_tokens(42) == 42\\n\\n    def test_should_return_zero_when_given_zero_int(self):\\n        assert safe_int_tokens(0) == 0\\n\\n    def test_should_truncate_float_to_int(self):\\n        assert safe_int_tokens(12.9) == 12\\n\\n    def test_should_parse_decimal_string(self):\\n        assert safe_int_tokens(\\\"100\\\") == 100\\n\\n    def test_should_parse_float_string(self):\\n        assert safe_int_tokens(\\\"12.0\\\") == 12\\n\\n    def test_should_parse_scientific_notation_string(self):\\n        assert safe_int_tokens(\\\"1e3\\\") == 1000\\n\\n    # --- Edge cases ---\\n\\n    def test_should_return_zero_for_none(self):\\n        assert safe_int_tokens(None) == 0\\n\\n    def test_should_return_zero_for_empty_string(self):\\n        assert safe_int_tokens(\\\"\\\") == 0\\n\\n    def test_should_return_zero_for_nan_string(self):\\n        assert safe_int_tokens(\\\"NaN\\\") == 0\\n\\n    def test_should_return_zero_for_inf_string(self):\\n        # float(\\\"inf\\\") is valid Python but not a meaningful token count.\\n        # int(float(\\\"inf\\\")) raises OverflowError; we expect 0.\\n        assert safe_int_tokens(\\\"inf\\\") == 0\\n\\n    def test_should_return_zero_for_negative_inf_string(self):\\n        assert safe_int_tokens(\\\"-inf\\\") == 0\\n\\n    def test_should_return_zero_for_nan_float(self):\\n        assert safe_int_tokens(float(\\\"nan\\\")) == 0\\n\\n    def test_should_return_zero_for_arbitrary_string(self):\\n        assert safe_int_tokens(\\\"not-a-number\\\") == 0\\n\\n    def test_should_return_zero_for_list(self):\\n        assert safe_int_tokens([1, 2, 3]) == 0\\n\\n    def test_should_return_zero_for_dict(self):\\n        assert safe_int_tokens({\\\"tokens\\\": 5}) == 0\\n\\n    def test_should_return_zero_for_bool_true(self):\\n        value = True\\n        assert safe_int_tokens(value) == 0\\n\\n    def test_should_return_zero_for_bool_false(self):\\n        value = False\\n        assert safe_int_tokens(value) == 0\\n\\n    def test_should_handle_large_integer(self):\\n        assert safe_int_tokens(10**9) == 10**9\\n\\n    def test_should_handle_negative_int(self):\\n        # Negative values are technically parseable; we return them as-is.\\n        assert safe_int_tokens(-5) == -5\\n\\n    def test_should_parse_float_string_with_trailing_zeros(self):\\n        assert safe_int_tokens(\\\"100.00\\\") == 100\\n\\n\\n# ---------------------------------------------------------------------------\\n# build_span_tree\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestBuildSpanTree:\\n    # --- Happy path ---\\n\\n    def test_should_return_empty_list_for_no_spans(self):\\n        assert build_span_tree([]) == []\\n\\n    def test_should_return_single_root_span(self):\\n        span = _span(name=\\\"root\\\")\\n        result = build_span_tree([span])\\n        assert len(result) == 1\\n        assert result[0].name == \\\"root\\\"\\n        assert result[0].children == []\\n\\n    def test_should_nest_child_under_parent(self):\\n        parent = _span(name=\\\"parent\\\", start_time=_dt(1))\\n        child = _span(name=\\\"child\\\", parent_span_id=parent.id, start_time=_dt(2))\\n        result = build_span_tree([parent, child])\\n        assert len(result) == 1\\n        assert result[0].name == \\\"parent\\\"\\n        assert len(result[0].children) == 1\\n        assert result[0].children[0].name == \\\"child\\\"\\n\\n    def test_should_build_three_level_hierarchy(self):\\n        root = _span(name=\\\"root\\\", start_time=_dt(1))\\n        mid = _span(name=\\\"mid\\\", parent_span_id=root.id, start_time=_dt(2))\\n        leaf = _span(name=\\\"leaf\\\", parent_span_id=mid.id, start_time=_dt(3))\\n        result = build_span_tree([root, mid, leaf])\\n        assert result[0].children[0].children[0].name == \\\"leaf\\\"\\n\\n    def test_should_return_multiple_root_spans(self):\\n        a = _span(name=\\\"a\\\", start_time=_dt(1))\\n        b = _span(name=\\\"b\\\", start_time=_dt(2))\\n        result = build_span_tree([a, b])\\n        assert len(result) == 2\\n\\n    # --- Ordering ---\\n\\n    def test_should_sort_roots_by_start_time_ascending(self):\\n        late = _span(name=\\\"late\\\", start_time=_dt(10))\\n        early = _span(name=\\\"early\\\", start_time=_dt(1))\\n        result = build_span_tree([late, early])\\n        assert result[0].name == \\\"early\\\"\\n        assert result[1].name == \\\"late\\\"\\n\\n    def test_should_sort_children_by_start_time_ascending(self):\\n        parent = _span(name=\\\"parent\\\", start_time=_dt(0))\\n        c2 = _span(name=\\\"c2\\\", parent_span_id=parent.id, start_time=_dt(5))\\n        c1 = _span(name=\\\"c1\\\", parent_span_id=parent.id, start_time=_dt(2))\\n        result = build_span_tree([parent, c2, c1])\\n        children = result[0].children\\n        assert children[0].name == \\\"c1\\\"\\n        assert children[1].name == \\\"c2\\\"\\n\\n    def test_should_produce_same_tree_regardless_of_input_order(self):\\n        root = _span(name=\\\"root\\\", start_time=_dt(1))\\n        child = _span(name=\\\"child\\\", parent_span_id=root.id, start_time=_dt(2))\\n\\n        result_forward = build_span_tree([root, child])\\n        result_reversed = build_span_tree([child, root])\\n\\n        assert result_forward[0].name == result_reversed[0].name\\n        assert result_forward[0].children[0].name == result_reversed[0].children[0].name\\n\\n    # --- Adversarial ---\\n\\n    def test_should_treat_orphan_span_as_root(self):\\n        \\\"\\\"\\\"A span whose parent_span_id references a non-existent span becomes a root.\\\"\\\"\\\"\\n        orphan = _span(name=\\\"orphan\\\", parent_span_id=uuid4())\\n        result = build_span_tree([orphan])\\n        assert len(result) == 1\\n        assert result[0].name == \\\"orphan\\\"\\n\\n    def test_should_not_share_children_list_between_spans(self):\\n        \\\"\\\"\\\"Each SpanReadResponse must have its own children list (default_factory).\\\"\\\"\\\"\\n        a = _span(name=\\\"a\\\", start_time=_dt(1))\\n        b = _span(name=\\\"b\\\", start_time=_dt(2))\\n        result = build_span_tree([a, b])\\n        result[0].children.append(result[1])\\n        # Mutating one span's children must not affect the other.\\n        assert result[1].children == []\\n\\n\\n# ---------------------------------------------------------------------------\\n# extract_trace_io_from_spans\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestExtractTraceIoFromSpans:\\n    # --- Happy path ---\\n\\n    def test_should_return_none_input_and_output_for_empty_spans(self):\\n        result = extract_trace_io_from_spans([])\\n        assert result == {\\\"input\\\": None, \\\"output\\\": None}\\n\\n    def test_should_extract_input_from_chat_input_span(self):\\n        span = _span(\\n            name=_CHAT_INPUT_SPAN_NAME,\\n            inputs={\\\"input_value\\\": \\\"hello\\\"},\\n            end_time=_dt(1),\\n        )\\n        result = extract_trace_io_from_spans([span])\\n        assert result[\\\"input\\\"] == {\\\"input_value\\\": \\\"hello\\\"}\\n\\n    def test_should_extract_output_from_last_finished_root_span(self):\\n        early = _span(name=\\\"root_early\\\", end_time=_dt(1), outputs={\\\"result\\\": \\\"first\\\"})\\n        late = _span(name=\\\"root_late\\\", end_time=_dt(5), outputs={\\\"result\\\": \\\"last\\\"})\\n        result = extract_trace_io_from_spans([early, late])\\n        assert result[\\\"output\\\"] == {\\\"result\\\": \\\"last\\\"}\\n\\n    def test_should_ignore_unfinished_root_spans_for_output(self):\\n        finished = _span(name=\\\"done\\\", end_time=_dt(3), outputs={\\\"result\\\": \\\"ok\\\"})\\n        unfinished = _span(name=\\\"pending\\\", end_time=None, outputs={\\\"result\\\": \\\"nope\\\"})\\n        result = extract_trace_io_from_spans([finished, unfinished])\\n        assert result[\\\"output\\\"] == {\\\"result\\\": \\\"ok\\\"}\\n\\n    def test_should_ignore_child_spans_for_output(self):\\n        parent = _span(name=\\\"parent\\\", end_time=_dt(2), outputs={\\\"result\\\": \\\"parent_out\\\"})\\n        child = _span(\\n            name=\\\"child\\\",\\n            parent_span_id=parent.id,\\n            end_time=_dt(3),\\n            outputs={\\\"result\\\": \\\"child_out\\\"},\\n        )\\n        result = extract_trace_io_from_spans([parent, child])\\n        assert result[\\\"output\\\"] == {\\\"result\\\": \\\"parent_out\\\"}\\n\\n    # --- Edge cases ---\\n\\n    def test_should_return_none_input_when_no_chat_input_span(self):\\n        span = _span(name=\\\"SomeOtherSpan\\\", inputs={\\\"input_value\\\": \\\"ignored\\\"}, end_time=_dt(1))\\n        result = extract_trace_io_from_spans([span])\\n        assert result[\\\"input\\\"] is None\\n\\n    def test_should_return_none_input_when_chat_input_span_has_no_inputs(self):\\n        span = _span(name=_CHAT_INPUT_SPAN_NAME, inputs=None, end_time=_dt(1))\\n        result = extract_trace_io_from_spans([span])\\n        assert result[\\\"input\\\"] is None\\n\\n    def test_should_return_none_input_when_input_value_key_missing(self):\\n        span = _span(name=_CHAT_INPUT_SPAN_NAME, inputs={\\\"other_key\\\": \\\"value\\\"}, end_time=_dt(1))\\n        result = extract_trace_io_from_spans([span])\\n        assert result[\\\"input\\\"] is None\\n\\n    def test_should_return_none_output_when_root_span_has_no_outputs(self):\\n        span = _span(name=\\\"root\\\", end_time=_dt(1), outputs=None)\\n        result = extract_trace_io_from_spans([span])\\n        assert result[\\\"output\\\"] is None\\n\\n    def test_should_return_none_output_when_no_finished_root_spans(self):\\n        span = _span(name=\\\"root\\\", end_time=None, outputs={\\\"result\\\": \\\"nope\\\"})\\n        result = extract_trace_io_from_spans([span])\\n        assert result[\\\"output\\\"] is None\\n\\n    def test_should_match_chat_input_span_by_substring(self):\\n        \\\"\\\"\\\"Span name only needs to *contain* the constant, not equal it.\\\"\\\"\\\"\\n        span = _span(\\n            name=f\\\"Langflow {_CHAT_INPUT_SPAN_NAME} Component\\\",\\n            inputs={\\\"input_value\\\": \\\"hi\\\"},\\n            end_time=_dt(1),\\n        )\\n        result = extract_trace_io_from_spans([span])\\n        assert result[\\\"input\\\"] == {\\\"input_value\\\": \\\"hi\\\"}\\n\\n\\n# ---------------------------------------------------------------------------\\n# extract_trace_io_from_rows\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestExtractTraceIoFromRows:\\n    # --- Happy path ---\\n\\n    def test_should_return_none_input_and_output_for_empty_rows(self):\\n        result = extract_trace_io_from_rows([])\\n        assert result == {\\\"input\\\": None, \\\"output\\\": None}\\n\\n    def test_should_extract_input_from_chat_input_row(self):\\n        row = _row(name=_CHAT_INPUT_SPAN_NAME, inputs={\\\"input_value\\\": \\\"hello\\\"}, end_time=_dt(1))\\n        result = extract_trace_io_from_rows([row])\\n        assert result[\\\"input\\\"] == {\\\"input_value\\\": \\\"hello\\\"}\\n\\n    def test_should_extract_output_from_last_finished_root_row(self):\\n        early = _row(name=\\\"root_early\\\", end_time=_dt(1), outputs={\\\"result\\\": \\\"first\\\"})\\n        late = _row(name=\\\"root_late\\\", end_time=_dt(5), outputs={\\\"result\\\": \\\"last\\\"})\\n        result = extract_trace_io_from_rows([early, late])\\n        assert result[\\\"output\\\"] == {\\\"result\\\": \\\"last\\\"}\\n\\n    def test_should_ignore_unfinished_root_rows_for_output(self):\\n        finished = _row(name=\\\"done\\\", end_time=_dt(3), outputs={\\\"result\\\": \\\"ok\\\"})\\n        unfinished = _row(name=\\\"pending\\\", end_time=None, outputs={\\\"result\\\": \\\"nope\\\"})\\n        result = extract_trace_io_from_rows([finished, unfinished])\\n        assert result[\\\"output\\\"] == {\\\"result\\\": \\\"ok\\\"}\\n\\n    def test_should_ignore_child_rows_for_output(self):\\n        parent_id = uuid4()\\n        parent = _row(name=\\\"parent\\\", end_time=_dt(2), outputs={\\\"result\\\": \\\"parent_out\\\"})\\n        child = _row(name=\\\"child\\\", parent_span_id=parent_id, end_time=_dt(3), outputs={\\\"result\\\": \\\"child_out\\\"})\\n        result = extract_trace_io_from_rows([parent, child])\\n        assert result[\\\"output\\\"] == {\\\"result\\\": \\\"parent_out\\\"}\\n\\n    # --- Edge cases ---\\n\\n    def test_should_return_none_input_when_no_chat_input_row(self):\\n        row = _row(name=\\\"SomeOtherSpan\\\", inputs={\\\"input_value\\\": \\\"ignored\\\"}, end_time=_dt(1))\\n        result = extract_trace_io_from_rows([row])\\n        assert result[\\\"input\\\"] is None\\n\\n    def test_should_return_none_input_when_chat_input_row_has_no_inputs(self):\\n        row = _row(name=_CHAT_INPUT_SPAN_NAME, inputs=None, end_time=_dt(1))\\n        result = extract_trace_io_from_rows([row])\\n        assert result[\\\"input\\\"] is None\\n\\n    def test_should_return_none_input_when_input_value_key_missing(self):\\n        row = _row(name=_CHAT_INPUT_SPAN_NAME, inputs={\\\"other_key\\\": \\\"value\\\"}, end_time=_dt(1))\\n        result = extract_trace_io_from_rows([row])\\n        assert result[\\\"input\\\"] is None\\n\\n    def test_should_return_none_output_when_root_row_has_no_outputs(self):\\n        row = _row(name=\\\"root\\\", end_time=_dt(1), outputs=None)\\n        result = extract_trace_io_from_rows([row])\\n        assert result[\\\"output\\\"] is None\\n\\n    def test_should_return_none_output_when_no_finished_root_rows(self):\\n        row = _row(name=\\\"root\\\", end_time=None, outputs={\\\"result\\\": \\\"nope\\\"})\\n        result = extract_trace_io_from_rows([row])\\n        assert result[\\\"output\\\"] is None\\n\\n    def test_should_match_chat_input_row_by_substring(self):\\n        row = _row(\\n            name=f\\\"Langflow {_CHAT_INPUT_SPAN_NAME} Component\\\",\\n            inputs={\\\"input_value\\\": \\\"hi\\\"},\\n            end_time=_dt(1),\\n        )\\n        result = extract_trace_io_from_rows([row])\\n        assert result[\\\"input\\\"] == {\\\"input_value\\\": \\\"hi\\\"}\\n\\n    def test_should_produce_same_result_as_span_variant_for_equivalent_data(self):\\n        \\\"\\\"\\\"extract_trace_io_from_rows and extract_trace_io_from_spans must agree.\\\"\\\"\\\"\\n        span = _span(\\n            name=_CHAT_INPUT_SPAN_NAME,\\n            inputs={\\\"input_value\\\": \\\"test\\\"},\\n            end_time=_dt(2),\\n            outputs={\\\"result\\\": \\\"out\\\"},\\n        )\\n        row = _row(\\n            name=_CHAT_INPUT_SPAN_NAME,\\n            inputs={\\\"input_value\\\": \\\"test\\\"},\\n            end_time=_dt(2),\\n            outputs={\\\"result\\\": \\\"out\\\"},\\n        )\\n        span_result = extract_trace_io_from_spans([span])\\n        row_result = extract_trace_io_from_rows([row])\\n        assert span_result == row_result\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/tracing/test_http_context_propagation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b03d7fbae76a7f933437899149f2c38457d4754837f1028fc5d5cd6f20524059\",\"content\":\"\\\"\\\"\\\"Tests for HTTP client trace context propagation in Arize Phoenix and LangWatch tracers.\\\"\\\"\\\"\\n\\nimport os\\nimport re\\nimport uuid\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\nfrom opentelemetry.sdk.trace import TracerProvider\\nfrom opentelemetry.sdk.trace.export import SimpleSpanProcessor\\nfrom opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\n\\n\\nclass TestHTTPClientInstrumentationManager:\\n    \\\"\\\"\\\"Test the shared HTTP client instrumentation manager.\\\"\\\"\\\"\\n\\n    @pytest.fixture(autouse=True)\\n    def reset_manager(self):\\n        \\\"\\\"\\\"Reset the singleton manager between tests.\\\"\\\"\\\"\\n        from langflow.services.tracing.http_instrumentation import HTTPClientInstrumentationManager\\n\\n        HTTPClientInstrumentationManager._instance = None\\n        yield\\n        HTTPClientInstrumentationManager._instance = None\\n\\n    def test_reference_counting_instrument_once(self):\\n        \\\"\\\"\\\"Verify instrumentation only happens on first enable.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"opentelemetry.instrumentation.requests.RequestsInstrumentor\\\") as mock_requests,\\n            patch(\\\"opentelemetry.instrumentation.urllib3.URLLib3Instrumentor\\\") as mock_urllib3,\\n        ):\\n            mock_requests.return_value.instrument = MagicMock()\\n            mock_urllib3.return_value.instrument = MagicMock()\\n\\n            from langflow.services.tracing.http_instrumentation import get_http_instrumentation_manager\\n\\n            manager = get_http_instrumentation_manager()\\n\\n            manager.enable()\\n            manager.enable()\\n            manager.enable()\\n\\n            mock_requests.return_value.instrument.assert_called_once()\\n            mock_urllib3.return_value.instrument.assert_called_once()\\n\\n    def test_reference_counting_uninstrument_at_zero(self):\\n        \\\"\\\"\\\"Verify uninstrumentation only happens when ref count reaches zero.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"opentelemetry.instrumentation.requests.RequestsInstrumentor\\\") as mock_requests,\\n            patch(\\\"opentelemetry.instrumentation.urllib3.URLLib3Instrumentor\\\") as mock_urllib3,\\n        ):\\n            mock_requests.return_value.instrument = MagicMock()\\n            mock_requests.return_value.uninstrument = MagicMock()\\n            mock_urllib3.return_value.instrument = MagicMock()\\n            mock_urllib3.return_value.uninstrument = MagicMock()\\n\\n            from langflow.services.tracing.http_instrumentation import get_http_instrumentation_manager\\n\\n            manager = get_http_instrumentation_manager()\\n\\n            manager.enable()\\n            manager.enable()\\n            manager.enable()\\n\\n            manager.disable()\\n            mock_requests.return_value.uninstrument.assert_not_called()\\n            mock_urllib3.return_value.uninstrument.assert_not_called()\\n\\n            manager.disable()\\n            mock_requests.return_value.uninstrument.assert_not_called()\\n            mock_urllib3.return_value.uninstrument.assert_not_called()\\n\\n            manager.disable()\\n            mock_requests.return_value.uninstrument.assert_called_once()\\n            mock_urllib3.return_value.uninstrument.assert_called_once()\\n\\n    def test_concurrent_tracers_dont_interfere(self):\\n        \\\"\\\"\\\"Verify that multiple tracers can coexist without interfering.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"opentelemetry.instrumentation.requests.RequestsInstrumentor\\\") as mock_requests,\\n            patch(\\\"opentelemetry.instrumentation.urllib3.URLLib3Instrumentor\\\") as mock_urllib3,\\n        ):\\n            mock_requests.return_value.instrument = MagicMock()\\n            mock_requests.return_value.uninstrument = MagicMock()\\n            mock_urllib3.return_value.instrument = MagicMock()\\n            mock_urllib3.return_value.uninstrument = MagicMock()\\n\\n            from langflow.services.tracing.http_instrumentation import get_http_instrumentation_manager\\n\\n            manager = get_http_instrumentation_manager()\\n\\n            manager.enable()\\n            manager.enable()\\n\\n            manager.disable()\\n\\n            mock_requests.return_value.uninstrument.assert_not_called()\\n            mock_urllib3.return_value.uninstrument.assert_not_called()\\n\\n            manager.disable()\\n\\n            mock_requests.return_value.uninstrument.assert_called_once()\\n\\n    def test_error_logging_on_uninstrument_failure(self):\\n        \\\"\\\"\\\"Verify unexpected errors during uninstrument are logged, not silently suppressed.\\\"\\\"\\\"\\n        with (\\n            patch(\\\"opentelemetry.instrumentation.requests.RequestsInstrumentor\\\") as mock_requests,\\n            patch(\\\"opentelemetry.instrumentation.urllib3.URLLib3Instrumentor\\\") as mock_urllib3,\\n            patch(\\\"langflow.services.tracing.http_instrumentation.logger\\\") as mock_logger,\\n        ):\\n            mock_requests.return_value.instrument = MagicMock()\\n            mock_requests.return_value.uninstrument = MagicMock(side_effect=RuntimeError(\\\"test error\\\"))\\n            mock_urllib3.return_value.instrument = MagicMock()\\n            mock_urllib3.return_value.uninstrument = MagicMock()\\n\\n            from langflow.services.tracing.http_instrumentation import get_http_instrumentation_manager\\n\\n            manager = get_http_instrumentation_manager()\\n\\n            manager.enable()\\n            manager.disable()\\n\\n            mock_logger.warning.assert_called()\\n            call_args = str(mock_logger.warning.call_args)\\n            assert \\\"Unexpected error uninstrumenting\\\" in call_args\\n\\n\\nclass TestArizePhoenixHttpInstrumentation:\\n    \\\"\\\"\\\"Test HTTP client instrumentation in ArizePhoenixTracer.\\\"\\\"\\\"\\n\\n    @pytest.fixture(autouse=True)\\n    def reset_manager(self):\\n        \\\"\\\"\\\"Reset the singleton manager between tests.\\\"\\\"\\\"\\n        from langflow.services.tracing.http_instrumentation import HTTPClientInstrumentationManager\\n\\n        HTTPClientInstrumentationManager._instance = None\\n        yield\\n        HTTPClientInstrumentationManager._instance = None\\n\\n    @pytest.fixture\\n    def mock_phoenix_imports(self):\\n        \\\"\\\"\\\"Mock phoenix.otel imports to avoid requiring the actual package.\\\"\\\"\\\"\\n        mock_provider = MagicMock(spec=TracerProvider)\\n        mock_provider.get_tracer.return_value = MagicMock()\\n\\n        with (\\n            patch.dict(os.environ, {\\\"PHOENIX_COLLECTOR_ENDPOINT\\\": \\\"http://localhost:6006\\\"}),\\n            patch(\\\"phoenix.otel.TracerProvider\\\", return_value=mock_provider),\\n            patch(\\\"phoenix.otel.Resource\\\"),\\n            patch(\\\"phoenix.otel.SimpleSpanProcessor\\\"),\\n            patch(\\\"phoenix.otel.BatchSpanProcessor\\\"),\\n            patch(\\\"phoenix.otel.HTTPSpanExporter\\\"),\\n            patch(\\\"phoenix.otel.GRPCSpanExporter\\\"),\\n            patch(\\\"phoenix.otel.PROJECT_NAME\\\", \\\"test\\\"),\\n            patch(\\\"openinference.instrumentation.langchain.LangChainInstrumentor\\\"),\\n        ):\\n            yield mock_provider\\n\\n    def test_instrument_http_clients_called_on_setup(self, mock_phoenix_imports):\\n        \\\"\\\"\\\"Verify that HTTP client instrumentors are called during tracer setup.\\\"\\\"\\\"\\n        _ = mock_phoenix_imports\\n        with (\\n            patch(\\\"opentelemetry.instrumentation.requests.RequestsInstrumentor\\\") as mock_requests_inst,\\n            patch(\\\"opentelemetry.instrumentation.urllib3.URLLib3Instrumentor\\\") as mock_urllib3_inst,\\n        ):\\n            mock_requests_inst.return_value.instrument = MagicMock()\\n            mock_urllib3_inst.return_value.instrument = MagicMock()\\n\\n            from langflow.services.tracing.arize_phoenix import ArizePhoenixTracer\\n\\n            tracer = ArizePhoenixTracer(\\n                trace_name=\\\"test - abc123\\\",\\n                trace_type=\\\"chain\\\",\\n                project_name=\\\"test\\\",\\n                trace_id=uuid.uuid4(),\\n            )\\n\\n            if tracer.ready:\\n                mock_requests_inst.return_value.instrument.assert_called_once()\\n                mock_urllib3_inst.return_value.instrument.assert_called_once()\\n\\n    def test_uninstrument_http_clients_called_on_end(self, mock_phoenix_imports):\\n        \\\"\\\"\\\"Verify that HTTP client instrumentors are uninstrumented when tracer ends.\\\"\\\"\\\"\\n        _ = mock_phoenix_imports\\n        with (\\n            patch(\\\"opentelemetry.instrumentation.requests.RequestsInstrumentor\\\") as mock_requests_inst,\\n            patch(\\\"opentelemetry.instrumentation.urllib3.URLLib3Instrumentor\\\") as mock_urllib3_inst,\\n        ):\\n            mock_requests_inst.return_value.instrument = MagicMock()\\n            mock_requests_inst.return_value.uninstrument = MagicMock()\\n            mock_urllib3_inst.return_value.instrument = MagicMock()\\n            mock_urllib3_inst.return_value.uninstrument = MagicMock()\\n\\n            from langflow.services.tracing.arize_phoenix import ArizePhoenixTracer\\n\\n            tracer = ArizePhoenixTracer(\\n                trace_name=\\\"test - abc123\\\",\\n                trace_type=\\\"chain\\\",\\n                project_name=\\\"test\\\",\\n                trace_id=uuid.uuid4(),\\n            )\\n\\n            if tracer.ready:\\n                tracer.end(inputs={}, outputs={})\\n                mock_requests_inst.return_value.uninstrument.assert_called_once()\\n                mock_urllib3_inst.return_value.uninstrument.assert_called_once()\\n\\n\\n_langwatch_available = False\\ntry:\\n    import langwatch  # noqa: F401\\n\\n    _langwatch_available = True\\nexcept ImportError:\\n    # langwatch is gated to python_version<'3.14' upstream.\\n    pass\\n\\n\\n@pytest.mark.skipif(not _langwatch_available, reason=\\\"langwatch not available on Python 3.14+\\\")\\nclass TestLangWatchHttpInstrumentation:\\n    \\\"\\\"\\\"Test HTTP client instrumentation in LangWatchTracer.\\\"\\\"\\\"\\n\\n    @pytest.fixture(autouse=True)\\n    def reset_manager(self):\\n        \\\"\\\"\\\"Reset the singleton manager between tests.\\\"\\\"\\\"\\n        from langflow.services.tracing.http_instrumentation import HTTPClientInstrumentationManager\\n\\n        HTTPClientInstrumentationManager._instance = None\\n        yield\\n        HTTPClientInstrumentationManager._instance = None\\n\\n    @pytest.fixture\\n    def mock_langwatch_imports(self):\\n        \\\"\\\"\\\"Mock langwatch imports to avoid requiring the actual package.\\\"\\\"\\\"\\n        mock_trace = MagicMock()\\n        mock_trace.root_span = MagicMock()\\n        mock_trace.api_key = \\\"test-key\\\"  # pragma: allowlist secret\\n        mock_trace.__enter__ = MagicMock(return_value=mock_trace)\\n        mock_trace.__exit__ = MagicMock(return_value=None)\\n\\n        mock_client = MagicMock()\\n        mock_client.trace.return_value = mock_trace\\n        mock_client._api_key = \\\"test-key\\\"  # pragma: allowlist secret\\n\\n        with (\\n            patch.dict(os.environ, {\\\"LANGWATCH_API_KEY\\\": \\\"test-key\\\"}),  # pragma: allowlist secret\\n            patch(\\\"langwatch.setup\\\"),\\n            patch(\\\"langwatch.trace\\\", return_value=mock_trace),\\n            patch(\\\"opentelemetry.exporter.otlp.proto.http.trace_exporter.OTLPSpanExporter\\\"),\\n        ):\\n            yield mock_client\\n\\n    def test_instrument_http_clients_called_on_setup(self, mock_langwatch_imports):\\n        \\\"\\\"\\\"Verify that HTTP client instrumentors are called during tracer setup.\\\"\\\"\\\"\\n        _ = mock_langwatch_imports\\n        from langflow.services.tracing.langwatch import LangWatchTracer\\n\\n        LangWatchTracer.tracer_provider = None\\n\\n        with (\\n            patch(\\\"opentelemetry.instrumentation.requests.RequestsInstrumentor\\\") as mock_requests_inst,\\n            patch(\\\"opentelemetry.instrumentation.urllib3.URLLib3Instrumentor\\\") as mock_urllib3_inst,\\n        ):\\n            mock_requests_inst.return_value.instrument = MagicMock()\\n            mock_urllib3_inst.return_value.instrument = MagicMock()\\n\\n            tracer = LangWatchTracer(\\n                trace_name=\\\"test - abc123\\\",\\n                trace_type=\\\"chain\\\",\\n                project_name=\\\"test\\\",\\n                trace_id=uuid.uuid4(),\\n            )\\n\\n            if tracer.ready:\\n                mock_requests_inst.return_value.instrument.assert_called_once()\\n                mock_urllib3_inst.return_value.instrument.assert_called_once()\\n\\n    def test_uninstrument_http_clients_called_on_end(self, mock_langwatch_imports):\\n        \\\"\\\"\\\"Verify that HTTP client instrumentors are uninstrumented when tracer ends.\\\"\\\"\\\"\\n        _ = mock_langwatch_imports\\n        from langflow.services.tracing.langwatch import LangWatchTracer\\n\\n        LangWatchTracer.tracer_provider = None\\n\\n        with (\\n            patch(\\\"opentelemetry.instrumentation.requests.RequestsInstrumentor\\\") as mock_requests_inst,\\n            patch(\\\"opentelemetry.instrumentation.urllib3.URLLib3Instrumentor\\\") as mock_urllib3_inst,\\n        ):\\n            mock_requests_inst.return_value.instrument = MagicMock()\\n            mock_requests_inst.return_value.uninstrument = MagicMock()\\n            mock_urllib3_inst.return_value.instrument = MagicMock()\\n            mock_urllib3_inst.return_value.uninstrument = MagicMock()\\n\\n            tracer = LangWatchTracer(\\n                trace_name=\\\"test - abc123\\\",\\n                trace_type=\\\"chain\\\",\\n                project_name=\\\"test\\\",\\n                trace_id=uuid.uuid4(),\\n            )\\n\\n            if tracer.ready:\\n                tracer.end(inputs={}, outputs={})\\n                mock_requests_inst.return_value.uninstrument.assert_called_once()\\n                mock_urllib3_inst.return_value.uninstrument.assert_called_once()\\n\\n\\n@pytest.mark.skip(reason=\\\"These tests mock at the wrong layer - Session.send mock bypasses OTel instrumentation\\\")\\nclass TestTraceContextPropagation:\\n    \\\"\\\"\\\"Integration tests verifying traceparent header is actually injected.\\\"\\\"\\\"\\n\\n    def test_traceparent_header_injected_on_requests(self):\\n        \\\"\\\"\\\"Verify that traceparent header is injected on outgoing HTTP requests.\\\"\\\"\\\"\\n        import requests\\n        from opentelemetry.instrumentation.requests import RequestsInstrumentor\\n\\n        exporter = InMemorySpanExporter()\\n        provider = TracerProvider()\\n        provider.add_span_processor(SimpleSpanProcessor(exporter))\\n\\n        RequestsInstrumentor().instrument(tracer_provider=provider)\\n\\n        try:\\n            captured_headers = {}\\n\\n            def capturing_send(_self, request, **_kwargs):\\n                captured_headers.update(dict(request.headers))\\n                mock_response = MagicMock()\\n                mock_response.status_code = 200\\n                mock_response.headers = {}\\n                mock_response.content = b\\\"\\\"\\n                mock_response.text = \\\"\\\"\\n                mock_response.json.return_value = {}\\n                mock_response.elapsed = MagicMock()\\n                mock_response.elapsed.total_seconds.return_value = 0.1\\n                return mock_response\\n\\n            with patch.object(requests.Session, \\\"send\\\", capturing_send):\\n                tracer = provider.get_tracer(__name__)\\n                with tracer.start_as_current_span(\\\"test-span\\\"):\\n                    requests.get(\\\"http://example.com/test\\\", timeout=10)\\n\\n            assert \\\"traceparent\\\" in captured_headers, f\\\"traceparent header not found in {list(captured_headers.keys())}\\\"\\n            assert captured_headers[\\\"traceparent\\\"].startswith(\\\"00-\\\"), \\\"traceparent should start with version 00\\\"\\n        finally:\\n            RequestsInstrumentor().uninstrument()\\n\\n    def test_traceparent_format_is_valid(self):\\n        \\\"\\\"\\\"Verify that the traceparent header has valid W3C format.\\\"\\\"\\\"\\n        import requests\\n        from opentelemetry.instrumentation.requests import RequestsInstrumentor\\n\\n        provider = TracerProvider()\\n        RequestsInstrumentor().instrument(tracer_provider=provider)\\n\\n        try:\\n            captured_headers = {}\\n\\n            def capturing_send(_self, request, **_kwargs):\\n                captured_headers.update(dict(request.headers))\\n                mock_response = MagicMock()\\n                mock_response.status_code = 200\\n                mock_response.headers = {}\\n                mock_response.content = b\\\"\\\"\\n                mock_response.text = \\\"\\\"\\n                mock_response.json.return_value = {}\\n                mock_response.elapsed = MagicMock()\\n                mock_response.elapsed.total_seconds.return_value = 0.1\\n                return mock_response\\n\\n            with patch.object(requests.Session, \\\"send\\\", capturing_send):\\n                tracer = provider.get_tracer(__name__)\\n                with tracer.start_as_current_span(\\\"test-span\\\"):\\n                    requests.get(\\\"http://example.com/test\\\", timeout=10)\\n\\n            traceparent = captured_headers.get(\\\"traceparent\\\", \\\"\\\")\\n            pattern = r\\\"^00-[0-9a-f]{32}-[0-9a-f]{16}-[0-9a-f]{2}$\\\"\\n            assert re.match(pattern, traceparent), f\\\"traceparent '{traceparent}' does not match W3C format\\\"\\n        finally:\\n            RequestsInstrumentor().uninstrument()\\n\\n    def test_urllib3_traceparent_header_injected(self):\\n        \\\"\\\"\\\"Verify that traceparent header is injected on urllib3 requests.\\\"\\\"\\\"\\n        import urllib3\\n        from opentelemetry.instrumentation.urllib3 import URLLib3Instrumentor\\n\\n        provider = TracerProvider()\\n        URLLib3Instrumentor().instrument(tracer_provider=provider)\\n\\n        try:\\n            captured_headers = {}\\n\\n            def capturing_urlopen(_self, _method, _url, body=None, headers=None, **_kwargs):  # noqa: ARG001\\n                if headers:\\n                    captured_headers.update(dict(headers))\\n                mock_response = MagicMock()\\n                mock_response.status = 200\\n                mock_response.headers = {}\\n                mock_response.data = b\\\"\\\"\\n                return mock_response\\n\\n            with patch.object(urllib3.HTTPConnectionPool, \\\"urlopen\\\", capturing_urlopen):\\n                tracer = provider.get_tracer(__name__)\\n                with tracer.start_as_current_span(\\\"test-span\\\"):\\n                    http = urllib3.PoolManager()\\n                    http.request(\\\"GET\\\", \\\"http://example.com/test\\\")\\n\\n            assert \\\"traceparent\\\" in captured_headers, f\\\"traceparent header not found in {list(captured_headers.keys())}\\\"\\n        finally:\\n            URLLib3Instrumentor().uninstrument()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/tracing/test_langfuse_orphan_generation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1ac5a3c5aa9825927980845b031d697566801f5a8aabffb8c14486ec780617e4\",\"content\":\"\\\"\\\"\\\"Regression tests for the Langfuse orphan-generation fix (issue #13429).\\n\\nWhen a model runs as the *root* LangChain run \u2014 i.e. invoked directly with no\\nwrapping chain, as reproduced with Ollama \u2014 the langfuse v3 ``CallbackHandler``\\nemitted the LLM generation as a separate, orphan trace: ``parent = None``,\\n``userId = None``, ``sessionId = None``, and the token usage detached from the\\nflow trace. The langfuse SDK only applies the constructor ``trace_context`` on\\nthe chain path, so a bare model's generation started a brand-new trace.\\n\\n``LangFuseTracer.get_langchain_callback`` now returns a handler that re-parents\\nroot LLM runs under the flow's component (or root) span, so the generation\\nshares the flow ``trace_id`` and stays attributed to the user/session.\\n\\nThe end-to-end test exercises the real langfuse SDK with an in-memory\\nOpenTelemetry exporter \u2014 a pure mock cannot catch this bug because the orphaning\\nhappens inside the SDK's generation path.\\n\\\"\\\"\\\"\\n\\nimport os\\nimport uuid\\nfrom unittest.mock import patch\\n\\nimport pytest\\n\\n\\n@pytest.fixture(autouse=True)\\ndef langfuse_env_vars():\\n    \\\"\\\"\\\"Set fake langfuse credentials for testing.\\\"\\\"\\\"\\n    with patch.dict(\\n        os.environ,\\n        {\\n            \\\"LANGFUSE_SECRET_KEY\\\": \\\"sk-lf-test\\\",  # pragma: allowlist secret\\n            \\\"LANGFUSE_PUBLIC_KEY\\\": \\\"pk-lf-test\\\",\\n            \\\"LANGFUSE_HOST\\\": \\\"http://localhost:3000\\\",\\n        },\\n    ):\\n        yield\\n\\n\\n@pytest.fixture(autouse=True)\\ndef reset_langfuse_shared_client():\\n    \\\"\\\"\\\"Clear the cached Langfuse client between tests so mocks don't leak.\\\"\\\"\\\"\\n    from langflow.services.tracing.langfuse import _reset_shared_client_for_tests\\n\\n    _reset_shared_client_for_tests()\\n    yield\\n    _reset_shared_client_for_tests()\\n\\n\\nclass TestOtelParentSpanBuilder:\\n    \\\"\\\"\\\"``_build_otel_parent_span`` turns the flow ids into an OTel parent span.\\\"\\\"\\\"\\n\\n    def test_returns_none_when_ids_missing(self):\\n        from langflow.services.tracing.langfuse import _build_otel_parent_span\\n\\n        assert _build_otel_parent_span(None, \\\"b\\\" * 16) is None\\n        assert _build_otel_parent_span(\\\"a\\\" * 32, None) is None\\n        assert _build_otel_parent_span(\\\"\\\", \\\"\\\") is None\\n\\n    def test_returns_none_for_non_hex_ids(self):\\n        \\\"\\\"\\\"Mock span ids (non-hex) degrade gracefully instead of raising.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import _build_otel_parent_span\\n\\n        assert _build_otel_parent_span(\\\"not-hex\\\", \\\"child-span-id\\\") is None\\n\\n    def test_builds_span_context_from_hex_ids(self):\\n        from langflow.services.tracing.langfuse import _build_otel_parent_span\\n\\n        trace_id = \\\"a\\\" * 32\\n        span_id = \\\"b\\\" * 16\\n        parent = _build_otel_parent_span(trace_id, span_id)\\n\\n        assert parent is not None\\n        ctx = parent.get_span_context()\\n        assert ctx.trace_id == int(trace_id, 16)\\n        assert ctx.span_id == int(span_id, 16)\\n        # Sampled so downstream generations are recorded under the flow trace.\\n        assert ctx.trace_flags.sampled\\n\\n\\nclass _RecordingBase:\\n    \\\"\\\"\\\"Stand-in for langfuse's ``CallbackHandler`` that records OTel context.\\n\\n    Each LLM-start callback records the span context that is *current* at the\\n    moment the SDK would create the generation span. The re-parenting subclass\\n    is expected to make the flow's parent span current for root runs only.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, *, trace_context=None, **kwargs):  # noqa: ARG002\\n        self.trace_context = trace_context\\n        self.captured = []\\n\\n    def _record(self):\\n        from opentelemetry import trace as otel_trace_api\\n\\n        self.captured.append(otel_trace_api.get_current_span().get_span_context())\\n\\n    def on_chat_model_start(self, *args, **kwargs):  # noqa: ARG002\\n        self._record()\\n\\n    def on_llm_start(self, *args, **kwargs):  # noqa: ARG002\\n        self._record()\\n\\n\\nclass TestRootRunReparentingHandler:\\n    \\\"\\\"\\\"The subclass activates the parent span for root LLM runs only.\\\"\\\"\\\"\\n\\n    def _make_handler(self, trace_id=\\\"a\\\" * 32, span_id=\\\"b\\\" * 16, *, with_parent=True):\\n        from langflow.services.tracing.langfuse import (\\n            _build_otel_parent_span,\\n            _root_run_reparenting_handler_cls,\\n        )\\n\\n        handler_cls = _root_run_reparenting_handler_cls(_RecordingBase)\\n        otel_parent = _build_otel_parent_span(trace_id, span_id) if with_parent else None\\n        handler = handler_cls(\\n            trace_context={\\\"trace_id\\\": trace_id, \\\"parent_span_id\\\": span_id},\\n            otel_parent=otel_parent,\\n        )\\n        return handler, trace_id, span_id\\n\\n    def test_activates_parent_for_root_chat_model_run(self):\\n        handler, trace_id, span_id = self._make_handler()\\n\\n        handler.on_chat_model_start({}, [], run_id=uuid.uuid4(), parent_run_id=None)\\n\\n        ctx = handler.captured[-1]\\n        assert ctx.is_valid\\n        assert ctx.trace_id == int(trace_id, 16)\\n        assert ctx.span_id == int(span_id, 16)\\n\\n    def test_activates_parent_for_root_llm_run(self):\\n        handler, trace_id, span_id = self._make_handler()\\n\\n        handler.on_llm_start({}, [], run_id=uuid.uuid4(), parent_run_id=None)\\n\\n        ctx = handler.captured[-1]\\n        assert ctx.is_valid\\n        assert ctx.trace_id == int(trace_id, 16)\\n        assert ctx.span_id == int(span_id, 16)\\n\\n    def test_does_not_activate_for_non_root_run(self):\\n        \\\"\\\"\\\"A wrapping chain/agent is present (parent_run_id set) \u2192 leave untouched.\\n\\n        The SDK already nests these correctly under the chain span, so the\\n        handler must not force the flow parent into the OTel context.\\n        \\\"\\\"\\\"\\n        handler, _, _ = self._make_handler()\\n\\n        handler.on_chat_model_start({}, [], run_id=uuid.uuid4(), parent_run_id=uuid.uuid4())\\n\\n        ctx = handler.captured[-1]\\n        # No span was activated \u2192 ambient context is the invalid root span.\\n        assert not ctx.is_valid\\n\\n    def test_missing_parent_is_safe(self):\\n        \\\"\\\"\\\"When the parent span id is not resolvable, root runs simply no-op.\\\"\\\"\\\"\\n        handler, _, _ = self._make_handler(with_parent=False)\\n\\n        handler.on_chat_model_start({}, [], run_id=uuid.uuid4(), parent_run_id=None)\\n\\n        ctx = handler.captured[-1]\\n        assert not ctx.is_valid\\n\\n    def test_handler_is_deepcopy_and_copy_safe(self):\\n        \\\"\\\"\\\"Survive ``copy.deepcopy`` / ``copy.copy`` by returning self.\\n\\n        The handler never recurses into the langfuse client.\\n\\n        Langflow deep-copies flow/graph state (restore-point snapshots, working-flow\\n        copies, component build). The real langfuse ``CallbackHandler`` / ``Langfuse``\\n        client is NOT deep-copyable \u2014 its singleton ``LangfuseResourceManager.__new__``\\n        is keyword-only, so ``copy.deepcopy`` (which calls ``cls.__new__(cls)`` with\\n        no args) raises ``TypeError: __new__() missing 3 required keyword-only\\n        arguments``. That surfaced to users as a failed Agent build. A base whose\\n        deepcopy explodes stands in for that; the subclass must short-circuit it.\\n        \\\"\\\"\\\"\\n        import copy\\n\\n        from langflow.services.tracing.langfuse import _root_run_reparenting_handler_cls\\n\\n        class _NonCopyableBase:\\n            def __init__(self, *, trace_context=None, **kwargs):  # noqa: ARG002\\n                self.trace_context = trace_context\\n\\n            def __deepcopy__(self, memo):\\n                msg = \\\"LangfuseResourceManager.__new__() missing 3 required keyword-only arguments\\\"\\n                raise TypeError(msg)\\n\\n            def __copy__(self):\\n                msg = \\\"LangfuseResourceManager.__new__() missing 3 required keyword-only arguments\\\"\\n                raise TypeError(msg)\\n\\n        handler_cls = _root_run_reparenting_handler_cls(_NonCopyableBase)\\n        handler = handler_cls(trace_context={\\\"trace_id\\\": \\\"a\\\" * 32}, otel_parent=None)\\n\\n        assert copy.deepcopy(handler) is handler\\n        assert copy.copy(handler) is handler\\n        # Deep-copying a container that holds the handler must not raise either.\\n        assert copy.deepcopy({\\\"callbacks\\\": [handler]})[\\\"callbacks\\\"][0] is handler\\n\\n\\ndef _build_real_langfuse_client_or_skip(tracer_provider):\\n    \\\"\\\"\\\"Construct a real Langfuse client wired to ``tracer_provider``.\\n\\n    Its network OTLP exporter is replaced with a no-op so the test stays local\\n    and fast (no connection to a Langfuse server). Skips if the SDK cannot be\\n    imported on this interpreter (e.g. pydantic/python version mismatch).\\n    \\\"\\\"\\\"\\n    try:\\n        from langfuse import Langfuse\\n        from opentelemetry.sdk.trace.export import SpanExportResult\\n    except Exception as exc:\\n        pytest.skip(f\\\"langfuse SDK is not importable: {exc}\\\")\\n\\n    class _NoopOtlpExporter:\\n        def __init__(self, *args, **kwargs):\\n            pass\\n\\n        def export(self, spans):  # noqa: ARG002\\n            return SpanExportResult.SUCCESS\\n\\n        def shutdown(self):\\n            pass\\n\\n        def force_flush(self, timeout_millis=30000):  # noqa: ARG002\\n            return True\\n\\n    with patch(\\\"langfuse._client.span_processor.OTLPSpanExporter\\\", _NoopOtlpExporter):\\n        client = Langfuse(\\n            public_key=\\\"pk-lf-test\\\",\\n            secret_key=\\\"sk-lf-test\\\",  # noqa: S106  # pragma: allowlist secret\\n            host=\\\"http://localhost:3000\\\",\\n            tracer_provider=tracer_provider,\\n            tracing_enabled=True,\\n        )\\n    # Avoid a network round-trip during tracer setup's health check.\\n    client.auth_check = lambda: True\\n    return client\\n\\n\\nclass TestRootGenerationNestsUnderFlowTrace:\\n    \\\"\\\"\\\"End-to-end: a root LLM generation shares the flow trace (issue #13429).\\\"\\\"\\\"\\n\\n    def test_root_llm_generation_shares_flow_trace_and_nests_under_component(self):\\n        pytest.importorskip(\\\"langfuse\\\")\\n        pytest.importorskip(\\\"langchain_core\\\")\\n        import langflow.services.tracing.langfuse as langfuse_module\\n        from langchain_core.messages import AIMessage, HumanMessage\\n        from langchain_core.outputs import ChatGeneration, LLMResult\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n        from opentelemetry.sdk.trace import TracerProvider\\n        from opentelemetry.sdk.trace.export import SimpleSpanProcessor\\n        from opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\n\\n        exporter = InMemorySpanExporter()\\n        provider = TracerProvider()\\n        provider.add_span_processor(SimpleSpanProcessor(exporter))\\n        client = _build_real_langfuse_client_or_skip(provider)\\n\\n        with patch.object(langfuse_module, \\\"_get_or_create_shared_client\\\", lambda config: client):  # noqa: ARG005\\n            try:\\n                tracer = LangFuseTracer(\\n                    trace_name=\\\"repro - flow-xyz\\\",\\n                    trace_type=\\\"chain\\\",\\n                    project_name=\\\"proj\\\",\\n                    trace_id=uuid.uuid4(),\\n                    user_id=\\\"demo-user-13429\\\",\\n                    session_id=\\\"demo-session-13429\\\",\\n                )\\n                assert tracer.ready\\n\\n                # Open a component span, then run a bare chat model as the root\\n                # LangChain run (parent_run_id=None) \u2014 the orphan-trace condition.\\n                tracer.add_trace(\\\"comp-ollama\\\", \\\"Ollama (comp-ollama)\\\", \\\"llm\\\", {\\\"input\\\": \\\"hi\\\"})\\n                handler = tracer.get_langchain_callback()\\n                assert handler is not None\\n\\n                run_id = uuid.uuid4()\\n                handler.on_chat_model_start(\\n                    {\\\"id\\\": [\\\"langchain\\\", \\\"chat_models\\\", \\\"ollama\\\", \\\"ChatOllama\\\"]},\\n                    [[HumanMessage(content=\\\"hi\\\")]],\\n                    run_id=run_id,\\n                    parent_run_id=None,\\n                    invocation_params={},\\n                )\\n                handler.on_llm_end(\\n                    LLMResult(generations=[[ChatGeneration(message=AIMessage(content=\\\"ok\\\"), generation_info={})]]),\\n                    run_id=run_id,\\n                    parent_run_id=None,\\n                )\\n                tracer.end_trace(\\\"comp-ollama\\\", \\\"Ollama\\\", outputs={\\\"output\\\": \\\"ok\\\"})\\n                tracer.end(inputs={\\\"in\\\": \\\"hi\\\"}, outputs={\\\"out\\\": \\\"ok\\\"})\\n            finally:\\n                client.shutdown()\\n\\n        spans = {s.name: s for s in exporter.get_finished_spans()}\\n        # The flow root span carries the flow *display name*, not its id (LE-2451 / #14865).\\n        assert \\\"repro\\\" in spans, f\\\"missing flow root span; got {list(spans)}\\\"\\n        assert \\\"Ollama\\\" in spans, f\\\"missing component span; got {list(spans)}\\\"\\n        assert \\\"ChatOllama\\\" in spans, f\\\"missing generation span; got {list(spans)}\\\"\\n\\n        root_span = spans[\\\"repro\\\"]\\n        component_span = spans[\\\"Ollama\\\"]\\n        generation_span = spans[\\\"ChatOllama\\\"]\\n\\n        # Langfuse indexes ``langfuse.trace.name`` for its name search; the id stays in metadata.\\n        assert root_span.attributes.get(\\\"langfuse.trace.name\\\") == \\\"repro\\\"\\n        assert root_span.attributes.get(\\\"langfuse.observation.metadata.flow_id\\\") == \\\"flow-xyz\\\"\\n\\n        # The generation is recorded as a langfuse generation (carries token usage).\\n        assert generation_span.attributes.get(\\\"langfuse.observation.type\\\") == \\\"generation\\\"\\n\\n        # Core of #13429: the generation must live in the flow trace, not orphan.\\n        assert generation_span.context.trace_id == root_span.context.trace_id\\n        # And nest under the component span (not be a root of its own trace).\\n        assert generation_span.parent is not None\\n        assert generation_span.parent.span_id == component_span.context.span_id\\n\\n\\nclass TestFlowNameParsing:\\n    \\\"\\\"\\\"``LangFuseTracer`` names the trace after the flow, parsed out of ``trace_name``.\\n\\n    The graph builds ``trace_name`` as ``f\\\"{flow_name} - {flow_id}\\\"`` (LE-2451 / #14865).\\n    \\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _make_tracer(trace_name: str):\\n        pytest.importorskip(\\\"langfuse\\\")\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n        with patch(\\\"langflow.services.tracing.langfuse._get_or_create_shared_client\\\") as mock_client:\\n            mock_client.return_value.auth_check.return_value = True\\n            tracer = LangFuseTracer(\\n                trace_name=trace_name,\\n                trace_type=\\\"flow\\\",\\n                project_name=\\\"test-project\\\",\\n                trace_id=uuid.uuid4(),\\n            )\\n        assert tracer.ready, \\\"tracer setup failed; the SDK calls below were never made\\\"\\n        return tracer, mock_client.return_value\\n\\n    @pytest.mark.parametrize(\\n        (\\\"trace_name\\\", \\\"expected_name\\\", \\\"expected_flow_id\\\"),\\n        [\\n            (\\\"demo flow - flow-xyz\\\", \\\"demo flow\\\", \\\"flow-xyz\\\"),\\n            # A display name containing the separator must not be truncated.\\n            (\\\"Customer - Agent - flow-xyz\\\", \\\"Customer - Agent\\\", \\\"flow-xyz\\\"),\\n        ],\\n    )\\n    def test_trace_is_named_after_the_flow(self, trace_name, expected_name, expected_flow_id):\\n        tracer, client = self._make_tracer(trace_name)\\n\\n        assert tracer.flow_name == expected_name\\n        assert tracer.flow_id == expected_flow_id\\n        assert client.start_span.call_args.kwargs[\\\"name\\\"] == expected_name\\n        assert client.start_span.call_args.kwargs[\\\"metadata\\\"][\\\"flow_id\\\"] == expected_flow_id\\n        trace_update = client.start_span.return_value.update_trace.call_args.kwargs\\n        assert trace_update[\\\"name\\\"] == expected_name\\n        assert trace_update[\\\"metadata\\\"][\\\"flow_id\\\"] == expected_flow_id\\n\\n    def test_unnamed_flow_falls_back_to_flow_id(self):\\n        # An unnamed graph formats its run name as \\\"None - <id>\\\"; the trace must not be called \\\"None\\\".\\n        tracer, client = self._make_tracer(\\\"None - flow-xyz\\\")\\n\\n        assert tracer.flow_id == \\\"flow-xyz\\\"\\n        assert client.start_span.call_args.kwargs[\\\"name\\\"] == \\\"flow-xyz\\\"\\n        assert client.start_span.return_value.update_trace.call_args.kwargs[\\\"name\\\"] == \\\"flow-xyz\\\"\\n\\n\\nclass TestGraphRunNamesTraceAfterFlow:\\n    \\\"\\\"\\\"A real multi-component graph run names the Langfuse trace after the flow (LE-2451 / #14865).\\n\\n    Drives the real graph engine and the real ``TracingService`` so the run name reaches\\n    ``LangFuseTracer`` exactly as in production (``f\\\"{flow_name} - {flow_id}\\\"``), then inspects\\n    the spans the langfuse SDK exports.\\n    \\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _build_graph(flow_name: str, flow_id: str):\\n        from lfx.components.input_output import ChatInput, ChatOutput, TextInputComponent, TextOutputComponent\\n        from lfx.components.processing import CombineTextComponent\\n        from lfx.graph.graph.base import Graph\\n\\n        chat_in = ChatInput(_id=\\\"chat-in\\\")\\n        chat_in.set(input_value=\\\"hello\\\", should_store_message=False, session_id=\\\"session-le2451\\\")\\n        text_in = TextInputComponent(_id=\\\"text-in\\\")\\n        text_in.set(input_value=\\\"from text input\\\")\\n        combine = CombineTextComponent(_id=\\\"combine\\\")\\n        combine.set(text1=chat_in.message_response, text2=text_in.text_response, delimiter=\\\" | \\\")\\n        text_out = TextOutputComponent(_id=\\\"text-out\\\")\\n        text_out.set(input_value=combine.combine_texts)\\n        chat_out = ChatOutput(_id=\\\"chat-out\\\")\\n        chat_out.set(input_value=text_out.text_response, should_store_message=False, session_id=\\\"session-le2451\\\")\\n        return Graph(start=chat_in, end=chat_out, flow_id=flow_id, flow_name=flow_name, user_id=\\\"user-le2451\\\")\\n\\n    @pytest.mark.asyncio\\n    async def test_five_component_graph_run(self):\\n        pytest.importorskip(\\\"langfuse\\\")\\n        import asyncio\\n        import contextlib\\n        from unittest.mock import MagicMock\\n\\n        import langflow.services.tracing.langfuse as langfuse_module\\n        from langflow.services.tracing.base import BaseTracer\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n        from langflow.services.tracing.service import TracingService\\n        from lfx.services.settings.base import Settings\\n        from lfx.services.settings.service import SettingsService\\n        from opentelemetry.sdk.trace import TracerProvider\\n        from opentelemetry.sdk.trace.export import SimpleSpanProcessor\\n        from opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\n\\n        class _InertTracer(BaseTracer):\\n            \\\"\\\"\\\"Stands in for every non-Langfuse provider so only Langfuse is exercised.\\\"\\\"\\\"\\n\\n            def __init__(self, *args, **kwargs):\\n                pass\\n\\n            @property\\n            def ready(self):\\n                return False\\n\\n            def add_trace(self, *args, **kwargs):\\n                pass\\n\\n            def end_trace(self, *args, **kwargs):\\n                pass\\n\\n            def end(self, *args, **kwargs):\\n                pass\\n\\n            def get_langchain_callback(self):\\n                return None\\n\\n        flow_id = str(uuid.uuid4())\\n        flow_name = \\\"Customer - Agent\\\"\\n\\n        exporter = InMemorySpanExporter()\\n        provider = TracerProvider()\\n        provider.add_span_processor(SimpleSpanProcessor(exporter))\\n        client = _build_real_langfuse_client_or_skip(provider)\\n\\n        settings = Settings()\\n        settings.deactivate_tracing = False\\n        service = TracingService(SettingsService(settings, MagicMock()))\\n\\n        with contextlib.ExitStack() as stack:\\n            stack.enter_context(\\n                patch.object(langfuse_module, \\\"_get_or_create_shared_client\\\", lambda config: client)  # noqa: ARG005\\n            )\\n            stack.enter_context(\\n                patch(\\\"langflow.services.tracing.service._get_langfuse_tracer\\\", return_value=LangFuseTracer)\\n            )\\n            # Components resolve the tracing service lazily through lfx deps.\\n            stack.enter_context(patch(\\\"lfx.services.deps.get_tracing_service\\\", return_value=service))\\n            for name in (\\\"langsmith\\\", \\\"langwatch\\\", \\\"arize_phoenix\\\", \\\"opik\\\", \\\"traceloop\\\", \\\"native\\\", \\\"openlayer\\\"):\\n                stack.enter_context(\\n                    patch(f\\\"langflow.services.tracing.service._get_{name}_tracer\\\", return_value=_InertTracer)\\n                )\\n            try:\\n                graph = self._build_graph(flow_name, flow_id)\\n                graph._tracing_service = service\\n                graph._tracing_service_initialized = True\\n                graph.session_id = \\\"session-le2451\\\"\\n                graph.prepare()\\n                ran = [result.vertex.id async for result in graph.async_start() if hasattr(result, \\\"vertex\\\")]\\n                # The graph ends the trace in a background task; wait for it before reading spans.\\n                await asyncio.gather(*graph._end_trace_tasks)\\n            finally:\\n                client.shutdown()\\n\\n        assert ran == [\\\"chat-in\\\", \\\"text-in\\\", \\\"combine\\\", \\\"text-out\\\", \\\"chat-out\\\"]\\n\\n        spans = exporter.get_finished_spans()\\n        exported_ids = {s.context.span_id for s in spans}\\n        roots = [s for s in spans if s.parent is None or s.parent.span_id not in exported_ids]\\n        assert [s.name for s in roots] == [flow_name], f\\\"unexpected root spans; got {[s.name for s in spans]}\\\"\\n        root = roots[0]\\n\\n        assert root.attributes.get(\\\"langfuse.trace.name\\\") == flow_name\\n        assert root.attributes.get(\\\"langfuse.observation.metadata.flow_id\\\") == flow_id\\n        assert root.attributes.get(\\\"langfuse.trace.metadata.flow_id\\\") == flow_id\\n\\n        children = [s for s in spans if s is not root]\\n        assert {s.name for s in children} == {\\\"Chat Input\\\", \\\"Text Input\\\", \\\"Combine Text\\\", \\\"Text Output\\\", \\\"Chat Output\\\"}\\n        assert all(s.parent.span_id == root.context.span_id for s in children)\\n        assert len({s.context.trace_id for s in spans}) == 1\\n\\n\\ndef test_handler_deepcopy_returns_self(monkeypatch):\\n    \\\"\\\"\\\"Regression test for https://github.com/langflow-ai/langflow/issues/13965.\\n\\n    _RootRunReparentingCallbackHandler.__deepcopy__ must return self so that\\n    deepcopy(component) in component_tool.py never triggers\\n    LangfuseResourceManager.__new__() with missing credential kwargs.\\n    \\\"\\\"\\\"\\n    import copy\\n\\n    monkeypatch.setenv(\\\"LANGFUSE_SECRET_KEY\\\", \\\"sk-test\\\")\\n    monkeypatch.setenv(\\\"LANGFUSE_PUBLIC_KEY\\\", \\\"pk-test\\\")\\n    monkeypatch.setenv(\\\"LANGFUSE_BASE_URL\\\", \\\"http://localhost:3000\\\")\\n\\n    from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n    with patch(\\\"langflow.services.tracing.langfuse._get_or_create_shared_client\\\") as mock_client:\\n        mock_client.return_value.auth_check.return_value = True\\n        mock_client.return_value.start_span.return_value.__enter__ = lambda s: s\\n        mock_client.return_value.start_span.return_value.__exit__ = lambda *_: None\\n        mock_client.return_value.start_span.return_value.id = \\\"root-span-id\\\"\\n        mock_client.return_value.start_span.return_value.update_trace = lambda **_: None\\n\\n        tracer = LangFuseTracer(\\n            trace_name=\\\"test-flow - abc\\\",\\n            trace_type=\\\"flow\\\",\\n            project_name=\\\"test\\\",\\n            trace_id=uuid.uuid4(),\\n        )\\n\\n    handler = tracer.get_langchain_callback()\\n    assert handler is not None, \\\"Expected a callback handler when Langfuse is configured\\\"\\n\\n    # The key assertion: deepcopy must not raise and must return the same instance.\\n    copied = copy.deepcopy(handler)\\n    assert copied is handler, \\\"deepcopy of handler should return self (no reconstruction of LangfuseResourceManager)\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/tracing/test_langfuse_v3_compatibility.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a862827e5a9bdefde491177e7eb704ad623db7797db765783bfff7ee940910f6\",\"content\":\"\\\"\\\"\\\"Tests to verify langfuse v3 API compatibility.\\n\\nThese tests verify that the LangFuseTracer implementation is compatible\\nwith the langfuse v3 SDK. The v3 SDK removed several methods that the\\nv2 API used, so we need to ensure our implementation uses the correct API.\\n\\nSee: https://langfuse.com/docs/observability/sdk/upgrade-path\\n\\\"\\\"\\\"\\n\\nimport os\\nimport sys\\nimport types\\nimport uuid\\nfrom unittest.mock import MagicMock, patch\\n\\nimport pytest\\n\\n\\n@pytest.fixture(autouse=True)\\ndef langfuse_env_vars():\\n    \\\"\\\"\\\"Set fake langfuse credentials for testing.\\\"\\\"\\\"\\n    with patch.dict(\\n        os.environ,\\n        {\\n            \\\"LANGFUSE_SECRET_KEY\\\": \\\"sk-lf-test\\\",  # pragma: allowlist secret\\n            \\\"LANGFUSE_PUBLIC_KEY\\\": \\\"pk-lf-test\\\",\\n            \\\"LANGFUSE_HOST\\\": \\\"http://localhost:3000\\\",\\n        },\\n    ):\\n        yield\\n\\n\\n@pytest.fixture(autouse=True)\\ndef reset_langfuse_shared_client():\\n    \\\"\\\"\\\"Clear the cached Langfuse client between tests so mocks don't leak.\\\"\\\"\\\"\\n    from langflow.services.tracing.langfuse import _reset_shared_client_for_tests\\n\\n    _reset_shared_client_for_tests()\\n    yield\\n    _reset_shared_client_for_tests()\\n\\n\\ndef _clear_failed_langfuse_import() -> None:\\n    \\\"\\\"\\\"Remove partially imported Langfuse modules after SDK import failures.\\\"\\\"\\\"\\n    for module_name in list(sys.modules):\\n        if module_name == \\\"langfuse\\\" or module_name.startswith(\\\"langfuse.\\\"):\\n            sys.modules.pop(module_name, None)\\n\\n\\ndef _import_langfuse_or_skip():\\n    try:\\n        from langfuse import Langfuse\\n    except Exception as exc:\\n        _clear_failed_langfuse_import()\\n        pytest.skip(f\\\"langfuse SDK is not importable: {exc}\\\")\\n    return Langfuse\\n\\n\\ndef _import_callback_handler_or_skip():\\n    try:\\n        from langfuse.langchain import CallbackHandler\\n    except Exception as exc:\\n        _clear_failed_langfuse_import()\\n        pytest.skip(f\\\"langfuse LangChain callback handler is not importable: {exc}\\\")\\n    return CallbackHandler\\n\\n\\nclass _FakeLangchainCallbackHandler:\\n    \\\"\\\"\\\"Real (subclassable) stand-in for langfuse's ``CallbackHandler`` base.\\n\\n    ``get_langchain_callback`` now subclasses the imported ``CallbackHandler`` to\\n    re-parent root LLM runs, so tests must patch the import with an actual class\\n    (a bare ``MagicMock`` instance cannot be used as a base class). This mirrors\\n    the relevant part of the real constructor signature.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, *, public_key=None, update_trace=False, trace_context=None):\\n        self.run_inline = True\\n        self.public_key = public_key\\n        self.update_trace = update_trace\\n        self.trace_context = trace_context\\n\\n    def on_chat_model_start(self, *args, **kwargs):  # noqa: ARG002\\n        return None\\n\\n    def on_llm_start(self, *args, **kwargs):  # noqa: ARG002\\n        return None\\n\\n\\nclass TestLangfuseV3ApiExists:\\n    \\\"\\\"\\\"Verify that the langfuse v3 API methods we need actually exist.\\\"\\\"\\\"\\n\\n    def test_langfuse_client_has_start_span(self):\\n        \\\"\\\"\\\"Verify start_span method exists (v3 API).\\\"\\\"\\\"\\n        langfuse_class = _import_langfuse_or_skip()\\n\\n        assert hasattr(langfuse_class, \\\"start_span\\\"), \\\"Langfuse.start_span() should exist in v3\\\"\\n\\n    def test_langfuse_client_has_start_as_current_span(self):\\n        \\\"\\\"\\\"Verify start_as_current_span method exists (v3 API).\\\"\\\"\\\"\\n        langfuse_class = _import_langfuse_or_skip()\\n\\n        assert hasattr(langfuse_class, \\\"start_as_current_span\\\"), \\\"Langfuse.start_as_current_span() should exist in v3\\\"\\n\\n    def test_langfuse_client_has_create_trace_id(self):\\n        \\\"\\\"\\\"Verify create_trace_id method exists (v3 API).\\\"\\\"\\\"\\n        langfuse_class = _import_langfuse_or_skip()\\n\\n        assert hasattr(langfuse_class, \\\"create_trace_id\\\"), \\\"Langfuse.create_trace_id() should exist in v3\\\"\\n\\n    def test_langfuse_client_does_not_have_trace(self):\\n        \\\"\\\"\\\"Verify trace() method was removed in v3.\\\"\\\"\\\"\\n        langfuse_class = _import_langfuse_or_skip()\\n\\n        # This test documents that trace() no longer exists\\n        # If this fails, langfuse may have restored backward compatibility\\n        assert not hasattr(langfuse_class, \\\"trace\\\"), \\\"Langfuse.trace() should NOT exist in v3 (removed)\\\"\\n\\n    def test_callback_handler_import_path(self):\\n        \\\"\\\"\\\"Verify the v3 callback handler import path works.\\\"\\\"\\\"\\n        # v3 path\\n        callback_handler = _import_callback_handler_or_skip()\\n\\n        assert callback_handler is not None\\n\\n\\nclass TestLangfuseTracerV3Compatibility:\\n    \\\"\\\"\\\"Test that LangFuseTracer works with langfuse v3 API.\\\"\\\"\\\"\\n\\n    def test_tracer_initialization_does_not_crash(self):\\n        \\\"\\\"\\\"Tracer should initialize without crashing (may not be ready without server).\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n        # Should not raise an exception\\n        tracer = LangFuseTracer(\\n            trace_name=\\\"test-flow - test-id\\\",\\n            trace_type=\\\"chain\\\",\\n            project_name=\\\"test-project\\\",\\n            trace_id=uuid.uuid4(),\\n            user_id=\\\"test-user\\\",\\n            session_id=\\\"test-session\\\",\\n        )\\n        # Tracer won't be ready without a server, but shouldn't crash\\n        assert isinstance(tracer.ready, bool)\\n\\n\\nclass TestLangfuseTracerFunctionality:\\n    \\\"\\\"\\\"Test LangFuseTracer functionality with mocked langfuse client.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def mock_langfuse(self):\\n        \\\"\\\"\\\"Create a mock langfuse client that simulates v3 API.\\\"\\\"\\\"\\n\\n        class TraceContext(dict):\\n            pass\\n\\n        mock_langfuse_module = types.ModuleType(\\\"langfuse\\\")\\n        mock_langfuse_types_module = types.ModuleType(\\\"langfuse.types\\\")\\n        mock_langfuse_langchain_module = types.ModuleType(\\\"langfuse.langchain\\\")\\n\\n        mock_langfuse_class = MagicMock()\\n        mock_langfuse_types_module.TraceContext = TraceContext\\n        mock_langfuse_langchain_module.CallbackHandler = MagicMock()\\n        mock_langfuse_module.Langfuse = mock_langfuse_class\\n        mock_langfuse_module.types = mock_langfuse_types_module\\n        mock_langfuse_module.langchain = mock_langfuse_langchain_module\\n\\n        with patch.dict(\\n            sys.modules,\\n            {\\n                \\\"langfuse\\\": mock_langfuse_module,\\n                \\\"langfuse.types\\\": mock_langfuse_types_module,\\n                \\\"langfuse.langchain\\\": mock_langfuse_langchain_module,\\n            },\\n        ):\\n            mock_client = MagicMock()\\n            mock_langfuse_class.return_value = mock_client\\n            mock_langfuse_class.create_trace_id = MagicMock(return_value=\\\"a\\\" * 32)\\n\\n            # Mock health check (auth_check in v3)\\n            mock_client.auth_check.return_value = True\\n\\n            # V3 API mocks\\n            mock_root_span = MagicMock()\\n            mock_root_span.id = \\\"root-span-id\\\"\\n            mock_client.start_span.return_value = mock_root_span\\n\\n            mock_child_span = MagicMock()\\n            mock_child_span.id = \\\"child-span-id\\\"\\n            mock_root_span.start_span.return_value = mock_child_span\\n\\n            yield {\\n                \\\"client\\\": mock_client,\\n                \\\"root_span\\\": mock_root_span,\\n                \\\"child_span\\\": mock_child_span,\\n            }\\n\\n    def test_tracer_uses_v3_api_for_initialization(self, mock_langfuse):\\n        \\\"\\\"\\\"Verify tracer uses start_span instead of removed trace() method.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n        tracer = LangFuseTracer(\\n            trace_name=\\\"test-flow - flow-123\\\",\\n            trace_type=\\\"chain\\\",\\n            project_name=\\\"test-project\\\",\\n            trace_id=uuid.uuid4(),\\n            user_id=\\\"user-1\\\",\\n            session_id=\\\"session-1\\\",\\n        )\\n\\n        assert tracer.ready\\n        # Should use v3 start_span, not v2 trace()\\n        mock_langfuse[\\\"client\\\"].start_span.assert_called_once()\\n        # Should set trace metadata via update_trace\\n        mock_langfuse[\\\"root_span\\\"].update_trace.assert_called()\\n\\n    def test_trace_user_id_uses_auth_user_when_no_tracing_override(self, mock_langfuse):\\n        \\\"\\\"\\\"``trace.userId`` should be the authenticated Langflow user (pre-#9505 behavior).\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n        LangFuseTracer(\\n            trace_name=\\\"test-flow - flow-123\\\",\\n            trace_type=\\\"chain\\\",\\n            project_name=\\\"test-project\\\",\\n            trace_id=uuid.uuid4(),\\n            user_id=\\\"auth-user\\\",\\n            session_id=\\\"session-1\\\",\\n        )\\n\\n        update_kwargs = mock_langfuse[\\\"root_span\\\"].update_trace.call_args.kwargs\\n        assert update_kwargs[\\\"user_id\\\"] == \\\"auth-user\\\"\\n        # No override \u2192 only the flow id is stamped; nothing recorded for the override.\\n        assert update_kwargs[\\\"metadata\\\"] == {\\\"flow_id\\\": \\\"flow-123\\\"}\\n\\n    def test_trace_user_id_stays_auth_user_and_override_goes_to_metadata(self, mock_langfuse):\\n        \\\"\\\"\\\"``tracing_user_id`` must not redefine ``trace.userId``; it is stamped in metadata.\\n\\n        Regression for GitHub issue #9505 / PR #13266 review: external Langfuse\\n        consumers depend on ``trace.userId`` continuing to mean the authenticated\\n        Langflow user. The caller-supplied override surfaces as\\n        ``metadata.langflow.tracing_user_id`` instead.\\n        \\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n        LangFuseTracer(\\n            trace_name=\\\"test-flow - flow-123\\\",\\n            trace_type=\\\"chain\\\",\\n            project_name=\\\"test-project\\\",\\n            trace_id=uuid.uuid4(),\\n            user_id=\\\"auth-user\\\",\\n            session_id=\\\"session-1\\\",\\n            tracing_user_id=\\\"end-user-456\\\",\\n        )\\n\\n        update_kwargs = mock_langfuse[\\\"root_span\\\"].update_trace.call_args.kwargs\\n        assert update_kwargs[\\\"user_id\\\"] == \\\"auth-user\\\"\\n        assert update_kwargs[\\\"metadata\\\"] == {\\\"flow_id\\\": \\\"flow-123\\\", \\\"langflow.tracing_user_id\\\": \\\"end-user-456\\\"}\\n\\n    def test_tracing_user_id_equal_to_auth_user_is_not_stamped(self, mock_langfuse):\\n        \\\"\\\"\\\"When the override matches the auth user there is nothing extra to record.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n        LangFuseTracer(\\n            trace_name=\\\"test-flow - flow-123\\\",\\n            trace_type=\\\"chain\\\",\\n            project_name=\\\"test-project\\\",\\n            trace_id=uuid.uuid4(),\\n            user_id=\\\"same-user\\\",\\n            session_id=\\\"session-1\\\",\\n            tracing_user_id=\\\"same-user\\\",\\n        )\\n\\n        update_kwargs = mock_langfuse[\\\"root_span\\\"].update_trace.call_args.kwargs\\n        assert update_kwargs[\\\"user_id\\\"] == \\\"same-user\\\"\\n        assert update_kwargs[\\\"metadata\\\"] == {\\\"flow_id\\\": \\\"flow-123\\\"}\\n\\n    def test_add_trace_creates_child_span(self, mock_langfuse):\\n        \\\"\\\"\\\"Test that add_trace creates a child span using v3 API.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n        tracer = LangFuseTracer(\\n            trace_name=\\\"test-flow - flow-123\\\",\\n            trace_type=\\\"chain\\\",\\n            project_name=\\\"test-project\\\",\\n            trace_id=uuid.uuid4(),\\n        )\\n\\n        tracer.add_trace(\\n            trace_id=\\\"component-1\\\",\\n            trace_name=\\\"TestComponent (component-1)\\\",\\n            trace_type=\\\"llm\\\",\\n            inputs={\\\"prompt\\\": \\\"test\\\"},\\n            metadata={\\\"key\\\": \\\"value\\\"},\\n        )\\n\\n        # Should create child span under root span\\n        mock_langfuse[\\\"root_span\\\"].start_span.assert_called_once()\\n        call_kwargs = mock_langfuse[\\\"root_span\\\"].start_span.call_args[1]\\n        assert call_kwargs[\\\"name\\\"] == \\\"TestComponent\\\"\\n\\n    def test_end_trace_updates_and_ends_span(self, mock_langfuse):\\n        \\\"\\\"\\\"Test that end_trace updates span with output and ends it.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n        tracer = LangFuseTracer(\\n            trace_name=\\\"test-flow - flow-123\\\",\\n            trace_type=\\\"chain\\\",\\n            project_name=\\\"test-project\\\",\\n            trace_id=uuid.uuid4(),\\n        )\\n\\n        # Add then end a trace\\n        tracer.add_trace(\\\"comp-1\\\", \\\"Test (comp-1)\\\", \\\"llm\\\", {\\\"input\\\": \\\"test\\\"})\\n        tracer.end_trace(\\\"comp-1\\\", \\\"Test\\\", outputs={\\\"output\\\": \\\"result\\\"})\\n\\n        # Should update and end the child span\\n        mock_langfuse[\\\"child_span\\\"].update.assert_called()\\n        mock_langfuse[\\\"child_span\\\"].end.assert_called()\\n\\n    def test_end_exposes_stable_evaluator_trace_input_and_output(self, mock_langfuse):\\n        \\\"\\\"\\\"Trace input/output should expose stable JSONPath keys with the flow boundary messages.\\\"\\\"\\\"\\n        from langflow.serialization.serialization import serialize\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n        from lfx.schema.message import Message\\n\\n        tracer = LangFuseTracer(\\n            trace_name=\\\"test-flow - flow-123\\\",\\n            trace_type=\\\"chain\\\",\\n            project_name=\\\"test-project\\\",\\n            trace_id=uuid.uuid4(),\\n        )\\n\\n        component_inputs = {\\n            \\\"Config (config-id)\\\": {\\\"model\\\": \\\"test-model\\\"},\\n            \\\"Chat Input (chat-input-id)\\\": {\\\"input_value\\\": \\\"What is Langflow?\\\", \\\"sender\\\": \\\"User\\\"},\\n            \\\"Prompt (prompt-id)\\\": {\\\"template\\\": \\\"Answer the user\\\"},\\n        }\\n        component_outputs = {\\n            \\\"Chat Input (chat-input-id)\\\": {\\\"message\\\": Message(text=\\\"What is Langflow?\\\")},\\n            \\\"Agent (agent-id)\\\": {\\\"response\\\": Message(text=\\\"An intermediate response\\\")},\\n            \\\"Chat Output (chat-output-id)\\\": {\\\"message\\\": Message(text=\\\"Langflow is a visual workflow builder.\\\")},\\n            \\\"Audit Sink (audit-id)\\\": {\\\"record\\\": {\\\"status\\\": \\\"stored\\\"}},\\n        }\\n        tracer.add_trace(\\n            trace_id=\\\"chat-input-id\\\",\\n            trace_name=\\\"Chat Input (chat-input-id)\\\",\\n            trace_type=\\\"chain\\\",\\n            inputs=component_inputs[\\\"Chat Input (chat-input-id)\\\"],\\n            vertex=MagicMock(is_input=True, is_output=False),\\n        )\\n        tracer.add_trace(\\n            trace_id=\\\"chat-output-id\\\",\\n            trace_name=\\\"Chat Output (chat-output-id)\\\",\\n            trace_type=\\\"chain\\\",\\n            inputs={\\\"input_value\\\": \\\"Langflow is a visual workflow builder.\\\"},\\n            vertex=MagicMock(is_input=False, is_output=True),\\n        )\\n        tracer.end(\\n            inputs=component_inputs,\\n            outputs=component_outputs,\\n            metadata={\\\"final\\\": True},\\n        )\\n\\n        root_update = mock_langfuse[\\\"root_span\\\"].update.call_args.kwargs\\n        assert root_update[\\\"input\\\"] == serialize(component_inputs)\\n        assert root_update[\\\"output\\\"] == serialize(component_outputs)\\n\\n        trace_update = mock_langfuse[\\\"root_span\\\"].update_trace.call_args.kwargs\\n        assert trace_update[\\\"input\\\"] == {\\\"input\\\": \\\"What is Langflow?\\\"}\\n        assert trace_update[\\\"output\\\"] == {\\\"output\\\": \\\"Langflow is a visual workflow builder.\\\"}\\n        assert trace_update[\\\"metadata\\\"] == {\\\"final\\\": True}\\n        mock_langfuse[\\\"root_span\\\"].end.assert_called_once()\\n\\n    def test_end_exposes_stable_trace_io_for_marked_arbitrary_graphs(self, mock_langfuse):\\n        \\\"\\\"\\\"Marked non-chat boundaries should expose their structured input and output values.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n        tracer = LangFuseTracer(\\n            trace_name=\\\"test-flow - flow-123\\\",\\n            trace_type=\\\"chain\\\",\\n            project_name=\\\"test-project\\\",\\n            trace_id=uuid.uuid4(),\\n        )\\n\\n        component_inputs = {\\n            \\\"Webhook (webhook-id)\\\": {\\\"payload\\\": {\\\"order_id\\\": 42}, \\\"method\\\": \\\"POST\\\"},\\n            \\\"Transform (transform-id)\\\": {\\\"mapping\\\": \\\"order\\\"},\\n        }\\n        component_outputs = {\\n            \\\"Webhook (webhook-id)\\\": {},\\n            \\\"Transform (transform-id)\\\": {\\\"record\\\": {\\\"order_id\\\": 42, \\\"status\\\": \\\"ready\\\"}},\\n            \\\"Data Output (data-output-id)\\\": {\\\"data\\\": [{\\\"order_id\\\": 42, \\\"status\\\": \\\"ready\\\"}]},\\n        }\\n        tracer.add_trace(\\n            trace_id=\\\"webhook-id\\\",\\n            trace_name=\\\"Webhook (webhook-id)\\\",\\n            trace_type=\\\"chain\\\",\\n            inputs=component_inputs[\\\"Webhook (webhook-id)\\\"],\\n            vertex=MagicMock(is_input=True, is_output=False),\\n        )\\n        tracer.add_trace(\\n            trace_id=\\\"data-output-id\\\",\\n            trace_name=\\\"Data Output (data-output-id)\\\",\\n            trace_type=\\\"chain\\\",\\n            inputs={},\\n            vertex=MagicMock(is_input=False, is_output=True),\\n        )\\n        tracer.end(inputs=component_inputs, outputs=component_outputs)\\n\\n        trace_update = mock_langfuse[\\\"root_span\\\"].update_trace.call_args.kwargs\\n        assert trace_update[\\\"input\\\"] == {\\\"input\\\": component_inputs[\\\"Webhook (webhook-id)\\\"]}\\n        assert trace_update[\\\"output\\\"] == {\\\"output\\\": [{\\\"order_id\\\": 42, \\\"status\\\": \\\"ready\\\"}]}\\n\\n    def test_end_falls_back_to_stable_aggregate_when_boundaries_are_unmarked(self, mock_langfuse):\\n        \\\"\\\"\\\"Custom graphs without boundary markers should retain their complete structured aggregates.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n        tracer = LangFuseTracer(\\n            trace_name=\\\"test-flow - flow-123\\\",\\n            trace_type=\\\"chain\\\",\\n            project_name=\\\"test-project\\\",\\n            trace_id=uuid.uuid4(),\\n        )\\n        component_inputs = {\\\"Custom Source (source-id)\\\": {\\\"payload\\\": {\\\"order_id\\\": 42}}}\\n        component_outputs = {\\\"Custom Sink (sink-id)\\\": {\\\"record\\\": {\\\"order_id\\\": 42, \\\"status\\\": \\\"ready\\\"}}}\\n\\n        tracer.end(inputs=component_inputs, outputs=component_outputs)\\n\\n        trace_update = mock_langfuse[\\\"root_span\\\"].update_trace.call_args.kwargs\\n        assert trace_update[\\\"input\\\"] == {\\\"input\\\": component_inputs}\\n        assert trace_update[\\\"output\\\"] == {\\\"output\\\": component_outputs}\\n\\n    def test_end_orders_multiple_boundary_outputs_by_component_id(self, mock_langfuse):\\n        \\\"\\\"\\\"Multiple graph outputs should be deterministic even when their completion order is not.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n        from lfx.schema.message import Message\\n\\n        tracer = LangFuseTracer(\\n            trace_name=\\\"test-flow - flow-123\\\",\\n            trace_type=\\\"chain\\\",\\n            project_name=\\\"test-project\\\",\\n            trace_id=uuid.uuid4(),\\n        )\\n        component_outputs = {\\n            \\\"Data Output (z-output-id)\\\": {\\\"data\\\": {\\\"order_id\\\": 42}},\\n            \\\"Text Output (a-output-id)\\\": {\\\"text\\\": Message(text=\\\"ready\\\")},\\n        }\\n        tracer.add_trace(\\n            trace_id=\\\"z-output-id\\\",\\n            trace_name=\\\"Data Output (z-output-id)\\\",\\n            trace_type=\\\"chain\\\",\\n            inputs={},\\n            vertex=MagicMock(is_input=False, is_output=True),\\n        )\\n        tracer.add_trace(\\n            trace_id=\\\"a-output-id\\\",\\n            trace_name=\\\"Text Output (a-output-id)\\\",\\n            trace_type=\\\"chain\\\",\\n            inputs={},\\n            vertex=MagicMock(is_input=False, is_output=True),\\n        )\\n\\n        tracer.end(inputs={}, outputs=component_outputs)\\n\\n        trace_update = mock_langfuse[\\\"root_span\\\"].update_trace.call_args.kwargs\\n        assert trace_update[\\\"output\\\"] == {\\\"output\\\": [\\\"ready\\\", {\\\"order_id\\\": 42}]}\\n\\n    def test_end_uses_component_input_for_dual_role_boundary(self, mock_langfuse):\\n        \\\"\\\"\\\"A component marked as both input and output should preserve the original request.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n        from lfx.schema.message import Message\\n\\n        tracer = LangFuseTracer(\\n            trace_name=\\\"test-flow - flow-123\\\",\\n            trace_type=\\\"chain\\\",\\n            project_name=\\\"test-project\\\",\\n            trace_id=uuid.uuid4(),\\n        )\\n        trace_name = \\\"Bidirectional (component-id)\\\"\\n        tracer.add_trace(\\n            trace_id=\\\"component-id\\\",\\n            trace_name=trace_name,\\n            trace_type=\\\"chain\\\",\\n            inputs={\\\"request\\\": \\\"ping\\\"},\\n            vertex=MagicMock(is_input=True, is_output=True),\\n        )\\n\\n        tracer.end(\\n            inputs={trace_name: {\\\"request\\\": \\\"ping\\\"}},\\n            outputs={trace_name: {\\\"response\\\": Message(text=\\\"pong\\\")}},\\n        )\\n\\n        trace_update = mock_langfuse[\\\"root_span\\\"].update_trace.call_args.kwargs\\n        assert trace_update[\\\"input\\\"] == {\\\"input\\\": \\\"ping\\\"}\\n        assert trace_update[\\\"output\\\"] == {\\\"output\\\": \\\"pong\\\"}\\n\\n    def test_end_normalizes_messages_nested_in_multi_output_boundary(self, mock_langfuse):\\n        \\\"\\\"\\\"Message values should become evaluator-ready text without dropping sibling outputs.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n        from lfx.schema.message import Message\\n\\n        tracer = LangFuseTracer(\\n            trace_name=\\\"test-flow - flow-123\\\",\\n            trace_type=\\\"chain\\\",\\n            project_name=\\\"test-project\\\",\\n            trace_id=uuid.uuid4(),\\n        )\\n        trace_name = \\\"Composite Output (output-id)\\\"\\n        tracer.add_trace(\\n            trace_id=\\\"output-id\\\",\\n            trace_name=trace_name,\\n            trace_type=\\\"chain\\\",\\n            inputs={},\\n            vertex=MagicMock(is_input=False, is_output=True),\\n        )\\n\\n        tracer.end(\\n            inputs={},\\n            outputs={trace_name: {\\\"message\\\": Message(text=\\\"ready\\\"), \\\"usage\\\": {\\\"tokens\\\": 3}}},\\n        )\\n\\n        trace_update = mock_langfuse[\\\"root_span\\\"].update_trace.call_args.kwargs\\n        assert trace_update[\\\"output\\\"] == {\\\"output\\\": {\\\"message\\\": \\\"ready\\\", \\\"usage\\\": {\\\"tokens\\\": 3}}}\\n\\n    def test_get_langchain_callback_uses_trace_context(self, mock_langfuse):\\n        \\\"\\\"\\\"Test that get_langchain_callback creates handler with trace context.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n        tracer = LangFuseTracer(\\n            trace_name=\\\"test-flow - flow-123\\\",\\n            trace_type=\\\"chain\\\",\\n            project_name=\\\"test-project\\\",\\n            trace_id=uuid.uuid4(),\\n        )\\n\\n        # Add a span first (uses mock_langfuse fixture)\\n        tracer.add_trace(\\\"comp-1\\\", \\\"Test\\\", \\\"llm\\\", {})\\n        assert mock_langfuse[\\\"root_span\\\"].start_span.called\\n\\n        with patch(\\\"langfuse.langchain.CallbackHandler\\\", _FakeLangchainCallbackHandler):\\n            handler = tracer.get_langchain_callback()\\n\\n        assert handler is not None\\n        assert isinstance(handler, _FakeLangchainCallbackHandler)\\n        assert \\\"trace_id\\\" in handler.trace_context\\n\\n    def test_get_langchain_callback_includes_parent_span_id(self, mock_langfuse):\\n        \\\"\\\"\\\"Test that callback handler gets parent span ID for proper nesting.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n        tracer = LangFuseTracer(\\n            trace_name=\\\"test-flow - flow-123\\\",\\n            trace_type=\\\"chain\\\",\\n            project_name=\\\"test-project\\\",\\n            trace_id=uuid.uuid4(),\\n        )\\n\\n        # Add a span to be used as parent (uses mock_langfuse fixture)\\n        tracer.add_trace(\\\"comp-1\\\", \\\"Test\\\", \\\"llm\\\", {})\\n        assert mock_langfuse[\\\"child_span\\\"].id == \\\"child-span-id\\\"\\n\\n        with patch(\\\"langfuse.langchain.CallbackHandler\\\", _FakeLangchainCallbackHandler):\\n            handler = tracer.get_langchain_callback()\\n\\n        assert handler.trace_context[\\\"parent_span_id\\\"] == \\\"child-span-id\\\"\\n\\n\\nclass TestLangfuseClientSingleton:\\n    \\\"\\\"\\\"Verify the Langfuse client is constructed once and reused across flow runs.\\n\\n    Regression test for https://github.com/langflow-ai/langflow/issues/9066.\\n    \\\"\\\"\\\"\\n\\n    def test_single_client_for_multiple_flow_runs(self):\\n        \\\"\\\"\\\"A single Langfuse() client must be reused across all flow runs.\\n\\n        Background threads (task_manager, prompt_cache, OTel exporters) are\\n        spawned per client and never joined, so a per-run client leaks threads.\\n        \\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n        n_runs = 5\\n\\n        with patch(\\\"langfuse.Langfuse\\\") as mock_langfuse_class:\\n            mock_langfuse_class.create_trace_id = MagicMock(return_value=\\\"a\\\" * 32)\\n            mock_client = MagicMock()\\n            mock_client.auth_check.return_value = True\\n            mock_langfuse_class.return_value = mock_client\\n\\n            for _ in range(n_runs):\\n                LangFuseTracer(\\n                    trace_name=\\\"test-flow - flow-id\\\",\\n                    trace_type=\\\"chain\\\",\\n                    project_name=\\\"test-project\\\",\\n                    trace_id=uuid.uuid4(),\\n                )\\n\\n            # After fix: Langfuse() must be instantiated exactly once,\\n            # regardless of how many flows run.\\n            assert mock_langfuse_class.call_count == 1\\n\\n    def test_end_calls_client_flush(self):\\n        \\\"\\\"\\\"end() must flush buffered events so they're sent before the trace finishes.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n        with patch(\\\"langfuse.Langfuse\\\") as mock_langfuse_class:\\n            mock_langfuse_class.create_trace_id = MagicMock(return_value=\\\"a\\\" * 32)\\n            mock_client = MagicMock()\\n            mock_client.auth_check.return_value = True\\n            mock_root_span = MagicMock()\\n            mock_client.start_span.return_value = mock_root_span\\n            mock_langfuse_class.return_value = mock_client\\n\\n            tracer = LangFuseTracer(\\n                trace_name=\\\"test-flow - flow-id\\\",\\n                trace_type=\\\"chain\\\",\\n                project_name=\\\"test-project\\\",\\n                trace_id=uuid.uuid4(),\\n            )\\n            tracer.end(inputs={\\\"a\\\": 1}, outputs={\\\"b\\\": 2})\\n\\n            mock_client.flush.assert_called_once()\\n\\n    def test_end_swallows_flush_errors(self):\\n        \\\"\\\"\\\"A failing flush() must not break flow end.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n        with patch(\\\"langfuse.Langfuse\\\") as mock_langfuse_class:\\n            mock_langfuse_class.create_trace_id = MagicMock(return_value=\\\"a\\\" * 32)\\n            mock_client = MagicMock()\\n            mock_client.auth_check.return_value = True\\n            mock_client.flush.side_effect = RuntimeError(\\\"upstream down\\\")\\n            mock_root_span = MagicMock()\\n            mock_client.start_span.return_value = mock_root_span\\n            mock_langfuse_class.return_value = mock_client\\n\\n            tracer = LangFuseTracer(\\n                trace_name=\\\"test-flow - flow-id\\\",\\n                trace_type=\\\"chain\\\",\\n                project_name=\\\"test-project\\\",\\n                trace_id=uuid.uuid4(),\\n            )\\n            # Should not raise even though flush() blew up.\\n            tracer.end(inputs={\\\"a\\\": 1}, outputs={\\\"b\\\": 2})\\n\\n            mock_client.flush.assert_called_once()\\n\\n    def test_feedback_helper_reuses_shared_client(self):\\n        \\\"\\\"\\\"`_get_langfuse_client()` (used by feedback scoring) must reuse the singleton.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import _get_langfuse_client\\n\\n        with patch(\\\"langfuse.Langfuse\\\") as mock_langfuse_class:\\n            mock_client = MagicMock()\\n            mock_langfuse_class.return_value = mock_client\\n\\n            client_a = _get_langfuse_client()\\n            client_b = _get_langfuse_client()\\n\\n            assert client_a is client_b\\n            assert mock_langfuse_class.call_count == 1\\n\\n    def test_credential_change_creates_new_client(self):\\n        \\\"\\\"\\\"Rotating credentials should produce a fresh client, not reuse the stale one.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import _get_langfuse_client\\n\\n        with patch(\\\"langfuse.Langfuse\\\") as mock_langfuse_class:\\n            mock_langfuse_class.return_value = MagicMock()\\n\\n            _get_langfuse_client()\\n            assert mock_langfuse_class.call_count == 1\\n\\n            # Rotate credentials and call again.\\n            with patch.dict(\\n                os.environ,\\n                {\\n                    \\\"LANGFUSE_SECRET_KEY\\\": \\\"sk-lf-rotated\\\",  # pragma: allowlist secret\\n                    \\\"LANGFUSE_PUBLIC_KEY\\\": \\\"pk-lf-rotated\\\",\\n                    \\\"LANGFUSE_HOST\\\": \\\"http://localhost:3000\\\",\\n                },\\n            ):\\n                _get_langfuse_client()\\n\\n            assert mock_langfuse_class.call_count == 2\\n\\n\\nclass TestLangfuseIsolatedTracerProvider:\\n    \\\"\\\"\\\"Verify Langfuse is initialized with an isolated OTel ``TracerProvider``.\\n\\n    Regression test for https://github.com/langflow-ai/langflow/issues/13319.\\n\\n    Without an explicit ``tracer_provider``, the Langfuse v3 SDK registers\\n    itself as the global OTel tracer provider. Because ``langflow.main`` calls\\n    ``FastAPIInstrumentor.instrument_app(app)`` (which uses the global\\n    provider), every FastAPI HTTP request span would then be exported to\\n    Langfuse \u2014 flooding traces with health checks, flow list calls, and other\\n    unrelated routes. Passing an isolated provider keeps Langfuse spans\\n    private to the langfuse client.\\n    \\\"\\\"\\\"\\n\\n    def test_shared_client_uses_isolated_tracer_provider(self):\\n        \\\"\\\"\\\"``Langfuse(...)`` must receive an explicit, non-global ``TracerProvider``.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import _get_langfuse_client\\n        from opentelemetry.sdk.trace import TracerProvider\\n\\n        with patch(\\\"langfuse.Langfuse\\\") as mock_langfuse_class:\\n            mock_langfuse_class.return_value = MagicMock()\\n\\n            _get_langfuse_client()\\n\\n            mock_langfuse_class.assert_called_once()\\n            call_kwargs = mock_langfuse_class.call_args.kwargs\\n            assert \\\"tracer_provider\\\" in call_kwargs, (\\n                \\\"Langfuse() must be called with an explicit tracer_provider so it does not\\\"\\n                \\\" register itself as the global OTel tracer provider (issue #13319).\\\"\\n            )\\n            assert isinstance(call_kwargs[\\\"tracer_provider\\\"], TracerProvider)\\n\\n    def test_global_tracer_provider_is_not_replaced_by_langfuse_init(self):\\n        \\\"\\\"\\\"Initializing the Langfuse client must not swap out the global TracerProvider.\\n\\n        If Langfuse becomes the global provider, ``FastAPIInstrumentor`` will\\n        emit HTTP request spans into Langfuse, which is the symptom reported\\n        in #13319.\\n        \\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import _get_langfuse_client\\n        from opentelemetry import trace as otel_trace_api\\n\\n        before = otel_trace_api.get_tracer_provider()\\n\\n        with patch(\\\"langfuse.Langfuse\\\") as mock_langfuse_class:\\n            mock_langfuse_class.return_value = MagicMock()\\n            _get_langfuse_client()\\n\\n        after = otel_trace_api.get_tracer_provider()\\n        assert after is before, (\\n            \\\"Global OTel TracerProvider must not change when the Langfuse client is initialized (issue #13319).\\\"\\n        )\\n\\n\\nclass TestLangfuseSetupFailureVisibility:\\n    \\\"\\\"\\\"Regression for https://github.com/langflow-ai/langflow/issues/13317.\\n\\n    On Docker v1.9.3 (Python 3.14 + pydantic<2.13) langfuse fails to import\\n    with ``pydantic.v1.errors.ConfigError`` and the tracer was silently\\n    initializing with ``_ready = False`` because the broad except branch in\\n    ``_setup_langfuse`` only logged at ``debug`` level. Users saw no traces\\n    in Langfuse and no diagnostic message in logs. Setup failures must now\\n    surface at ``WARNING``/``ERROR`` level (via loguru) so the cause is\\n    visible. The module logger is loguru's ``lfx.log.logger.logger`` so we\\n    patch its methods directly rather than relying on stdlib ``caplog``.\\n    \\\"\\\"\\\"\\n\\n    def test_auth_check_failure_logs_warning(self):\\n        \\\"\\\"\\\"A failed auth_check must log a WARNING so users see the problem.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n        with (\\n            patch(\\\"langfuse.Langfuse\\\") as mock_langfuse_class,\\n            patch(\\\"langflow.services.tracing.langfuse.logger\\\") as mock_logger,\\n        ):\\n            mock_langfuse_class.create_trace_id = MagicMock(return_value=\\\"a\\\" * 32)\\n            mock_client = MagicMock()\\n            mock_client.auth_check.return_value = False\\n            mock_langfuse_class.return_value = mock_client\\n\\n            tracer = LangFuseTracer(\\n                trace_name=\\\"test - flow-1\\\",\\n                trace_type=\\\"chain\\\",\\n                project_name=\\\"proj\\\",\\n                trace_id=uuid.uuid4(),\\n            )\\n\\n            assert tracer.ready is False\\n            mock_logger.warning.assert_called_once()\\n            warning_msg = mock_logger.warning.call_args.args[0].lower()\\n            assert \\\"authentication failed\\\" in warning_msg\\n\\n    def test_auth_check_exception_logs_warning(self):\\n        \\\"\\\"\\\"A connection error during auth_check must log a WARNING, not debug.\\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n        with (\\n            patch(\\\"langfuse.Langfuse\\\") as mock_langfuse_class,\\n            patch(\\\"langflow.services.tracing.langfuse.logger\\\") as mock_logger,\\n        ):\\n            mock_langfuse_class.create_trace_id = MagicMock(return_value=\\\"a\\\" * 32)\\n            mock_client = MagicMock()\\n            mock_client.auth_check.side_effect = ConnectionError(\\\"upstream unreachable\\\")\\n            mock_langfuse_class.return_value = mock_client\\n\\n            tracer = LangFuseTracer(\\n                trace_name=\\\"test - flow-1\\\",\\n                trace_type=\\\"chain\\\",\\n                project_name=\\\"proj\\\",\\n                trace_id=uuid.uuid4(),\\n            )\\n\\n            assert tracer.ready is False\\n            mock_logger.warning.assert_called_once()\\n            warning_msg = mock_logger.warning.call_args.args[0].lower()\\n            assert \\\"cannot connect to langfuse\\\" in warning_msg\\n\\n    def test_setup_exception_logs_with_traceback(self):\\n        \\\"\\\"\\\"Unexpected setup errors must call logger.exception so users see the cause.\\n\\n        Simulates the production failure mode: langfuse import succeeds (mocked)\\n        but ``start_span`` raises something other than ``ImportError`` \u2014 exactly\\n        the shape ``pydantic.v1.errors.ConfigError`` takes on Python 3.14 with\\n        pydantic<2.13, just raised later in the path. The previous ``debug``\\n        log meant users got no signal at all.\\n        \\\"\\\"\\\"\\n        from langflow.services.tracing.langfuse import LangFuseTracer\\n\\n        with (\\n            patch(\\\"langfuse.Langfuse\\\") as mock_langfuse_class,\\n            patch(\\\"langflow.services.tracing.langfuse.logger\\\") as mock_logger,\\n        ):\\n            mock_langfuse_class.create_trace_id = MagicMock(return_value=\\\"a\\\" * 32)\\n            mock_client = MagicMock()\\n            mock_client.auth_check.return_value = True\\n            mock_client.start_span.side_effect = RuntimeError(\\\"simulated pydantic v1 config error\\\")\\n            mock_langfuse_class.return_value = mock_client\\n\\n            tracer = LangFuseTracer(\\n                trace_name=\\\"test - flow-1\\\",\\n                trace_type=\\\"chain\\\",\\n                project_name=\\\"proj\\\",\\n                trace_id=uuid.uuid4(),\\n            )\\n\\n            assert tracer.ready is False\\n            mock_logger.exception.assert_called_once()\\n            err_msg = mock_logger.exception.call_args.args[0].lower()\\n            assert \\\"error setting up langfuse tracer\\\" in err_msg\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/tracing/test_langwatch.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2d58c275e5345490935b1b638e551789287b1baa51d7bb5119464065bc122e58\",\"content\":\"\\\"\\\"\\\"Unit tests for the LangWatch tracer's handling of a missing ``langwatch`` package.\\n\\n``langwatch`` is an optional dependency that caps ``requires-python`` at ``<3.14`` upstream,\\nso it is excluded from Python 3.14+ environments such as the official Langflow Docker images.\\nWhen ``LANGWATCH_API_KEY`` is set but the package cannot be imported, the tracer must disable\\nitself gracefully and emit a single actionable warning instead of failing silently.\\n\\\"\\\"\\\"\\n\\nimport sys\\nimport uuid\\nfrom unittest.mock import patch\\n\\nimport pytest\\nfrom langflow.services.tracing import langwatch as langwatch_module\\nfrom langflow.services.tracing.langwatch import LangWatchTracer\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _reset_langwatch_state():\\n    \\\"\\\"\\\"Reset the shared class-level state so tests don't leak into each other.\\\"\\\"\\\"\\n    original_warned = LangWatchTracer._missing_dependency_warned\\n    original_provider = LangWatchTracer.tracer_provider\\n    LangWatchTracer._missing_dependency_warned = False\\n    LangWatchTracer.tracer_provider = None\\n    yield\\n    LangWatchTracer._missing_dependency_warned = original_warned\\n    LangWatchTracer.tracer_provider = original_provider\\n\\n\\ndef _make_tracer() -> LangWatchTracer:\\n    return LangWatchTracer(\\n        trace_name=\\\"test flow - abc123\\\",\\n        trace_type=\\\"chain\\\",\\n        project_name=\\\"test\\\",\\n        trace_id=uuid.uuid4(),\\n    )\\n\\n\\ndef test_tracer_disabled_and_warns_once_when_package_missing(monkeypatch):\\n    \\\"\\\"\\\"API key set + ``langwatch`` unimportable -> tracer not ready, warn exactly once.\\n\\n    Forcing ``import langwatch`` to fail mirrors the Python 3.14 Docker images, where the\\n    package is absent. The warning must fire once even across multiple flow runs (each run\\n    constructs a fresh tracer).\\n    \\\"\\\"\\\"\\n    monkeypatch.setenv(\\\"LANGWATCH_API_KEY\\\", \\\"test-key\\\")  # pragma: allowlist secret\\n    # A ``None`` entry in ``sys.modules`` makes ``import langwatch`` raise ImportError,\\n    # even when the package is genuinely installed in the local (Python <3.14) test env.\\n    monkeypatch.setitem(sys.modules, \\\"langwatch\\\", None)\\n\\n    with patch.object(langwatch_module.logger, \\\"warning\\\") as mock_warning:\\n        tracer1 = _make_tracer()\\n        tracer2 = _make_tracer()\\n\\n    assert tracer1.ready is False\\n    assert tracer2.ready is False\\n\\n    mock_warning.assert_called_once()\\n    message = mock_warning.call_args.args[0]\\n    assert \\\"LANGWATCH_API_KEY\\\" in message\\n    assert \\\"langwatch\\\" in message\\n\\n\\ndef test_no_warning_when_api_key_not_set(monkeypatch):\\n    \\\"\\\"\\\"No API key -> tracer is a silent no-op and emits no missing-package warning.\\\"\\\"\\\"\\n    monkeypatch.delenv(\\\"LANGWATCH_API_KEY\\\", raising=False)\\n\\n    with patch.object(langwatch_module.logger, \\\"warning\\\") as mock_warning:\\n        tracer = _make_tracer()\\n\\n    assert tracer.ready is False\\n    mock_warning.assert_not_called()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/tracing/test_llm_content_not_exported_to_apm.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f385145e8769208cb824c8d95fa1849b63ccd88611ee756fd089ad7f0508b762\",\"content\":\"\\\"\\\"\\\"End-to-end check that a real LLM tracer cannot push prompt text to the operator's APM.\\n\\nTraceloop adopts an already-installed global tracer provider and appends its own span\\nprocessor to it, so once Langflow installs one for OTLP export, its gen_ai spans travel\\nthat path too. The vendor integration is deliberately left alone; the export filter is\\nwhat holds the line. Runs in a subprocess because tracer providers are process-global.\\n\\\"\\\"\\\"\\n\\nimport json\\nimport os\\nimport subprocess\\nimport sys\\n\\nSENTINEL = \\\"SENTINEL-PROMPT-TEXT-MUST-NOT-BE-EXPORTED\\\"\\n\\nPROBE = f\\\"\\\"\\\"\\nimport json\\nfrom opentelemetry import trace\\nfrom opentelemetry.sdk.trace import TracerProvider\\nfrom opentelemetry.sdk.trace.export.in_memory_span_exporter import InMemorySpanExporter\\nfrom langflow.services.telemetry.opentelemetry import (\\n    APPLICATION_TRACER_NAME,\\n    ApplicationOnlySpanProcessor,\\n)\\n\\n# Stand in for the operator's APM, wired exactly as the OTLP bootstrap wires it.\\napm_exporter = InMemorySpanExporter()\\nprovider = TracerProvider()\\nprovider.add_span_processor(ApplicationOnlySpanProcessor(apm_exporter))\\ntrace.set_tracer_provider(provider)\\n\\nfrom uuid import uuid4\\nfrom langflow.services.tracing.traceloop import TraceloopTracer\\n\\ntracer = TraceloopTracer(\\n    trace_name=\\\"probe\\\", trace_type=\\\"chain\\\", project_name=\\\"probe-project\\\", trace_id=uuid4()\\n)\\n\\n# Drive the vendor integration the way a flow does, with content in the payload.\\nif tracer.ready:\\n    tracer.add_trace(\\n        trace_id=str(uuid4()),\\n        trace_name=\\\"OpenAIModel\\\",\\n        trace_type=\\\"llm\\\",\\n        inputs={{\\\"input_value\\\": {SENTINEL!r}}},\\n    )\\n    tracer.end_trace(trace_id=list(tracer.child_spans)[0], trace_name=\\\"OpenAIModel\\\") if tracer.child_spans else None\\n\\n# An application span must still get through, so we know the filter is not simply off.\\nprovider.get_tracer(APPLICATION_TRACER_NAME).start_span(\\\"flow\\\").end()\\nprovider.force_flush()\\n\\nfinished = apm_exporter.get_finished_spans()\\nblob = json.dumps(\\n    [{{\\\"name\\\": s.name, \\\"scope\\\": s.instrumentation_scope.name, \\\"attrs\\\": dict(s.attributes or {{}})}} for s in finished],\\n    default=str,\\n)\\nprint(\\\"PROBE_RESULT \\\" + json.dumps({{\\n    \\\"ready\\\": bool(tracer.ready),\\n    \\\"exported\\\": [s.name for s in finished],\\n    \\\"leaked\\\": {SENTINEL!r} in blob,\\n}}))\\n\\\"\\\"\\\"\\n\\n\\ndef test_traceloop_content_never_reaches_the_apm_exporter():\\n    env = {k: v for k, v in os.environ.items() if not k.startswith((\\\"OTEL_\\\", \\\"TRACELOOP_\\\"))}\\n    env[\\\"TRACELOOP_API_KEY\\\"] = \\\"not-a-real-key\\\"  # pragma: allowlist secret\\n    # Traceloop's own exporter points at a closed port so nothing leaves the machine.\\n    env[\\\"TRACELOOP_BASE_URL\\\"] = \\\"http://127.0.0.1:9\\\"\\n    completed = subprocess.run(  # noqa: S603\\n        [sys.executable, \\\"-c\\\", PROBE],\\n        env=env,\\n        capture_output=True,\\n        text=True,\\n        timeout=300,\\n        check=False,\\n    )\\n    assert completed.returncode == 0, completed.stderr\\n    line = next(ln for ln in completed.stdout.splitlines() if ln.startswith(\\\"PROBE_RESULT \\\"))\\n    result = json.loads(line.removeprefix(\\\"PROBE_RESULT \\\"))\\n\\n    assert result[\\\"ready\\\"], \\\"Traceloop tracer did not initialize; the probe proves nothing\\\"\\n    assert not result[\\\"leaked\\\"], \\\"LLM content reached the APM exporter\\\"\\n    assert result[\\\"exported\\\"] == [\\\"flow\\\"], f\\\"expected only the application span, got {result['exported']}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/tracing/test_native_callback.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1282732281a613ee65087eeaa213864fece9a5b8262adc36f4ebf3c2507e0e13\",\"content\":\"\\\"\\\"\\\"Unit tests for NativeCallbackHandler.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nfrom unittest.mock import MagicMock\\nfrom uuid import UUID, uuid4\\n\\nfrom langflow.services.tracing.native_callback import NativeCallbackHandler\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _make_handler(parent_span_id: UUID | None = None) -> tuple[NativeCallbackHandler, MagicMock]:\\n    \\\"\\\"\\\"Return (handler, mock_tracer).\\\"\\\"\\\"\\n    mock_tracer = MagicMock()\\n    mock_tracer._current_component_id = None\\n    handler = NativeCallbackHandler(tracer=mock_tracer, parent_span_id=parent_span_id)\\n    return handler, mock_tracer\\n\\n\\ndef _make_llm_result(\\n    prompt_tokens: int | None = None,\\n    completion_tokens: int | None = None,\\n    total_tokens: int | None = None,\\n    *,\\n    use_llm_output: bool = False,\\n    use_usage_metadata: bool = False,\\n    use_response_metadata: bool = False,\\n    use_generation_info: bool = False,\\n) -> MagicMock:\\n    \\\"\\\"\\\"Build a mock LLMResult with configurable token sources.\\\"\\\"\\\"\\n    result = MagicMock()\\n\\n    if use_llm_output:\\n        result.llm_output = {\\n            \\\"token_usage\\\": {\\n                \\\"prompt_tokens\\\": prompt_tokens,\\n                \\\"completion_tokens\\\": completion_tokens,\\n                \\\"total_tokens\\\": total_tokens,\\n            }\\n        }\\n        result.generations = []\\n    elif use_usage_metadata:\\n        # Modern LangChain: AIMessage.usage_metadata\\n        message = MagicMock()\\n        message.usage_metadata = {\\n            \\\"input_tokens\\\": prompt_tokens,\\n            \\\"output_tokens\\\": completion_tokens,\\n            \\\"total_tokens\\\": total_tokens,\\n        }\\n        message.response_metadata = {}\\n        gen = MagicMock()\\n        gen.message = message\\n        gen.generation_info = {}\\n        result.llm_output = {}\\n        result.generations = [[gen]]\\n    elif use_response_metadata:\\n        # Provider-specific: AIMessage.response_metadata\\n        message = MagicMock()\\n        message.usage_metadata = None\\n        message.response_metadata = {\\n            \\\"token_usage\\\": {\\n                \\\"prompt_tokens\\\": prompt_tokens,\\n                \\\"completion_tokens\\\": completion_tokens,\\n                \\\"total_tokens\\\": total_tokens,\\n            }\\n        }\\n        gen = MagicMock()\\n        gen.message = message\\n        gen.generation_info = {}\\n        result.llm_output = {}\\n        result.generations = [[gen]]\\n    elif use_generation_info:\\n        # generation_info path\\n        message = MagicMock()\\n        message.usage_metadata = None\\n        message.response_metadata = {}\\n        gen = MagicMock()\\n        gen.message = message\\n        gen.generation_info = {\\n            \\\"token_usage\\\": {\\n                \\\"prompt_tokens\\\": prompt_tokens,\\n                \\\"completion_tokens\\\": completion_tokens,\\n                \\\"total_tokens\\\": total_tokens,\\n            }\\n        }\\n        result.llm_output = {}\\n        result.generations = [[gen]]\\n    else:\\n        result.llm_output = {}\\n        result.generations = []\\n\\n    return result\\n\\n\\n# ---------------------------------------------------------------------------\\n# Internal helpers\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestInternalHelpers:\\n    def test_get_span_id_creates_new_uuid_for_unknown_run(self):\\n        handler, _ = _make_handler()\\n        run_id = uuid4()\\n        span_id = handler._get_span_id(run_id)\\n        assert isinstance(span_id, UUID)\\n\\n    def test_get_span_id_returns_same_id_for_same_run(self):\\n        handler, _ = _make_handler()\\n        run_id = uuid4()\\n        id1 = handler._get_span_id(run_id)\\n        id2 = handler._get_span_id(run_id)\\n        assert id1 == id2\\n\\n    def test_get_start_time_returns_now_for_unknown_run(self):\\n        handler, _ = _make_handler()\\n        from datetime import datetime, timezone\\n\\n        before = datetime.now(timezone.utc)\\n        t = handler._get_start_time(uuid4())\\n        after = datetime.now(timezone.utc)\\n        assert before <= t <= after\\n\\n    def test_calculate_latency_returns_non_negative(self):\\n        handler, _ = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)  # registers start time\\n        latency = handler._calculate_latency(run_id)\\n        assert latency >= 0\\n\\n    def test_cleanup_run_removes_span(self):\\n        handler, _ = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n        assert run_id in handler._spans\\n        handler._cleanup_run(run_id)\\n        assert run_id not in handler._spans\\n\\n    def test_cleanup_run_noop_for_unknown_run(self):\\n        handler, _ = _make_handler()\\n        # Should not raise\\n        handler._cleanup_run(uuid4())\\n\\n\\n# ---------------------------------------------------------------------------\\n# LLM callbacks\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestOnLlmStart:\\n    def test_on_llm_start_calls_add_langchain_span(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler.on_llm_start(\\n            serialized={\\\"name\\\": \\\"ChatOpenAI\\\", \\\"id\\\": [\\\"langchain\\\", \\\"ChatOpenAI\\\"]},\\n            prompts=[\\\"Hello\\\"],\\n            run_id=run_id,\\n            invocation_params={\\\"model_name\\\": \\\"gpt-4\\\"},\\n        )\\n        mock_tracer.add_langchain_span.assert_called_once()\\n        call_kwargs = mock_tracer.add_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"span_type\\\"] == \\\"llm\\\"\\n        assert \\\"gpt-4\\\" in call_kwargs[\\\"name\\\"]\\n\\n    def test_on_llm_start_uses_parent_span_id_when_no_parent_run(self):\\n        parent_id = uuid4()\\n        handler, mock_tracer = _make_handler(parent_span_id=parent_id)\\n        run_id = uuid4()\\n        handler.on_llm_start(\\n            serialized={},\\n            prompts=[\\\"hi\\\"],\\n            run_id=run_id,\\n        )\\n        call_kwargs = mock_tracer.add_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"parent_span_id\\\"] == parent_id\\n\\n    def test_on_llm_start_uses_parent_run_id_when_provided(self):\\n        handler, mock_tracer = _make_handler()\\n        parent_run_id = uuid4()\\n        run_id = uuid4()\\n        # Register parent run first\\n        handler._get_span_id(parent_run_id)\\n        handler.on_llm_start(\\n            serialized={},\\n            prompts=[\\\"hi\\\"],\\n            run_id=run_id,\\n            parent_run_id=parent_run_id,\\n        )\\n        call_kwargs = mock_tracer.add_langchain_span.call_args[1]\\n        # parent_span_id should be the span id of the parent run\\n        assert call_kwargs[\\\"parent_span_id\\\"] == handler._spans[parent_run_id][\\\"span_id\\\"]\\n\\n    def test_on_llm_start_extracts_model_from_invocation_params(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler.on_llm_start(\\n            serialized={\\\"name\\\": \\\"OpenAI\\\"},\\n            prompts=[\\\"hi\\\"],\\n            run_id=run_id,\\n            invocation_params={\\\"model\\\": \\\"gpt-3.5-turbo\\\"},\\n        )\\n        call_kwargs = mock_tracer.add_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"model_name\\\"] == \\\"gpt-3.5-turbo\\\"\\n\\n    def test_on_llm_start_handles_empty_serialized(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler.on_llm_start(serialized={}, prompts=[\\\"hi\\\"], run_id=run_id)\\n        mock_tracer.add_langchain_span.assert_called_once()\\n\\n\\nclass TestOnChatModelStart:\\n    def test_on_chat_model_start_calls_add_langchain_span(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        msg = MagicMock()\\n        msg.type = \\\"human\\\"\\n        msg.content = \\\"hello\\\"\\n        handler.on_chat_model_start(\\n            serialized={\\\"name\\\": \\\"ChatOpenAI\\\"},\\n            messages=[[msg]],\\n            run_id=run_id,\\n            invocation_params={\\\"model_name\\\": \\\"gpt-4\\\"},\\n        )\\n        mock_tracer.add_langchain_span.assert_called_once()\\n        call_kwargs = mock_tracer.add_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"span_type\\\"] == \\\"llm\\\"\\n        assert \\\"messages\\\" in call_kwargs[\\\"inputs\\\"]\\n\\n    def test_on_chat_model_start_formats_messages(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        msg = MagicMock()\\n        msg.type = \\\"human\\\"\\n        msg.content = \\\"test message\\\"\\n        handler.on_chat_model_start(\\n            serialized={},\\n            messages=[[msg]],\\n            run_id=run_id,\\n        )\\n        call_kwargs = mock_tracer.add_langchain_span.call_args[1]\\n        formatted = call_kwargs[\\\"inputs\\\"][\\\"messages\\\"]\\n        assert formatted == [[{\\\"type\\\": \\\"human\\\", \\\"content\\\": \\\"test message\\\"}]]\\n\\n\\nclass TestOnLlmEnd:\\n    def test_on_llm_end_legacy_llm_output_tokens(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n\\n        response = _make_llm_result(\\n            prompt_tokens=10,\\n            completion_tokens=20,\\n            total_tokens=30,\\n            use_llm_output=True,\\n        )\\n        handler.on_llm_end(response, run_id=run_id)\\n\\n        mock_tracer.end_langchain_span.assert_called_once()\\n        call_kwargs = mock_tracer.end_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"prompt_tokens\\\"] == 10\\n        assert call_kwargs[\\\"completion_tokens\\\"] == 20\\n        assert call_kwargs[\\\"total_tokens\\\"] == 30\\n\\n    def test_on_llm_end_usage_metadata_tokens(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n\\n        response = _make_llm_result(\\n            prompt_tokens=5,\\n            completion_tokens=15,\\n            total_tokens=20,\\n            use_usage_metadata=True,\\n        )\\n        handler.on_llm_end(response, run_id=run_id)\\n\\n        call_kwargs = mock_tracer.end_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"total_tokens\\\"] == 20\\n\\n    def test_on_llm_end_response_metadata_tokens(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n\\n        response = _make_llm_result(\\n            prompt_tokens=8,\\n            completion_tokens=12,\\n            total_tokens=20,\\n            use_response_metadata=True,\\n        )\\n        handler.on_llm_end(response, run_id=run_id)\\n\\n        call_kwargs = mock_tracer.end_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"total_tokens\\\"] == 20\\n\\n    def test_on_llm_end_generation_info_tokens(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n\\n        response = _make_llm_result(\\n            prompt_tokens=3,\\n            completion_tokens=7,\\n            total_tokens=10,\\n            use_generation_info=True,\\n        )\\n        handler.on_llm_end(response, run_id=run_id)\\n\\n        call_kwargs = mock_tracer.end_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"total_tokens\\\"] == 10\\n\\n    def test_on_llm_end_no_tokens_when_none_available(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n\\n        response = _make_llm_result()  # no token info\\n        handler.on_llm_end(response, run_id=run_id)\\n\\n        call_kwargs = mock_tracer.end_langchain_span.call_args[1]\\n        assert call_kwargs.get(\\\"total_tokens\\\") is None\\n\\n    def test_on_llm_end_cleans_up_run(self):\\n        handler, _mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n        response = _make_llm_result()\\n        handler.on_llm_end(response, run_id=run_id)\\n        assert run_id not in handler._spans\\n\\n    def test_on_llm_end_extracts_generation_text(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n\\n        gen = MagicMock()\\n        gen.text = \\\"hello world\\\"\\n        gen.generation_info = {\\\"finish_reason\\\": \\\"stop\\\"}\\n        gen.message = None\\n\\n        response = MagicMock()\\n        response.llm_output = {}\\n        response.generations = [[gen]]\\n\\n        handler.on_llm_end(response, run_id=run_id)\\n\\n        call_kwargs = mock_tracer.end_langchain_span.call_args[1]\\n        outputs = call_kwargs[\\\"outputs\\\"]\\n        assert outputs[\\\"generations\\\"][0][0][\\\"text\\\"] == \\\"hello world\\\"\\n\\n\\nclass TestOnLlmError:\\n    def test_on_llm_error_calls_end_langchain_span_with_error(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n\\n        handler.on_llm_error(ValueError(\\\"LLM failed\\\"), run_id=run_id)\\n\\n        mock_tracer.end_langchain_span.assert_called_once()\\n        call_kwargs = mock_tracer.end_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"error\\\"] == \\\"LLM failed\\\"\\n\\n    def test_on_llm_error_cleans_up_run(self):\\n        handler, _mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n        handler.on_llm_error(RuntimeError(\\\"boom\\\"), run_id=run_id)\\n        assert run_id not in handler._spans\\n\\n\\n# ---------------------------------------------------------------------------\\n# Chain callbacks\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestChainCallbacks:\\n    def test_on_chain_start_calls_add_langchain_span(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler.on_chain_start(\\n            serialized={\\\"name\\\": \\\"LLMChain\\\"},\\n            inputs={\\\"question\\\": \\\"what?\\\"},\\n            run_id=run_id,\\n        )\\n        mock_tracer.add_langchain_span.assert_called_once()\\n        call_kwargs = mock_tracer.add_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"span_type\\\"] == \\\"chain\\\"\\n        assert call_kwargs[\\\"name\\\"] == \\\"LLMChain\\\"\\n\\n    def test_on_chain_start_uses_id_list_fallback(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler.on_chain_start(\\n            serialized={\\\"id\\\": [\\\"langchain\\\", \\\"chains\\\", \\\"MyChain\\\"]},\\n            inputs={},\\n            run_id=run_id,\\n        )\\n        call_kwargs = mock_tracer.add_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"name\\\"] == \\\"MyChain\\\"\\n\\n    def test_on_chain_end_calls_end_langchain_span(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n        handler.on_chain_end({\\\"result\\\": \\\"done\\\"}, run_id=run_id)\\n\\n        mock_tracer.end_langchain_span.assert_called_once()\\n        call_kwargs = mock_tracer.end_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"outputs\\\"] == {\\\"result\\\": \\\"done\\\"}\\n\\n    def test_on_chain_end_cleans_up_run(self):\\n        handler, _mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n        handler.on_chain_end({}, run_id=run_id)\\n        assert run_id not in handler._spans\\n\\n    def test_on_chain_error_calls_end_langchain_span_with_error(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n        handler.on_chain_error(RuntimeError(\\\"chain broke\\\"), run_id=run_id)\\n\\n        call_kwargs = mock_tracer.end_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"error\\\"] == \\\"chain broke\\\"\\n\\n    def test_on_chain_error_cleans_up_run(self):\\n        handler, _mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n        handler.on_chain_error(RuntimeError(\\\"err\\\"), run_id=run_id)\\n        assert run_id not in handler._spans\\n\\n    def test_graph_interrupt_closes_span_without_error(self):\\n        \\\"\\\"\\\"A LangGraph interrupt (HITL pause) closes the span with error=None so the trace stays ok.\\\"\\\"\\\"\\n\\n        class GraphInterrupt(Exception):  # noqa: N818  # mirrors LangGraph's real class name (detected by name)\\n            pass\\n\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n        handler.on_chain_error(GraphInterrupt(\\\"paused for human input\\\"), run_id=run_id)\\n\\n        call_kwargs = mock_tracer.end_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"error\\\"] is None\\n        assert run_id not in handler._spans\\n\\n\\n# ---------------------------------------------------------------------------\\n# Tool callbacks\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestToolCallbacks:\\n    def test_on_tool_start_calls_add_langchain_span(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler.on_tool_start(\\n            serialized={\\\"name\\\": \\\"SearchTool\\\"},\\n            input_str=\\\"query\\\",\\n            run_id=run_id,\\n        )\\n        mock_tracer.add_langchain_span.assert_called_once()\\n        call_kwargs = mock_tracer.add_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"span_type\\\"] == \\\"tool\\\"\\n        assert call_kwargs[\\\"name\\\"] == \\\"SearchTool\\\"\\n\\n    def test_on_tool_start_uses_inputs_dict_when_provided(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler.on_tool_start(\\n            serialized={\\\"name\\\": \\\"Tool\\\"},\\n            input_str=\\\"fallback\\\",\\n            run_id=run_id,\\n            inputs={\\\"query\\\": \\\"actual input\\\"},\\n        )\\n        call_kwargs = mock_tracer.add_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"inputs\\\"] == {\\\"query\\\": \\\"actual input\\\"}\\n\\n    def test_on_tool_start_falls_back_to_input_str(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler.on_tool_start(\\n            serialized={\\\"name\\\": \\\"Tool\\\"},\\n            input_str=\\\"my query\\\",\\n            run_id=run_id,\\n        )\\n        call_kwargs = mock_tracer.add_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"inputs\\\"] == {\\\"input\\\": \\\"my query\\\"}\\n\\n    def test_on_tool_end_with_string_output(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n        handler.on_tool_end(\\\"search result\\\", run_id=run_id)\\n\\n        call_kwargs = mock_tracer.end_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"outputs\\\"] == {\\\"output\\\": \\\"search result\\\"}\\n\\n    def test_on_tool_end_with_dict_output(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n        handler.on_tool_end({\\\"result\\\": \\\"data\\\"}, run_id=run_id)\\n\\n        call_kwargs = mock_tracer.end_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"outputs\\\"] == {\\\"output\\\": {\\\"result\\\": \\\"data\\\"}}\\n\\n    def test_on_tool_end_cleans_up_run(self):\\n        handler, _mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n        handler.on_tool_end(\\\"result\\\", run_id=run_id)\\n        assert run_id not in handler._spans\\n\\n    def test_on_tool_error_calls_end_langchain_span_with_error(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n        handler.on_tool_error(RuntimeError(\\\"tool failed\\\"), run_id=run_id)\\n\\n        call_kwargs = mock_tracer.end_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"error\\\"] == \\\"tool failed\\\"\\n\\n    def test_on_tool_error_cleans_up_run(self):\\n        handler, _mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n        handler.on_tool_error(RuntimeError(\\\"err\\\"), run_id=run_id)\\n        assert run_id not in handler._spans\\n\\n\\n# ---------------------------------------------------------------------------\\n# Retriever callbacks\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestRetrieverCallbacks:\\n    def test_on_retriever_start_calls_add_langchain_span(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler.on_retriever_start(\\n            serialized={\\\"name\\\": \\\"VectorStoreRetriever\\\"},\\n            query=\\\"find docs\\\",\\n            run_id=run_id,\\n        )\\n        mock_tracer.add_langchain_span.assert_called_once()\\n        call_kwargs = mock_tracer.add_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"span_type\\\"] == \\\"retriever\\\"\\n        assert call_kwargs[\\\"inputs\\\"] == {\\\"query\\\": \\\"find docs\\\"}\\n\\n    def test_on_retriever_start_uses_id_list_fallback(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler.on_retriever_start(\\n            serialized={\\\"id\\\": [\\\"langchain\\\", \\\"MyRetriever\\\"]},\\n            query=\\\"q\\\",\\n            run_id=run_id,\\n        )\\n        call_kwargs = mock_tracer.add_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"name\\\"] == \\\"MyRetriever\\\"\\n\\n    def test_on_retriever_end_serializes_documents(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n\\n        doc1 = MagicMock()\\n        doc1.page_content = \\\"content 1\\\"\\n        doc1.metadata = {\\\"source\\\": \\\"file.txt\\\"}\\n        doc2 = MagicMock()\\n        doc2.page_content = \\\"content 2\\\"\\n        doc2.metadata = {}\\n\\n        handler.on_retriever_end([doc1, doc2], run_id=run_id)\\n\\n        call_kwargs = mock_tracer.end_langchain_span.call_args[1]\\n        docs = call_kwargs[\\\"outputs\\\"][\\\"documents\\\"]\\n        assert len(docs) == 2\\n        assert docs[0][\\\"page_content\\\"] == \\\"content 1\\\"\\n        assert docs[0][\\\"metadata\\\"] == {\\\"source\\\": \\\"file.txt\\\"}\\n        assert docs[1][\\\"page_content\\\"] == \\\"content 2\\\"\\n\\n    def test_on_retriever_end_handles_empty_documents(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n        handler.on_retriever_end([], run_id=run_id)\\n\\n        call_kwargs = mock_tracer.end_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"outputs\\\"][\\\"documents\\\"] == []\\n\\n    def test_on_retriever_end_cleans_up_run(self):\\n        handler, _mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n        handler.on_retriever_end([], run_id=run_id)\\n        assert run_id not in handler._spans\\n\\n    def test_on_retriever_error_calls_end_langchain_span_with_error(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n        handler.on_retriever_error(RuntimeError(\\\"retriever failed\\\"), run_id=run_id)\\n\\n        call_kwargs = mock_tracer.end_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"error\\\"] == \\\"retriever failed\\\"\\n\\n    def test_on_retriever_error_cleans_up_run(self):\\n        handler, _mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        handler._get_span_id(run_id)\\n        handler.on_retriever_error(RuntimeError(\\\"err\\\"), run_id=run_id)\\n        assert run_id not in handler._spans\\n\\n\\n# ---------------------------------------------------------------------------\\n# Parent span ID propagation\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestParentSpanPropagation:\\n    def test_parent_span_id_used_when_no_parent_run(self):\\n        parent_id = uuid4()\\n        handler, mock_tracer = _make_handler(parent_span_id=parent_id)\\n        run_id = uuid4()\\n\\n        handler.on_chain_start(serialized={}, inputs={}, run_id=run_id)\\n\\n        call_kwargs = mock_tracer.add_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"parent_span_id\\\"] == parent_id\\n\\n    def test_parent_run_id_takes_precedence_over_parent_span_id(self):\\n        parent_id = uuid4()\\n        handler, mock_tracer = _make_handler(parent_span_id=parent_id)\\n\\n        parent_run_id = uuid4()\\n        child_run_id = uuid4()\\n        # Register parent run\\n        handler._get_span_id(parent_run_id)\\n        parent_span_id_from_run = handler._spans[parent_run_id][\\\"span_id\\\"]\\n\\n        handler.on_chain_start(\\n            serialized={},\\n            inputs={},\\n            run_id=child_run_id,\\n            parent_run_id=parent_run_id,\\n        )\\n\\n        call_kwargs = mock_tracer.add_langchain_span.call_args[1]\\n        # Should use the parent run's span id, not the handler's parent_span_id\\n        assert call_kwargs[\\\"parent_span_id\\\"] == parent_span_id_from_run\\n\\n    def test_no_parent_span_id_when_neither_provided(self):\\n        handler, mock_tracer = _make_handler(parent_span_id=None)\\n        run_id = uuid4()\\n\\n        handler.on_chain_start(serialized={}, inputs={}, run_id=run_id)\\n\\n        call_kwargs = mock_tracer.add_langchain_span.call_args[1]\\n        assert call_kwargs[\\\"parent_span_id\\\"] is None\\n\\n\\n# ---------------------------------------------------------------------------\\n# Agent callbacks (no-ops)\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestAgentCallbacks:\\n    def test_on_agent_action_does_not_call_tracer(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        action = MagicMock()\\n        # Should not raise and should not call tracer methods\\n        handler.on_agent_action(action, run_id=run_id)\\n        mock_tracer.add_langchain_span.assert_not_called()\\n        mock_tracer.end_langchain_span.assert_not_called()\\n\\n    def test_on_agent_finish_does_not_call_tracer(self):\\n        handler, mock_tracer = _make_handler()\\n        run_id = uuid4()\\n        finish = MagicMock()\\n        handler.on_agent_finish(finish, run_id=run_id)\\n        mock_tracer.add_langchain_span.assert_not_called()\\n        mock_tracer.end_langchain_span.assert_not_called()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/tracing/test_native_tracer.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"43b9ed6112bd04f8f9f1ec63b42ab4c483f6eca5db021e1718bb80f8a284cd70\",\"content\":\"\\\"\\\"\\\"Unit tests for NativeTracer and NativeCallbackHandler.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport asyncio\\nimport os\\nfrom datetime import datetime, timezone\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\nfrom uuid import UUID, uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.traces.model import SpanStatus, SpanType\\nfrom langflow.services.tracing.native import NativeTracer\\nfrom langflow.services.tracing.span_sorting import resolve_span_uuids, topological_sort_spans\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _make_tracer(\\n    flow_id: str | None = None,\\n    session_id: str | None = None,\\n    trace_id: UUID | None = None,\\n) -> NativeTracer:\\n    tid = trace_id or uuid4()\\n    return NativeTracer(\\n        trace_name=f\\\"Test Flow - {flow_id or 'flow-123'}\\\",\\n        trace_type=\\\"chain\\\",\\n        project_name=\\\"test-project\\\",\\n        trace_id=tid,\\n        flow_id=flow_id or \\\"flow-123\\\",\\n        user_id=\\\"user-1\\\",\\n        session_id=session_id,\\n    )\\n\\n\\n# ---------------------------------------------------------------------------\\n# _is_enabled / ready\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestIsEnabled:\\n    def test_enabled_by_default(self):\\n        with patch.dict(os.environ, {}, clear=False):\\n            os.environ.pop(\\\"LANGFLOW_NATIVE_TRACING\\\", None)\\n            assert NativeTracer._is_enabled() is True\\n\\n    @pytest.mark.parametrize(\\\"value\\\", [\\\"false\\\", \\\"False\\\", \\\"FALSE\\\", \\\"0\\\", \\\"no\\\"])\\n    def test_disabled_by_env_var(self, value):\\n        with patch.dict(os.environ, {\\\"LANGFLOW_NATIVE_TRACING\\\": value}):\\n            assert NativeTracer._is_enabled() is False\\n\\n    @pytest.mark.parametrize(\\\"value\\\", [\\\"true\\\", \\\"True\\\", \\\"1\\\", \\\"yes\\\"])\\n    def test_enabled_by_env_var(self, value):\\n        with patch.dict(os.environ, {\\\"LANGFLOW_NATIVE_TRACING\\\": value}):\\n            assert NativeTracer._is_enabled() is True\\n\\n    def test_ready_property_reflects_is_enabled(self):\\n        with patch.dict(os.environ, {\\\"LANGFLOW_NATIVE_TRACING\\\": \\\"false\\\"}):\\n            tracer = _make_tracer()\\n            assert tracer.ready is False\\n\\n        with patch.dict(os.environ, {\\\"LANGFLOW_NATIVE_TRACING\\\": \\\"true\\\"}):\\n            tracer = _make_tracer()\\n            assert tracer.ready is True\\n\\n\\n# ---------------------------------------------------------------------------\\n# __init__ defaults\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestInit:\\n    def test_session_id_defaults_to_trace_id(self):\\n        tid = uuid4()\\n        tracer = NativeTracer(\\n            trace_name=\\\"Flow\\\",\\n            trace_type=\\\"chain\\\",\\n            project_name=\\\"proj\\\",\\n            trace_id=tid,\\n            flow_id=\\\"flow-1\\\",\\n            session_id=None,\\n        )\\n        assert tracer.session_id == str(tid)\\n\\n    def test_session_id_uses_provided_value(self):\\n        tracer = _make_tracer(session_id=\\\"my-session\\\")\\n        assert tracer.session_id == \\\"my-session\\\"\\n\\n    def test_flow_id_extracted_from_trace_name_when_not_provided(self):\\n        tid = uuid4()\\n        tracer = NativeTracer(\\n            trace_name=\\\"My Flow - flow-abc\\\",\\n            trace_type=\\\"chain\\\",\\n            project_name=\\\"proj\\\",\\n            trace_id=tid,\\n            flow_id=None,\\n        )\\n        assert tracer.flow_id == \\\"flow-abc\\\"\\n\\n    def test_flow_id_uses_full_trace_name_when_no_separator(self):\\n        tid = uuid4()\\n        tracer = NativeTracer(\\n            trace_name=\\\"NoSeparatorHere\\\",\\n            trace_type=\\\"chain\\\",\\n            project_name=\\\"proj\\\",\\n            trace_id=tid,\\n            flow_id=None,\\n        )\\n        assert tracer.flow_id == \\\"NoSeparatorHere\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# add_trace / end_trace\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestAddEndTrace:\\n    def test_add_trace_stores_span(self):\\n        tracer = _make_tracer()\\n        tracer.add_trace(\\n            trace_id=\\\"comp-1\\\",\\n            trace_name=\\\"My Component (comp-1)\\\",\\n            trace_type=\\\"chain\\\",\\n            inputs={\\\"key\\\": \\\"value\\\"},\\n            metadata={\\\"meta\\\": \\\"data\\\"},\\n        )\\n        assert \\\"comp-1\\\" in tracer.spans\\n        span = tracer.spans[\\\"comp-1\\\"]\\n        assert span[\\\"name\\\"] == \\\"My Component\\\"\\n        assert span[\\\"inputs\\\"] == {\\\"key\\\": \\\"value\\\"}\\n\\n    def test_add_trace_sets_current_component_id(self):\\n        tracer = _make_tracer()\\n        tracer.add_trace(\\\"comp-1\\\", \\\"Comp (comp-1)\\\", \\\"chain\\\", {})\\n        assert tracer._current_component_id == \\\"comp-1\\\"\\n\\n    def test_add_trace_noop_when_not_ready(self):\\n        with patch.dict(os.environ, {\\\"LANGFLOW_NATIVE_TRACING\\\": \\\"false\\\"}):\\n            tracer = _make_tracer()\\n        tracer.add_trace(\\\"comp-1\\\", \\\"Comp\\\", \\\"chain\\\", {})\\n        assert \\\"comp-1\\\" not in tracer.spans\\n\\n    def test_end_trace_moves_span_to_completed(self):\\n        tracer = _make_tracer()\\n        tracer.add_trace(\\\"comp-1\\\", \\\"My Component (comp-1)\\\", \\\"chain\\\", {\\\"in\\\": \\\"val\\\"})\\n        tracer.end_trace(\\\"comp-1\\\", \\\"My Component\\\", outputs={\\\"out\\\": \\\"result\\\"})\\n\\n        assert \\\"comp-1\\\" not in tracer.spans\\n        assert len(tracer.completed_spans) == 1\\n        span = tracer.completed_spans[0]\\n        assert span[\\\"name\\\"] == \\\"My Component\\\"\\n        assert span[\\\"status\\\"] == SpanStatus.OK\\n        assert span[\\\"outputs\\\"] == {\\\"out\\\": \\\"result\\\"}\\n        assert span[\\\"error\\\"] is None\\n\\n    def test_end_trace_with_error(self):\\n        tracer = _make_tracer()\\n        tracer.add_trace(\\\"comp-1\\\", \\\"Comp (comp-1)\\\", \\\"chain\\\", {})\\n        err = ValueError(\\\"something broke\\\")\\n        tracer.end_trace(\\\"comp-1\\\", \\\"Comp\\\", error=err)\\n\\n        span = tracer.completed_spans[0]\\n        assert span[\\\"status\\\"] == SpanStatus.ERROR\\n        assert span[\\\"error\\\"] == \\\"something broke\\\"\\n        assert span[\\\"outputs\\\"][\\\"error\\\"] == \\\"something broke\\\"\\n\\n    def test_end_trace_with_logs(self):\\n        tracer = _make_tracer()\\n        tracer.add_trace(\\\"comp-1\\\", \\\"Comp (comp-1)\\\", \\\"chain\\\", {})\\n        log = MagicMock()\\n        log.model_dump.return_value = {\\\"message\\\": \\\"log entry\\\"}\\n        tracer.end_trace(\\\"comp-1\\\", \\\"Comp\\\", logs=[log])\\n\\n        span = tracer.completed_spans[0]\\n        assert span[\\\"outputs\\\"][\\\"logs\\\"] == [{\\\"message\\\": \\\"log entry\\\"}]\\n\\n    def test_end_trace_noop_for_unknown_trace_id(self):\\n        tracer = _make_tracer()\\n        tracer.end_trace(\\\"nonexistent\\\", \\\"Comp\\\")\\n        assert len(tracer.completed_spans) == 0\\n\\n    def test_end_trace_noop_when_not_ready(self):\\n        with patch.dict(os.environ, {\\\"LANGFLOW_NATIVE_TRACING\\\": \\\"false\\\"}):\\n            tracer = _make_tracer()\\n        tracer.end_trace(\\\"comp-1\\\", \\\"Comp\\\")\\n        assert len(tracer.completed_spans) == 0\\n\\n    def test_end_trace_clears_current_component_id(self):\\n        tracer = _make_tracer()\\n        tracer.add_trace(\\\"comp-1\\\", \\\"Comp (comp-1)\\\", \\\"chain\\\", {})\\n        tracer.end_trace(\\\"comp-1\\\", \\\"Comp\\\")\\n        assert tracer._current_component_id is None\\n\\n\\nclass TestFinalizePendingSpans:\\n    \\\"\\\"\\\"Force-completion of spans that started but never received an end_trace.\\n\\n    A span whose end event raced the trace worker teardown must still be flushed, otherwise\\n    the terminal component (e.g. Chat Output) is silently missing from the persisted trace.\\n    \\\"\\\"\\\"\\n\\n    def test_pending_span_is_force_completed(self):\\n        tracer = _make_tracer()\\n        tracer.add_trace(\\\"out-1\\\", \\\"Chat Output (out-1)\\\", \\\"chain\\\", {\\\"in\\\": \\\"val\\\"})\\n        tracer.end_trace(\\\"comp-1\\\", \\\"Other\\\")  # noop; out-1 deliberately left unended\\n\\n        tracer._finalize_pending_spans()\\n\\n        assert \\\"out-1\\\" not in tracer.spans\\n        names = [s[\\\"name\\\"] for s in tracer.completed_spans]\\n        assert \\\"Chat Output\\\" in names\\n        span = next(s for s in tracer.completed_spans if s[\\\"name\\\"] == \\\"Chat Output\\\")\\n        assert span[\\\"status\\\"] == SpanStatus.OK\\n        assert span[\\\"inputs\\\"] == {\\\"in\\\": \\\"val\\\"}\\n\\n    def test_already_ended_spans_are_untouched(self):\\n        tracer = _make_tracer()\\n        tracer.add_trace(\\\"comp-1\\\", \\\"Comp (comp-1)\\\", \\\"chain\\\", {})\\n        tracer.end_trace(\\\"comp-1\\\", \\\"Comp\\\", outputs={\\\"out\\\": \\\"x\\\"})\\n\\n        tracer._finalize_pending_spans()\\n\\n        assert len(tracer.completed_spans) == 1\\n        assert tracer.completed_spans[0][\\\"outputs\\\"] == {\\\"out\\\": \\\"x\\\"}\\n\\n    def test_noop_when_no_pending_spans(self):\\n        tracer = _make_tracer()\\n        tracer._finalize_pending_spans()\\n        assert tracer.completed_spans == []\\n\\n    def test_end_trace_includes_token_attributes(self):\\n        tracer = _make_tracer()\\n        tracer.add_trace(\\\"comp-1\\\", \\\"Comp (comp-1)\\\", \\\"llm\\\", {})\\n        # Simulate token accumulation from a child LangChain span\\n        tracer._component_tokens[\\\"comp-1\\\"] = {\\n            \\\"gen_ai.usage.input_tokens\\\": 10,\\n            \\\"gen_ai.usage.output_tokens\\\": 20,\\n        }\\n        tracer.end_trace(\\\"comp-1\\\", \\\"Comp\\\")\\n\\n        span = tracer.completed_spans[0]\\n        assert span[\\\"attributes\\\"][\\\"gen_ai.usage.input_tokens\\\"] == 10\\n        assert span[\\\"attributes\\\"][\\\"gen_ai.usage.output_tokens\\\"] == 20\\n\\n    def test_end_trace_no_token_attributes_when_zero(self):\\n        tracer = _make_tracer()\\n        tracer.add_trace(\\\"comp-1\\\", \\\"Comp (comp-1)\\\", \\\"chain\\\", {})\\n        tracer.end_trace(\\\"comp-1\\\", \\\"Comp\\\")\\n\\n        span = tracer.completed_spans[0]\\n        assert \\\"prompt_tokens\\\" not in span[\\\"attributes\\\"]\\n        assert \\\"total_tokens\\\" not in span[\\\"attributes\\\"]\\n\\n\\n# ---------------------------------------------------------------------------\\n# _map_trace_type\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestMapTraceType:\\n    @pytest.mark.parametrize(\\n        (\\\"input_type\\\", \\\"expected\\\"),\\n        [\\n            (\\\"chain\\\", SpanType.CHAIN),\\n            (\\\"llm\\\", SpanType.LLM),\\n            (\\\"tool\\\", SpanType.TOOL),\\n            (\\\"retriever\\\", SpanType.RETRIEVER),\\n            (\\\"embedding\\\", SpanType.EMBEDDING),\\n            (\\\"parser\\\", SpanType.PARSER),\\n            (\\\"agent\\\", SpanType.AGENT),\\n            (\\\"CHAIN\\\", SpanType.CHAIN),\\n            (\\\"LLM\\\", SpanType.LLM),\\n            (\\\"unknown_type\\\", SpanType.CHAIN),  # fallback\\n            (\\\"\\\", SpanType.CHAIN),  # fallback\\n        ],\\n    )\\n    def test_map_trace_type(self, input_type, expected):\\n        assert NativeTracer._map_trace_type(input_type) == expected\\n\\n\\n# ---------------------------------------------------------------------------\\n# end() \u2014 scheduling flush task\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestEnd:\\n    @pytest.mark.asyncio\\n    async def test_end_creates_flush_task(self):\\n        tracer = _make_tracer()\\n        tracer.add_trace(\\\"comp-1\\\", \\\"Comp (comp-1)\\\", \\\"chain\\\", {})\\n        tracer.end_trace(\\\"comp-1\\\", \\\"Comp\\\", outputs={\\\"out\\\": \\\"val\\\"})\\n\\n        with patch.object(tracer, \\\"_flush_to_database\\\", new_callable=AsyncMock) as mock_flush:\\n            mock_flush.return_value = None\\n            tracer.end(inputs={}, outputs={})\\n            assert tracer._flush_task is not None\\n            await tracer._flush_task\\n\\n        mock_flush.assert_called_once()\\n\\n    @pytest.mark.asyncio\\n    async def test_end_noop_when_not_ready(self):\\n        with patch.dict(os.environ, {\\\"LANGFLOW_NATIVE_TRACING\\\": \\\"false\\\"}):\\n            tracer = _make_tracer()\\n        tracer.end(inputs={}, outputs={})\\n        assert tracer._flush_task is None\\n\\n    def test_end_logs_error_when_no_event_loop(self):\\n        tracer = _make_tracer()\\n        tracer.add_trace(\\\"comp-1\\\", \\\"Comp (comp-1)\\\", \\\"chain\\\", {})\\n        tracer.end_trace(\\\"comp-1\\\", \\\"Comp\\\")\\n\\n        with patch(\\\"langflow.services.tracing.native.logger\\\") as mock_logger:\\n            with patch(\\\"asyncio.get_running_loop\\\", side_effect=RuntimeError(\\\"no loop\\\")):\\n                tracer.end(inputs={}, outputs={})\\n            mock_logger.error.assert_called_once()\\n            assert tracer._flush_task is None\\n\\n\\n# ---------------------------------------------------------------------------\\n# wait_for_flush\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestWaitForFlush:\\n    @pytest.mark.asyncio\\n    async def test_wait_for_flush_awaits_task(self):\\n        tracer = _make_tracer()\\n        completed = []\\n\\n        async def fake_flush():\\n            completed.append(True)\\n\\n        tracer._flush_task = asyncio.create_task(fake_flush())\\n        await tracer.wait_for_flush()\\n        assert completed == [True]\\n\\n    @pytest.mark.asyncio\\n    async def test_wait_for_flush_noop_when_no_task(self):\\n        tracer = _make_tracer()\\n        # Should not raise\\n        await tracer.wait_for_flush()\\n\\n    @pytest.mark.asyncio\\n    async def test_wait_for_flush_swallows_task_exception(self):\\n        tracer = _make_tracer()\\n\\n        async def failing_flush():\\n            msg = \\\"flush error\\\"\\n            raise RuntimeError(msg)\\n\\n        tracer._flush_task = asyncio.create_task(failing_flush())\\n        # Should not raise\\n        await tracer.wait_for_flush()\\n\\n\\n# ---------------------------------------------------------------------------\\n# _flush_to_database\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestFlushToDatabase:\\n    @pytest.mark.asyncio\\n    async def test_flush_invalid_flow_id_logs_error_and_continues(self):\\n        tracer = _make_tracer(flow_id=\\\"not-a-uuid\\\")\\n        tracer.add_trace(\\\"comp-1\\\", \\\"Comp (comp-1)\\\", \\\"chain\\\", {})\\n        tracer.end_trace(\\\"comp-1\\\", \\\"Comp\\\")\\n\\n        mock_session = AsyncMock()\\n        mock_session.__aenter__ = AsyncMock(return_value=mock_session)\\n        mock_session.__aexit__ = AsyncMock(return_value=False)\\n\\n        with (\\n            patch(\\\"langflow.services.tracing.native.logger\\\") as mock_logger,\\n            patch(\\\"lfx.services.deps.session_scope\\\", return_value=mock_session),\\n        ):\\n            await tracer._flush_to_database()\\n\\n        mock_logger.error.assert_called_once()\\n        # Verify it continued and attempted to persist with a sentinel flow_id\\n        assert mock_session.merge.call_count >= 2\\n\\n    @pytest.mark.asyncio\\n    async def test_flush_writes_trace_and_spans(self):\\n        flow_id = str(uuid4())\\n        tracer = _make_tracer(flow_id=flow_id)\\n        tracer.add_trace(\\\"comp-1\\\", \\\"Comp (comp-1)\\\", \\\"chain\\\", {\\\"in\\\": \\\"val\\\"})\\n        tracer.end_trace(\\\"comp-1\\\", \\\"Comp\\\", outputs={\\\"out\\\": \\\"result\\\"})\\n\\n        mock_session = AsyncMock()\\n        mock_session.__aenter__ = AsyncMock(return_value=mock_session)\\n        mock_session.__aexit__ = AsyncMock(return_value=False)\\n\\n        with patch(\\\"lfx.services.deps.session_scope\\\", return_value=mock_session):\\n            await tracer._flush_to_database()\\n\\n        # merge should be called at least twice: once for trace, once for span\\n        assert mock_session.merge.call_count >= 2\\n\\n    @pytest.mark.asyncio\\n    async def test_flush_uses_uuid5_for_non_uuid_span_id(self):\\n        flow_id = str(uuid4())\\n        tracer = _make_tracer(flow_id=flow_id)\\n        # Manually add a completed span with a non-UUID string id\\n        tracer.completed_spans.append(\\n            {\\n                \\\"id\\\": \\\"not-a-uuid-string\\\",\\n                \\\"name\\\": \\\"Span\\\",\\n                \\\"span_type\\\": SpanType.CHAIN,\\n                \\\"inputs\\\": {},\\n                \\\"outputs\\\": None,\\n                \\\"start_time\\\": datetime.now(tz=timezone.utc),\\n                \\\"end_time\\\": datetime.now(tz=timezone.utc),\\n                \\\"latency_ms\\\": 10,\\n                \\\"status\\\": SpanStatus.OK,\\n                \\\"error\\\": None,\\n                \\\"attributes\\\": {},\\n            }\\n        )\\n\\n        mock_session = AsyncMock()\\n        mock_session.__aenter__ = AsyncMock(return_value=mock_session)\\n        mock_session.__aexit__ = AsyncMock(return_value=False)\\n\\n        with patch(\\\"lfx.services.deps.session_scope\\\", return_value=mock_session):\\n            # Should not raise even with non-UUID span id\\n            await tracer._flush_to_database()\\n\\n        assert mock_session.merge.call_count >= 1\\n\\n    @pytest.mark.asyncio\\n    async def test_flush_error_status_when_span_has_error(self):\\n        flow_id = str(uuid4())\\n        tracer = _make_tracer(flow_id=flow_id)\\n        tracer.add_trace(\\\"comp-1\\\", \\\"Comp (comp-1)\\\", \\\"chain\\\", {})\\n        tracer.end_trace(\\\"comp-1\\\", \\\"Comp\\\", error=ValueError(\\\"boom\\\"))\\n\\n        captured_traces = []\\n\\n        mock_session = AsyncMock()\\n        mock_session.__aenter__ = AsyncMock(return_value=mock_session)\\n        mock_session.__aexit__ = AsyncMock(return_value=False)\\n\\n        async def capture_merge(obj):\\n            captured_traces.append(obj)\\n\\n        mock_session.merge = capture_merge\\n\\n        with patch(\\\"lfx.services.deps.session_scope\\\", return_value=mock_session):\\n            await tracer._flush_to_database()\\n\\n        # First merged object is the TraceTable\\n        from langflow.services.database.models.traces.model import TraceTable\\n\\n        trace_obj = next((o for o in captured_traces if isinstance(o, TraceTable)), None)\\n        assert trace_obj is not None\\n        assert trace_obj.status == SpanStatus.ERROR\\n\\n    @pytest.mark.asyncio\\n    async def test_flush_calculates_total_tokens_from_spans(self):\\n        flow_id = str(uuid4())\\n        tracer = _make_tracer(flow_id=flow_id)\\n        tracer.completed_spans = [\\n            {\\n                \\\"id\\\": str(uuid4()),\\n                \\\"name\\\": \\\"Span1\\\",\\n                \\\"span_type\\\": SpanType.LLM,\\n                \\\"inputs\\\": {},\\n                \\\"outputs\\\": None,\\n                \\\"start_time\\\": datetime.now(tz=timezone.utc),\\n                \\\"end_time\\\": datetime.now(tz=timezone.utc),\\n                \\\"latency_ms\\\": 10,\\n                \\\"status\\\": SpanStatus.OK,\\n                \\\"error\\\": None,\\n                \\\"attributes\\\": {\\\"gen_ai.usage.input_tokens\\\": 30, \\\"gen_ai.usage.output_tokens\\\": 20},\\n                \\\"span_source\\\": \\\"langchain\\\",\\n            },\\n            {\\n                \\\"id\\\": str(uuid4()),\\n                \\\"name\\\": \\\"Span2\\\",\\n                \\\"span_type\\\": SpanType.LLM,\\n                \\\"inputs\\\": {},\\n                \\\"outputs\\\": None,\\n                \\\"start_time\\\": datetime.now(tz=timezone.utc),\\n                \\\"end_time\\\": datetime.now(tz=timezone.utc),\\n                \\\"latency_ms\\\": 5,\\n                \\\"status\\\": SpanStatus.OK,\\n                \\\"error\\\": None,\\n                \\\"attributes\\\": {\\\"gen_ai.usage.input_tokens\\\": 20, \\\"gen_ai.usage.output_tokens\\\": 10},\\n                \\\"span_source\\\": \\\"langchain\\\",\\n            },\\n        ]\\n\\n        captured_traces = []\\n        mock_session = AsyncMock()\\n        mock_session.__aenter__ = AsyncMock(return_value=mock_session)\\n        mock_session.__aexit__ = AsyncMock(return_value=False)\\n\\n        async def capture_merge(obj):\\n            captured_traces.append(obj)\\n\\n        mock_session.merge = capture_merge\\n\\n        with patch(\\\"lfx.services.deps.session_scope\\\", return_value=mock_session):\\n            await tracer._flush_to_database()\\n\\n        from langflow.services.database.models.traces.model import TraceTable\\n\\n        trace_obj = next((o for o in captured_traces if isinstance(o, TraceTable)), None)\\n        assert trace_obj is not None\\n        assert trace_obj.total_tokens == 80\\n\\n\\n# ---------------------------------------------------------------------------\\n# add_langchain_span / end_langchain_span\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestLangchainSpans:\\n    def test_add_langchain_span_stores_span(self):\\n        tracer = _make_tracer()\\n        span_id = uuid4()\\n        tracer.add_langchain_span(\\n            span_id=span_id,\\n            name=\\\"ChatOpenAI gpt-4\\\",\\n            span_type=\\\"llm\\\",\\n            inputs={\\\"prompts\\\": [\\\"hello\\\"]},\\n            model_name=\\\"gpt-4\\\",\\n        )\\n        assert span_id in tracer.langchain_spans\\n        assert tracer.langchain_spans[span_id][\\\"model_name\\\"] == \\\"gpt-4\\\"\\n\\n    def test_add_langchain_span_noop_when_not_ready(self):\\n        with patch.dict(os.environ, {\\\"LANGFLOW_NATIVE_TRACING\\\": \\\"false\\\"}):\\n            tracer = _make_tracer()\\n        span_id = uuid4()\\n        tracer.add_langchain_span(span_id, \\\"LLM\\\", \\\"llm\\\", {})\\n        assert span_id not in tracer.langchain_spans\\n\\n    def test_end_langchain_span_moves_to_completed(self):\\n        tracer = _make_tracer()\\n        span_id = uuid4()\\n        tracer.add_langchain_span(span_id, \\\"ChatOpenAI gpt-4\\\", \\\"llm\\\", {\\\"prompts\\\": [\\\"hi\\\"]})\\n        tracer.end_langchain_span(\\n            span_id=span_id,\\n            outputs={\\\"text\\\": \\\"response\\\"},\\n            prompt_tokens=10,\\n            completion_tokens=20,\\n            total_tokens=30,\\n        )\\n\\n        assert span_id not in tracer.langchain_spans\\n        assert len(tracer.completed_spans) == 1\\n        span = tracer.completed_spans[0]\\n        assert span[\\\"status\\\"] == SpanStatus.OK\\n        assert span[\\\"attributes\\\"][\\\"gen_ai.usage.input_tokens\\\"] == 10\\n        assert span[\\\"attributes\\\"][\\\"gen_ai.usage.output_tokens\\\"] == 20\\n\\n    def test_end_langchain_span_with_error(self):\\n        tracer = _make_tracer()\\n        span_id = uuid4()\\n        tracer.add_langchain_span(span_id, \\\"LLM\\\", \\\"llm\\\", {})\\n        tracer.end_langchain_span(span_id, error=\\\"timeout error\\\")\\n\\n        span = tracer.completed_spans[0]\\n        assert span[\\\"status\\\"] == SpanStatus.ERROR\\n        assert span[\\\"error\\\"] == \\\"timeout error\\\"\\n\\n    def test_end_langchain_span_accumulates_tokens_to_component(self):\\n        tracer = _make_tracer()\\n        tracer._current_component_id = \\\"comp-1\\\"\\n        span_id = uuid4()\\n        tracer.add_langchain_span(span_id, \\\"LLM\\\", \\\"llm\\\", {})\\n        tracer.end_langchain_span(\\n            span_id,\\n            prompt_tokens=5,\\n            completion_tokens=10,\\n            total_tokens=15,\\n        )\\n\\n        assert tracer._component_tokens[\\\"comp-1\\\"][\\\"gen_ai.usage.input_tokens\\\"] == 5\\n        assert tracer._component_tokens[\\\"comp-1\\\"][\\\"gen_ai.usage.output_tokens\\\"] == 10\\n\\n    def test_end_langchain_span_noop_for_unknown_span_id(self):\\n        tracer = _make_tracer()\\n        tracer.end_langchain_span(uuid4())\\n        assert len(tracer.completed_spans) == 0\\n\\n    def test_end_langchain_span_noop_when_not_ready(self):\\n        with patch.dict(os.environ, {\\\"LANGFLOW_NATIVE_TRACING\\\": \\\"false\\\"}):\\n            tracer = _make_tracer()\\n        tracer.end_langchain_span(uuid4())\\n        assert len(tracer.completed_spans) == 0\\n\\n    def test_end_langchain_span_includes_model_name_in_attributes(self):\\n        tracer = _make_tracer()\\n        span_id = uuid4()\\n        tracer.add_langchain_span(span_id, \\\"ChatOpenAI gpt-4\\\", \\\"llm\\\", {}, model_name=\\\"gpt-4\\\")\\n        tracer.end_langchain_span(span_id)\\n\\n        span = tracer.completed_spans[0]\\n        assert span[\\\"attributes\\\"][\\\"gen_ai.response.model\\\"] == \\\"gpt-4\\\"\\n\\n\\n# ---------------------------------------------------------------------------\\n# get_langchain_callback\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestGetLangchainCallback:\\n    def test_returns_none_when_not_ready(self):\\n        with patch.dict(os.environ, {\\\"LANGFLOW_NATIVE_TRACING\\\": \\\"false\\\"}):\\n            tracer = _make_tracer()\\n        assert tracer.get_langchain_callback() is None\\n\\n    def test_returns_callback_handler_when_ready(self):\\n        tracer = _make_tracer()\\n        callback = tracer.get_langchain_callback()\\n        assert callback is not None\\n        from langflow.services.tracing.native_callback import NativeCallbackHandler\\n\\n        assert isinstance(callback, NativeCallbackHandler)\\n\\n    def test_callback_has_parent_span_id_when_component_active(self):\\n        from langflow.services.tracing.native_callback import NativeCallbackHandler\\n\\n        tracer = _make_tracer()\\n        tracer._current_component_id = \\\"comp-1\\\"\\n        callback = tracer.get_langchain_callback()\\n        assert callback is not None\\n        assert isinstance(callback, NativeCallbackHandler)\\n        assert callback.parent_span_id is not None\\n\\n    def test_callback_has_no_parent_span_id_when_no_component(self):\\n        from langflow.services.tracing.native_callback import NativeCallbackHandler\\n\\n        tracer = _make_tracer()\\n        tracer._current_component_id = None\\n        callback = tracer.get_langchain_callback()\\n        assert callback is not None\\n        assert isinstance(callback, NativeCallbackHandler)\\n        assert callback.parent_span_id is None\\n\\n\\n# ---------------------------------------------------------------------------\\n# _topological_sort_spans\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestTopologicalSortSpans:\\n    \\\"\\\"\\\"Verify that spans are sorted so parents appear before children.\\n\\n    This is critical for PostgreSQL which enforces FK constraints at INSERT time.\\n    \\\"\\\"\\\"\\n\\n    @staticmethod\\n    def _make_span(span_id, parent_id=None) -> tuple[dict, UUID, UUID | None]:\\n        \\\"\\\"\\\"Helper to create a resolved (span_data, span_uuid, parent_uuid) tuple.\\\"\\\"\\\"\\n        span_data = {\\\"id\\\": str(span_id), \\\"name\\\": f\\\"span-{span_id}\\\"}\\n        return (span_data, span_id, parent_id)\\n\\n    def test_no_parents(self):\\n        a, b, c = uuid4(), uuid4(), uuid4()\\n        items = [self._make_span(a), self._make_span(b), self._make_span(c)]\\n        result = topological_sort_spans(items)\\n        assert [r[1] for r in result] == [a, b, c]\\n\\n    def test_child_after_parent(self):\\n        parent_id = uuid4()\\n        child_id = uuid4()\\n        # Child comes first in the input list\\n        items = [self._make_span(child_id, parent_id), self._make_span(parent_id)]\\n        result = topological_sort_spans(items)\\n        uuids = [r[1] for r in result]\\n        assert uuids.index(parent_id) < uuids.index(child_id)\\n\\n    def test_deep_nesting(self):\\n        root = uuid4()\\n        mid = uuid4()\\n        leaf = uuid4()\\n        # Reverse order: leaf, mid, root\\n        items = [\\n            self._make_span(leaf, mid),\\n            self._make_span(mid, root),\\n            self._make_span(root),\\n        ]\\n        result = topological_sort_spans(items)\\n        uuids = [r[1] for r in result]\\n        assert uuids.index(root) < uuids.index(mid) < uuids.index(leaf)\\n\\n    def test_parent_outside_batch(self):\\n        \\\"\\\"\\\"Spans referencing a missing parent are detached before insertion.\\\"\\\"\\\"\\n        external_parent = uuid4()\\n        child_id = uuid4()\\n        items = [self._make_span(child_id, external_parent)]\\n        result = topological_sort_spans(items)\\n        assert len(result) == 1\\n        assert result[0][1] == child_id\\n        assert result[0][2] is None\\n\\n    def test_mixed_roots_and_children(self):\\n        root_a = uuid4()\\n        child_a = uuid4()\\n        root_b = uuid4()\\n        items = [\\n            self._make_span(child_a, root_a),\\n            self._make_span(root_b),\\n            self._make_span(root_a),\\n        ]\\n        result = topological_sort_spans(items)\\n        uuids = [r[1] for r in result]\\n        assert uuids.index(root_a) < uuids.index(child_a)\\n\\n    def test_cycle_two_node(self):\\n        \\\"\\\"\\\"Spans forming a 2-node cycle should not cause errors or drop spans.\\\"\\\"\\\"\\n        a = uuid4()\\n        b = uuid4()\\n        items = [\\n            self._make_span(a, b),\\n            self._make_span(b, a),\\n        ]\\n        result = topological_sort_spans(items)\\n        # Ensure all spans are present and no infinite loop / exception occurs.\\n        uuids = [r[1] for r in result]\\n        assert len(uuids) == 2\\n        assert set(uuids) == {a, b}\\n\\n    def test_self_parent_span(self):\\n        \\\"\\\"\\\"A span that lists itself as its own parent should still be returned.\\\"\\\"\\\"\\n        span_id = uuid4()\\n        items = [\\n            self._make_span(span_id, span_id),\\n        ]\\n        result = topological_sort_spans(items)\\n        uuids = [r[1] for r in result]\\n        assert len(uuids) == 1\\n        assert uuids[0] == span_id\\n\\n    def test_empty_input(self):\\n        result = topological_sort_spans([])\\n        assert result == []\\n\\n    def test_cycle_does_not_mutate_original_span_data(self):\\n        \\\"\\\"\\\"Verify cycle resolution doesn't mutate the original span dicts.\\\"\\\"\\\"\\n        a = uuid4()\\n        b = uuid4()\\n        span_a = {\\\"id\\\": str(a), \\\"name\\\": \\\"span-a\\\", \\\"parent_span_id\\\": b}\\n        span_b = {\\\"id\\\": str(b), \\\"name\\\": \\\"span-b\\\", \\\"parent_span_id\\\": a}\\n        items = [(span_a, a, b), (span_b, b, a)]\\n        topological_sort_spans(items)\\n        # Original dicts should retain their parent_span_id values\\n        assert span_a[\\\"parent_span_id\\\"] == b\\n        assert span_b[\\\"parent_span_id\\\"] == a\\n\\n\\n# ---------------------------------------------------------------------------\\n# resolve_span_uuids\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestResolveSpanUuids:\\n    \\\"\\\"\\\"Verify UUID resolution for span IDs and parent IDs.\\\"\\\"\\\"\\n\\n    def test_valid_uuid_string_id(self):\\n        trace_id = uuid4()\\n        span_id = uuid4()\\n        spans = [{\\\"id\\\": str(span_id), \\\"name\\\": \\\"span\\\"}]\\n        result = resolve_span_uuids(spans, trace_id)\\n        assert len(result) == 1\\n        assert result[0][1] == span_id\\n        assert result[0][2] is None\\n\\n    def test_non_uuid_string_id_uses_uuid5(self):\\n        from uuid import uuid5 as _uuid5\\n\\n        from langflow.services.tracing.span_sorting import LANGFLOW_SPAN_NAMESPACE\\n\\n        trace_id = uuid4()\\n        spans = [{\\\"id\\\": \\\"not-a-uuid\\\", \\\"name\\\": \\\"span\\\"}]\\n        result = resolve_span_uuids(spans, trace_id)\\n        expected = _uuid5(LANGFLOW_SPAN_NAMESPACE, f\\\"{trace_id}-not-a-uuid\\\")\\n        assert result[0][1] == expected\\n\\n    def test_parent_as_uuid_instance(self):\\n        trace_id = uuid4()\\n        span_id = uuid4()\\n        parent_id = uuid4()\\n        spans = [{\\\"id\\\": str(span_id), \\\"name\\\": \\\"span\\\", \\\"parent_span_id\\\": parent_id}]\\n        result = resolve_span_uuids(spans, trace_id)\\n        assert result[0][2] == parent_id\\n\\n    def test_parent_as_valid_uuid_string(self):\\n        trace_id = uuid4()\\n        span_id = uuid4()\\n        parent_id = uuid4()\\n        spans = [{\\\"id\\\": str(span_id), \\\"name\\\": \\\"span\\\", \\\"parent_span_id\\\": str(parent_id)}]\\n        result = resolve_span_uuids(spans, trace_id)\\n        assert result[0][2] == parent_id\\n\\n    def test_parent_as_non_uuid_string(self):\\n        from uuid import uuid5 as _uuid5\\n\\n        from langflow.services.tracing.span_sorting import LANGFLOW_SPAN_NAMESPACE\\n\\n        trace_id = uuid4()\\n        span_id = uuid4()\\n        spans = [{\\\"id\\\": str(span_id), \\\"name\\\": \\\"span\\\", \\\"parent_span_id\\\": \\\"invalid-parent\\\"}]\\n        result = resolve_span_uuids(spans, trace_id)\\n        expected_parent = _uuid5(LANGFLOW_SPAN_NAMESPACE, f\\\"{trace_id}-invalid-parent\\\")\\n        assert result[0][2] == expected_parent\\n\\n    def test_no_parent_span_id_key(self):\\n        trace_id = uuid4()\\n        span_id = uuid4()\\n        spans = [{\\\"id\\\": str(span_id), \\\"name\\\": \\\"span\\\"}]\\n        result = resolve_span_uuids(spans, trace_id)\\n        assert result[0][2] is None\\n\\n    def test_empty_input(self):\\n        result = resolve_span_uuids([], uuid4())\\n        assert result == []\\n\\n\\n# ---------------------------------------------------------------------------\\n# _flush_to_database with parent/child spans\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestFlushParentChildOrder:\\n    @pytest.mark.asyncio\\n    async def test_flush_inserts_parent_before_child(self):\\n        \\\"\\\"\\\"Verify that the DB merge order respects parent -> child ordering.\\\"\\\"\\\"\\n        flow_id = str(uuid4())\\n        tracer = _make_tracer(flow_id=flow_id)\\n\\n        parent_uuid = uuid4()\\n        child_uuid = uuid4()\\n\\n        # Deliberately add child first to simulate the problematic ordering\\n        tracer.completed_spans = [\\n            {\\n                \\\"id\\\": str(child_uuid),\\n                \\\"name\\\": \\\"Child Span\\\",\\n                \\\"span_type\\\": SpanType.CHAIN,\\n                \\\"inputs\\\": {},\\n                \\\"outputs\\\": None,\\n                \\\"start_time\\\": datetime.now(tz=timezone.utc),\\n                \\\"end_time\\\": datetime.now(tz=timezone.utc),\\n                \\\"latency_ms\\\": 5,\\n                \\\"status\\\": SpanStatus.OK,\\n                \\\"error\\\": None,\\n                \\\"attributes\\\": {},\\n                \\\"span_source\\\": \\\"component\\\",\\n                \\\"parent_span_id\\\": parent_uuid,\\n            },\\n            {\\n                \\\"id\\\": str(parent_uuid),\\n                \\\"name\\\": \\\"Parent Span\\\",\\n                \\\"span_type\\\": SpanType.CHAIN,\\n                \\\"inputs\\\": {},\\n                \\\"outputs\\\": None,\\n                \\\"start_time\\\": datetime.now(tz=timezone.utc),\\n                \\\"end_time\\\": datetime.now(tz=timezone.utc),\\n                \\\"latency_ms\\\": 10,\\n                \\\"status\\\": SpanStatus.OK,\\n                \\\"error\\\": None,\\n                \\\"attributes\\\": {},\\n                \\\"span_source\\\": \\\"component\\\",\\n            },\\n        ]\\n\\n        merged_objects = []\\n        mock_session = AsyncMock()\\n        mock_session.__aenter__ = AsyncMock(return_value=mock_session)\\n        mock_session.__aexit__ = AsyncMock(return_value=False)\\n\\n        async def capture_merge(obj):\\n            merged_objects.append(obj)\\n\\n        mock_session.merge = capture_merge\\n\\n        with patch(\\\"lfx.services.deps.session_scope\\\", return_value=mock_session):\\n            await tracer._flush_to_database()\\n\\n        from langflow.services.database.models.traces.model import SpanTable\\n\\n        span_objects = [o for o in merged_objects if isinstance(o, SpanTable)]\\n        assert len(span_objects) == 2\\n        # Parent (no parent_span_id) must come before child\\n        assert span_objects[0].id == parent_uuid\\n        assert span_objects[1].id == child_uuid\\n        assert span_objects[1].parent_span_id == parent_uuid\\n\\n    async def test_flush_detaches_span_from_missing_parent(self):\\n        \\\"\\\"\\\"A missing parent must not leave an invalid self-referential FK.\\\"\\\"\\\"\\n        tracer = _make_tracer(flow_id=str(uuid4()))\\n        tracer.completed_spans = [\\n            {\\n                \\\"id\\\": str(uuid4()),\\n                \\\"name\\\": \\\"Orphan Span\\\",\\n                \\\"span_type\\\": SpanType.CHAIN,\\n                \\\"inputs\\\": {},\\n                \\\"outputs\\\": None,\\n                \\\"start_time\\\": datetime.now(tz=timezone.utc),\\n                \\\"end_time\\\": datetime.now(tz=timezone.utc),\\n                \\\"latency_ms\\\": 5,\\n                \\\"status\\\": SpanStatus.OK,\\n                \\\"error\\\": None,\\n                \\\"attributes\\\": {},\\n                \\\"span_source\\\": \\\"langchain\\\",\\n                \\\"parent_span_id\\\": uuid4(),\\n            }\\n        ]\\n\\n        merged_objects = []\\n        mock_session = AsyncMock()\\n        mock_session.__aenter__ = AsyncMock(return_value=mock_session)\\n        mock_session.__aexit__ = AsyncMock(return_value=False)\\n\\n        async def capture_merge(obj):\\n            merged_objects.append(obj)\\n\\n        mock_session.merge = capture_merge\\n\\n        with patch(\\\"lfx.services.deps.session_scope\\\", return_value=mock_session):\\n            await tracer._flush_to_database()\\n\\n        from langflow.services.database.models.traces.model import SpanTable\\n\\n        span_objects = [obj for obj in merged_objects if isinstance(obj, SpanTable)]\\n        assert len(span_objects) == 1\\n        assert span_objects[0].parent_span_id is None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/tracing/test_otel_fastapi_patch.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bd13768180f071c3d2b31d8e19e6fd90d63c7d022accc8d3163699bb10d1156a\",\"content\":\"\\\"\\\"\\\"Regression tests for the OpenTelemetry FastAPI route-detail compatibility patch.\\n\\nFastAPI 0.137 made ``include_router`` lazy, so ``app.routes`` now holds\\n``_IncludedRouter`` wrappers with no ``.path``. ``opentelemetry-instrumentation-fastapi``\\nreads ``route.path`` to name spans and crashed on a *partial* route match (e.g. a CORS\\npreflight / OPTIONS against a GET-only route). These tests pin the fix and are written to\\npass on both eager (<=0.136) and lazy (>=0.137) inclusion.\\n\\\"\\\"\\\"\\n\\nimport pytest\\nfrom fastapi import APIRouter, FastAPI\\nfrom fastapi.testclient import TestClient\\nfrom lfx.observability_fastapi import (\\n    _safe_get_route_details,\\n    patch_otel_fastapi_route_details,\\n)\\nfrom opentelemetry.instrumentation.fastapi import FastAPIInstrumentor\\n\\n\\ndef _build_app() -> FastAPI:\\n    sub = APIRouter()\\n\\n    @sub.get(\\\"/version\\\")\\n    def _version():\\n        return {\\\"version\\\": \\\"test\\\"}\\n\\n    app = FastAPI()\\n    app.include_router(sub, prefix=\\\"/api/v1\\\")\\n    return app\\n\\n\\ndef test_patch_is_idempotent():\\n    \\\"\\\"\\\"Applying the patch twice leaves a single guarded helper installed.\\\"\\\"\\\"\\n    import opentelemetry.instrumentation.fastapi as otel_fastapi\\n\\n    patch_otel_fastapi_route_details()\\n    first = otel_fastapi._get_route_details\\n    patch_otel_fastapi_route_details()\\n    second = otel_fastapi._get_route_details\\n\\n    assert first is second\\n    assert first is _safe_get_route_details\\n    assert getattr(otel_fastapi, \\\"_langflow_route_details_patched\\\", False) is True\\n\\n\\ndef test_safe_route_details_partial_match_does_not_raise():\\n    \\\"\\\"\\\"A partial (method-mismatch) match against a lazily-included route returns a label.\\n\\n    Pre-patch this raised ``AttributeError: '_IncludedRouter' object has no attribute 'path'``.\\n    \\\"\\\"\\\"\\n    app = _build_app()\\n    # OPTIONS is not an accepted method for the GET route -> partial match on the path.\\n    scope = {\\n        \\\"type\\\": \\\"http\\\",\\n        \\\"method\\\": \\\"OPTIONS\\\",\\n        \\\"path\\\": \\\"/api/v1/version\\\",\\n        \\\"headers\\\": [],\\n        \\\"app\\\": app,\\n    }\\n\\n    route = _safe_get_route_details(scope)\\n\\n    # Either the include prefix (lazy >=0.137) or the full templated path (eager <=0.136);\\n    # the contract is \\\"a non-crashing, request-relevant string\\\".\\n    assert route in {\\\"/api/v1\\\", \\\"/api/v1/version\\\"}\\n\\n\\ndef test_safe_route_details_full_match_returns_path():\\n    \\\"\\\"\\\"A full match still yields a usable route label.\\\"\\\"\\\"\\n    app = _build_app()\\n    scope = {\\n        \\\"type\\\": \\\"http\\\",\\n        \\\"method\\\": \\\"GET\\\",\\n        \\\"path\\\": \\\"/api/v1/version\\\",\\n        \\\"headers\\\": [],\\n        \\\"app\\\": app,\\n    }\\n\\n    route = _safe_get_route_details(scope)\\n\\n    assert route == \\\"/api/v1/version\\\"\\n\\n\\ndef test_instrumented_options_preflight_does_not_500():\\n    \\\"\\\"\\\"End-to-end: an OPTIONS preflight through the instrumented app no longer crashes.\\n\\n    This reproduces the production failure path (OTel ASGI middleware -> span route\\n    extraction) that turned a 405/preflight into a 500 under FastAPI >=0.137.\\n    \\\"\\\"\\\"\\n    patch_otel_fastapi_route_details()\\n    app = _build_app()\\n    FastAPIInstrumentor.instrument_app(app)\\n\\n    try:\\n        client = TestClient(app)\\n        response = client.options(\\n            \\\"/api/v1/version\\\",\\n            headers={\\n                \\\"Origin\\\": \\\"https://example.com\\\",\\n                \\\"Access-Control-Request-Method\\\": \\\"GET\\\",\\n            },\\n        )\\n        # No CORS middleware here, so an OPTIONS to a GET-only route is a clean 405 -\\n        # the point is the request flowed through OTel instrumentation without erroring.\\n        assert response.status_code != 500\\n        assert response.status_code == 405\\n\\n        # And a normal request still works end-to-end.\\n        ok = client.get(\\\"/api/v1/version\\\")\\n        assert ok.status_code == 200\\n        assert ok.json() == {\\\"version\\\": \\\"test\\\"}\\n    finally:\\n        FastAPIInstrumentor.uninstrument_app(app)\\n\\n\\n@pytest.mark.parametrize(\\\"method\\\", [\\\"OPTIONS\\\", \\\"DELETE\\\", \\\"PUT\\\"])\\ndef test_instrumented_method_mismatch_does_not_500(method):\\n    \\\"\\\"\\\"Any method-mismatch (partial match) on a lazily-included route stays a 405, not a 500.\\\"\\\"\\\"\\n    patch_otel_fastapi_route_details()\\n    app = _build_app()\\n    FastAPIInstrumentor.instrument_app(app)\\n\\n    try:\\n        client = TestClient(app)\\n        response = client.request(method, \\\"/api/v1/version\\\")\\n        assert response.status_code == 405\\n    finally:\\n        FastAPIInstrumentor.uninstrument_app(app)\\n\\n\\ndef _build_app_with_path_params() -> FastAPI:\\n    \\\"\\\"\\\"Mirror Langflow's shape: a router with path params, lazily included under /api/v1.\\\"\\\"\\\"\\n    router = APIRouter(prefix=\\\"/v1\\\")\\n\\n    @router.get(\\\"/flows/{flow_id}\\\")\\n    def read_flow(flow_id: str):\\n        return {\\\"id\\\": flow_id}\\n\\n    api = APIRouter(prefix=\\\"/api\\\")\\n    api.include_router(router)\\n    app = FastAPI()\\n    app.include_router(api)\\n    return app\\n\\n\\nFLOW_ID = \\\"357ea329-0775-4204-8161-d182c8c4edf5\\\"\\n\\n\\ndef test_route_label_is_templated_not_the_raw_path():\\n    \\\"\\\"\\\"The identifier must not survive into the route label.\\n\\n    Under the stable HTTP semantic conventions this value becomes ``http.route``, which is a\\n    metric label. Returning the raw path would mint one metric series per flow id. Langflow\\n    mounts every API route under a lazily-included router, so this is the common path.\\n    \\\"\\\"\\\"\\n    app = _build_app_with_path_params()\\n    scope = {\\n        \\\"type\\\": \\\"http\\\",\\n        \\\"method\\\": \\\"GET\\\",\\n        \\\"path\\\": f\\\"/api/v1/flows/{FLOW_ID}\\\",\\n        \\\"headers\\\": [],\\n        \\\"app\\\": app,\\n    }\\n\\n    route = _safe_get_route_details(scope)\\n\\n    assert route == \\\"/api/v1/flows/{flow_id}\\\"\\n    assert FLOW_ID not in route\\n\\n\\ndef test_route_label_cardinality_is_bounded_by_endpoint_count():\\n    \\\"\\\"\\\"Many distinct ids must collapse onto one label, which is the whole point.\\\"\\\"\\\"\\n    app = _build_app_with_path_params()\\n    labels = set()\\n    for i in range(50):\\n        scope = {\\n            \\\"type\\\": \\\"http\\\",\\n            \\\"method\\\": \\\"GET\\\",\\n            \\\"path\\\": f\\\"/api/v1/flows/00000000-0000-0000-0000-{i:012d}\\\",\\n            \\\"headers\\\": [],\\n            \\\"app\\\": app,\\n        }\\n        labels.add(_safe_get_route_details(scope))\\n\\n    assert labels == {\\\"/api/v1/flows/{flow_id}\\\"}\\n\\n\\ndef test_preflight_on_a_parameterised_route_is_also_templated():\\n    \\\"\\\"\\\"A method mismatch still resolves the endpoint rather than falling back to the path.\\\"\\\"\\\"\\n    app = _build_app_with_path_params()\\n    scope = {\\n        \\\"type\\\": \\\"http\\\",\\n        \\\"method\\\": \\\"OPTIONS\\\",\\n        \\\"path\\\": f\\\"/api/v1/flows/{FLOW_ID}\\\",\\n        \\\"headers\\\": [],\\n        \\\"app\\\": app,\\n    }\\n\\n    route = _safe_get_route_details(scope)\\n\\n    assert FLOW_ID not in (route or \\\"\\\")\\n    assert route in {\\\"/api/v1/flows/{flow_id}\\\", \\\"/api/v1\\\"}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/services/tracing/test_repository.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"35253c33bbb7c212e48f96d698fd2db17915a84fa09c386ec6a5548a6a42c777\",\"content\":\"\\\"\\\"\\\"Unit tests for langflow.services.tracing.repository.\\n\\nCovers:\\n- fetch_trace_summary_data: token aggregation, I/O extraction, empty input\\n- Pagination boundary math used by fetch_traces\\n- TraceSummaryData dataclass defaults\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport math\\nfrom unittest.mock import MagicMock\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.tracing.formatting import TraceSummaryData\\n\\n# ---------------------------------------------------------------------------\\n# Helpers\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _paginate(total_count: int, size: int) -> int:\\n    \\\"\\\"\\\"Mirror the pagination formula used in fetch_traces.\\\"\\\"\\\"\\n    return math.ceil(total_count / size) if total_count > 0 else 0\\n\\n\\n# ---------------------------------------------------------------------------\\n# TraceSummaryData defaults\\n# ---------------------------------------------------------------------------\\n\\n\\nclass TestTraceSummaryData:\\n    def test_should_have_zero_tokens_by_default(self):\\n        data = TraceSummaryData()\\n        assert data.total_tokens == 0\\n\\n    def test_should_have_none_input_by_default(self):\\n        data = TraceSummaryData()\\n        assert data.input is None\\n\\n    def test_should_have_none_output_by_default(self):\\n        data = TraceSummaryData()\\n        assert data.output is None\\n\\n    def test_should_accept_explicit_values(self):\\n        data = TraceSummaryData(\\n            total_tokens=42,\\n            input={\\\"input_value\\\": \\\"hello\\\"},\\n            output={\\\"result\\\": \\\"world\\\"},\\n        )\\n        assert data.total_tokens == 42\\n        assert data.input == {\\\"input_value\\\": \\\"hello\\\"}\\n        assert data.output == {\\\"result\\\": \\\"world\\\"}\\n\\n    def test_should_not_share_mutable_defaults_between_instances(self):\\n        \\\"\\\"\\\"Two instances must not share the same dict objects.\\\"\\\"\\\"\\n        a = TraceSummaryData(input={\\\"k\\\": \\\"v\\\"})\\n        b = TraceSummaryData(input={\\\"k\\\": \\\"v\\\"})\\n        assert a.input is not None\\n        assert b.input is not None\\n        a.input[\\\"extra\\\"] = \\\"mutated\\\"\\n        assert \\\"extra\\\" not in b.input\\n\\n\\n# -----------------------------------------------------------";
